insert into admin_payload values ($admin_30bccdce3e7e175f${"version":1,"checked_at":"2026-10-24T22:30:24.912384+00:00","actor":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","syllabus_topic":{"id":"9fc4243b-fe0f-461b-b705-57873fb33563","block_name":"Histórico 2026","created_at":"2026-09-28T03:22:06.477804+00:00","discipline":"Direito Administrativo","edition_id":"c0ea9fc5-d65d-4f8c-a936-729f8824a072","topic_text":"DIREITO ADMINISTRATIVO (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Conceito e Fontes do Direito Administrativo. 1.1. Objeto do Direito Administrativo. 1.2. Fontes formais e materiais. 1.3. Regime Jurídico Administrativo. 2. Princípios da Administração Pública. 2.1. Princípios expressos (art. 37, caput, da CF). 2.2. Princípios implícitos. 2.3. Disposições da Lei de Introdução às Normas do Direito Brasileiro (LINDB) aplicáveis ao Direito Administrativo (Lei nº 13.655/2018). 3. Administração Pública. 3.1. Conceitos. 3.2. Estrutura da Administração Pública. 3.3. Desconcentração e Descentralização. 3.4. Órgãos Públicos. 3.5. Agentes Públicos. 4. Atos Administrativos. 4.1. Conceito, Requisitos. 4.2. Atributos. 4.3. Classificação. 4.4. Espécies de Atos Administrativos. 4.5. Perfeição, Validade, Eficácia, Revogação, Anulação e Convalidação. 5. Poderes da Administração Pública. 5.1. Poder Hierárquico. 5.2. Poder Disciplinar. 5.3. Poder Regulamentar. 5.4. Poder de Polícia. 5.5. Abuso de Poder. 5.6. Lei nº 13.869/2019. 6. Organização Administrativa da Polícia Civil do Estado do Piauí. 6.1. Estrutura e atribuições conforme a Lei Complementar Estadual nº 37/2004 e a Lei Complementar Estadual nº 318/2025. 6.2. Regime Jurídico dos Servidores da Polícia Civil do Piauí. 7. Licitações e Contratos Administrativos. 7.1. Lei nº 14.133/2021. 7.2. Contratos Administrativos. 8. Serviços Públicos. 8.1. Conceito, classificação, princípios. 8.2. Formas de Prestação. 9. Responsabilidade Civil do Estado. 9.1. Evolução histórica. 9.2. Teoria do Risco Administrativo. 9.3. Causas excludentes e atenuantes. 9.4. Dano, nexo causal e conduta. 9.5. Responsabilidade por atos legislativos e judiciais. 9.6. Responsabilidade individual de agentes públicos. 10. Bens Públicos. 10.1. Conceito e Classificação. 10.2. Afetação e desafetação. 10.3. Regime jurídico. 10.4. Formas de utilização. 11. Intervenção do Estado na Propriedade Privada. 11.1. Limitações Administrativas. 11.2. Ocupação Temporária. 11.3. Servidão Administrativa. 11.4. Requisição Administrativa. 11.5. Tombamento. 11.6. Desapropriação. 12. Controle da Administração Pública. 12.1. Controle Interno e Externo. 12.2. Controle Legislativo. 12.3. Controle Jurisdicional. 12.4. Controle Administrativo. 13. Improbidade Administrativa.","topic_order":3,"content_status":"current"},"sources":[{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado","id":"31420f66-9c12-4787-bdc0-f55f77525880","status":"vigente","is_official":true,"source_type":"constituicao","issuer":"Presidência da República — Planalto"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal","id":"8899e260-3368-4340-a724-22b88c44893a","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"dl200","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","bytes":317662,"sha256":"dec522116c8f9d89b81089e0de6029a261e889b60d091b66b777ae44ce09b31d","checked_at":"2026-10-24T22:17:19.906607+00:00","title":"Decreto-Lei 200/1967 — organização administrativa federal","id":"550bafa1-aa0d-43d1-894c-d46a66bdbb5e","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais","id":"15494028-a541-44f7-8017-8316c239a213","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"l14133","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","bytes":649705,"sha256":"6e747b82f9d1f660beeda5c2a9b75e6ff3881d21bd92d2618c032cba4dbab13f","checked_at":"2026-10-24T22:17:18.861233+00:00","title":"Lei 14.133/2021 — licitações e contratos","id":"2f05830e-ced4-4f1e-8627-14aba60e81eb","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"l13303","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","bytes":248652,"sha256":"081e50a5e352f44fbf734df5da72be27d675c827d380126e990fb6b225b35f35","checked_at":"2026-10-24T22:17:17.994894+00:00","title":"Lei 13.303/2016 — estatais","id":"d4fe7ad5-fad7-42a0-b850-aa327aa80278","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"l8987","url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm","bytes":104378,"sha256":"17c0d572f435d9c836079f67c4a0156a5d692d3c564f94541ae7d14fed2c45c8","checked_at":"2026-10-24T22:17:17.353896+00:00","title":"Lei 8.987/1995 — concessões e permissões","id":"e6543f58-9a4f-5489-82c2-4516d5cedc1b","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"edital","url":"https://conhecimento.fgv.br/sites/default/files/concursos/edital_delegado.22.12_0.pdf","bytes":958250,"sha256":"a2f1676ecf38e22c2faef198420a071031b324831f4b488bdd276999a0725964","checked_at":"2026-10-24T22:17:16.667734+00:00","title":"Edital PCPI — Delegado — matriz cadastrada","id":"6d246b75-f48d-5433-804e-8c2999e120bb","status":"vigente","is_official":true,"source_type":"edital","issuer":"FGV / Polícia Civil do Piauí"},{"key":"stf_rju","url":"https://noticias.stf.jus.br/postsnoticias/stf-valida-emenda-que-flexibilizou-regime-de-contratacao-de-servidores-publicos/","bytes":68113,"sha256":"58bff730ef752dc9f63f9294d279a38011a79aaed3245797228d537d429ac1d3","checked_at":"2026-10-24T22:22:56.755614+00:00","title":"STF — ADI 2.135: regime de contratação de servidores","id":"e9bbafe6-8b76-5714-bf1d-9e3da46d7730","status":"vigente","is_official":true,"source_type":"jurisprudencia","issuer":"Supremo Tribunal Federal"}],"rows":[{"kind":"new","material":{"id":"09aed23b-bb87-56ea-b0f0-9a3b64d438ee","slug":"administrativo-fundamentos-fontes-regime-juridico","discipline":"Direito Administrativo","topic_label":"Fontes, regime jurídico e noções de Estado","sort_order":1,"title":"Fundamentos: fontes, regime jurídico e interesse público","summary":"Conceitos fundamentais com distinções de prova, fonte oficial atual, casos resolvidos e vinte exercícios comentados.","body_md":"## Como estudar o regime administrativo\n\nDireito Administrativo trata da organização e do exercício da função administrativa, de seus instrumentos e dos controles que protegem os administrados. A função administrativa não pertence exclusivamente ao Executivo: o Legislativo e o Judiciário também administram pessoal, serviços e contratos. A Lei 9.784/1999, art. 1º, § 1º, explicita essa aplicação no âmbito federal.\n\nNão confunda **regime da Administração** com **regime jurídico administrativo**. A Administração participa de relações sujeitas a diferentes regimes; a combinação de prerrogativas e sujeições de direito público é uma construção didática para compreender sua atuação. A presença do Estado numa relação não torna toda cláusula unilateral nem elimina direitos do particular.\n\n## Fontes e força de cada fundamento\n\n| Base utilizada | Como empregar |\n| --- | --- |\n| Constituição e legislação | Identifique a competência, a hipótese e os limites vigentes |\n| Regulamentos | Confira a autorização e a subordinação à Constituição e à lei; não suponha poder livre de inovar |\n| Jurisprudência | Verifique tribunal, tese, alcance e eventual efeito vinculante |\n| Doutrina | Utilize conceitos e classificações como explicações, distinguindo-os do texto legal |\n| Prática administrativa | Pode ajudar a interpretar procedimentos; não autoriza contrariar a lei |\n\nA afirmação de que “jurisprudência nunca é fonte” está errada. Também é impreciso tratar qualquer decisão como se tivesse a força de uma súmula vinculante: a Constituição disciplina essa última no art. 103-A. Para o procedimento federal, o art. 2º da Lei 9.784 exige atuação conforme a lei **e o Direito**, e não simples reprodução mecânica de um costume administrativo.\n\n## Interesse público: finalidade e limites\n\nA supremacia do interesse público é uma síntese doutrinária de determinadas prerrogativas destinadas à coletividade. Não é uma autorização genérica para afastar direitos fundamentais. Antes de restringir um direito, identifique fundamento jurídico, finalidade, necessidade, proporcionalidade e garantias de participação e defesa.\n\nA indisponibilidade significa que o gestor não é dono dos bens, poderes e interesses cuja gestão recebeu. O art. 2º, parágrafo único, II, da Lei 9.784 veda a renúncia total ou parcial de poderes ou competências, salvo autorização em lei. Isso não proíbe toda solução consensual: é preciso verificar a base legal e suas condições. Não confunda interesse da coletividade com conveniência financeira ou preferência pessoal do agente.\n\nLegalidade, impessoalidade, moralidade, publicidade e eficiência constam do art. 37, caput, da Constituição. Eficiência não dispensa legalidade; publicidade não autoriza expor qualquer dado protegido; motivação não se resume a mencionar “interesse público” sem explicar os fatos.\n\n## Estado, governo e Administração\n\nO Brasil é uma República Federativa e um Estado Democrático de Direito. União, estados, Distrito Federal e municípios têm **autonomia**, nos termos do art. 18. A soberania é atributo da República Federativa do Brasil, e não de cada município ou estado-membro.\n\nA referência didática a povo, território e poder soberano ajuda a estudar o Estado. Governo se relaciona à direção política; Administração, à organização e execução das atividades administrativas. Essa distinção não apaga controles nem estabelece separação absoluta entre decisões políticas e deveres jurídicos.\n\nNo presidencialismo brasileiro, a Constituição atribui competências ao Presidente e disciplina a relação entre Poderes. República, federação e democracia designam aspectos diferentes: não use uma expressão para responder a pergunta sobre outra. O art. 1º, parágrafo único, prevê exercício do poder por representantes eleitos **ou diretamente**, nos termos constitucionais.\n\n## Roteiro de resolução\n\n1. Identifique a pessoa jurídica, o órgão e a função exercida.\n2. Localize a norma aplicável e o âmbito federativo.\n3. Distinga regra legal de classificação doutrinária.\n4. Verifique finalidade, motivação e garantias do administrado.\n5. Só então conclua sobre a prerrogativa ou o controle cabível.\n\nContinue em [Organização administrativa](/dashboard/library/administrativo-organizacao-direta-indireta-orgaos), [Poderes administrativos](/dashboard/library/administrativo-poderes-vinculado-discricionario-hierarquico) e [Processo administrativo federal](/dashboard/library/administrativo-processo-administrativo-lei-9784).\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":3,"source_note":"Redação própria a partir dos assuntos identificados nos arquivos enviados e das fontes oficiais indicadas. Sem reprodução de identidade visual, publicidade ou comentários autorais das apostilas. Questões extraídas são catalogadas separadamente com origem didática. Aplicação em outros concursos depende de edital e data de corte.","legal_basis":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],"law_version_checked_at":"2026-10-24T22:30:24.912384+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00","quiz":[{"q":"A função administrativa também pode ser exercida por órgãos do Legislativo e do Judiciário.","a":true,"why":"A Lei 9.784 alcança esses órgãos da União no desempenho de função administrativa. Base: Art. 1º, § 1º."},{"q":"A Lei 9.784/1999 regula diretamente todo processo administrativo de qualquer município, independentemente de sua legislação.","a":false,"why":"A lei estabelece normas para a Administração Federal; a aplicação em outras esferas exige fundamento próprio. Base: Art. 1º."},{"q":"O princípio da eficiência permite dispensar a legalidade se a solução administrativa for mais rápida.","a":false,"why":"Legalidade e eficiência são exigências simultâneas, não uma autorização para agir contra a lei. Base: Art. 37, caput."},{"q":"A atuação conforme a lei e o Direito é critério expresso do processo administrativo federal.","a":true,"why":"O art. 2º, parágrafo único, I, utiliza essa formulação e exige interpretação jurídica compatível com as garantias. Base: Art. 2º, parágrafo único, I."},{"q":"Costume administrativo reiterado autoriza a autoridade a contrariar uma proibição legal expressa.","a":false,"why":"A repetição da prática não afasta o dever de observar a lei e o Direito. Base: Art. 2º, parágrafo único, I."},{"q":"Uma súmula vinculante e uma decisão judicial isolada têm necessariamente os mesmos requisitos e o mesmo alcance.","a":false,"why":"O art. 103-A disciplina especificamente aprovação, revisão, cancelamento e efeito vinculante da súmula. Base: Art. 103-A."},{"q":"A indisponibilidade impede renúncia de poderes ou competências, salvo autorização em lei.","a":true,"why":"Esse é o critério do art. 2º, parágrafo único, II; não se trata de proibir toda solução legalmente autorizada. Base: Art. 2º, parágrafo único, II."},{"q":"Invocar interesse público dispensa a indicação dos fatos em decisão federal que limita um direito.","a":false,"why":"O art. 50 exige motivação, com indicação dos fatos e fundamentos jurídicos, nessas hipóteses. Base: Art. 50, I."},{"q":"Razoabilidade e proporcionalidade integram os princípios expressos da Lei 9.784/1999.","a":true,"why":"São princípios expressamente enumerados no art. 2º, caput. Base: Art. 2º."},{"q":"A promoção pessoal do agente é finalidade legítima da atuação administrativa federal.","a":false,"why":"O art. 2º, parágrafo único, III, exige objetividade no interesse público e veda promoção pessoal. Base: Art. 2º, parágrafo único, III."},{"q":"Estados e municípios são autônomos; isso não os torna individualmente soberanos.","a":true,"why":"A autonomia dos entes consta do art. 18; a soberania é fundamento da República Federativa do Brasil. Base: Arts. 1º, I, e 18."},{"q":"Federação e república respondem à mesma classificação e são expressões intercambiáveis.","a":false,"why":"A federação trata da organização territorial do poder; república, da forma de governo. O art. 1º adota ambas. Base: Art. 1º."},{"q":"O poder popular somente pode ser exercido mediante representantes eleitos.","a":false,"why":"O art. 1º, parágrafo único, prevê também o exercício direto nos termos da Constituição. Base: Art. 1º, parágrafo único."},{"q":"A soberania é um dos fundamentos constitucionais da República Federativa do Brasil.","a":true,"why":"Consta do art. 1º, I; não se deve atribuí-la separadamente aos entes autônomos. Base: Art. 1º, I."},{"q":"A separação de Poderes elimina qualquer fiscalização recíproca prevista na Constituição.","a":false,"why":"A independência e harmonia do art. 2º convivem com controles constitucionais, como os dos arts. 70 e 71. Base: Arts. 2º, 70 e 71."},{"q":"A publicidade administrativa admite apenas divulgações compatíveis com as proteções constitucionais de intimidade e sigilo.","a":true,"why":"O art. 37 deve ser interpretado com o art. 5º, X e XXXIII; publicidade não significa exposição irrestrita. Base: Arts. 5º, X e XXXIII, e 37."},{"q":"O critério de proporcionalidade permite impor obrigação superior à estritamente necessária à finalidade pública.","a":false,"why":"O art. 2º, parágrafo único, VI, veda essa imposição excessiva. Base: Art. 2º, parágrafo único, VI."},{"q":"A Administração pode aplicar retroativamente nova interpretação administrativa em qualquer hipótese, por mera conveniência.","a":false,"why":"O art. 2º, parágrafo único, XIII, veda aplicação retroativa de nova interpretação. Base: Art. 2º, parágrafo único, XIII."},{"q":"O impulso de ofício do processo federal convive com o direito de atuação dos interessados.","a":true,"why":"O art. 2º, parágrafo único, XII, prevê impulsão de ofício sem prejuízo da atuação dos interessados. Base: Art. 2º, parágrafo único, XII."},{"q":"A revisão judicial de lesão ou ameaça a direito depende de uma autorização genérica da Administração.","a":false,"why":"O art. 5º, XXXV, assegura o acesso à apreciação judicial; não depende dessa autorização. Base: Art. 5º, XXXV."}],"flashcards":[{"f":"A função administrativa também pode ser exercida por órgãos do Legislativo e do Judiciário.","b":"Certo. A Lei 9.784 alcança esses órgãos da União no desempenho de função administrativa."},{"f":"A Lei 9.784/1999 regula diretamente todo processo administrativo de qualquer município, independentemente de sua legislação.","b":"Errado. A lei estabelece normas para a Administração Federal; a aplicação em outras esferas exige fundamento próprio."},{"f":"O princípio da eficiência permite dispensar a legalidade se a solução administrativa for mais rápida.","b":"Errado. Legalidade e eficiência são exigências simultâneas, não uma autorização para agir contra a lei."},{"f":"A atuação conforme a lei e o Direito é critério expresso do processo administrativo federal.","b":"Certo. O art. 2º, parágrafo único, I, utiliza essa formulação e exige interpretação jurídica compatível com as garantias."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-fundamentos-fontes-regime-juridico","subject":"Direito Administrativo","topic_label":"Fontes, regime jurídico e noções de Estado","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Revisão assistida dos vinte itens contra fontes oficiais; fixação local, sem atribuição a banca.","sources":[{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"}],"items":[{"q":"A função administrativa também pode ser exercida por órgãos do Legislativo e do Judiciário.","a":true,"why":"A Lei 9.784 alcança esses órgãos da União no desempenho de função administrativa. Base: Art. 1º, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 1º","origin":"elaboracao_propria_base_oficial"},{"q":"A Lei 9.784/1999 regula diretamente todo processo administrativo de qualquer município, independentemente de sua legislação.","a":false,"why":"A lei estabelece normas para a Administração Federal; a aplicação em outras esferas exige fundamento próprio. Base: Art. 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º","origin":"elaboracao_propria_base_oficial"},{"q":"O princípio da eficiência permite dispensar a legalidade se a solução administrativa for mais rápida.","a":false,"why":"Legalidade e eficiência são exigências simultâneas, não uma autorização para agir contra a lei. Base: Art. 37, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, caput","origin":"elaboracao_propria_base_oficial"},{"q":"A atuação conforme a lei e o Direito é critério expresso do processo administrativo federal.","a":true,"why":"O art. 2º, parágrafo único, I, utiliza essa formulação e exige interpretação jurídica compatível com as garantias. Base: Art. 2º, parágrafo único, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, I","origin":"elaboracao_propria_base_oficial"},{"q":"Costume administrativo reiterado autoriza a autoridade a contrariar uma proibição legal expressa.","a":false,"why":"A repetição da prática não afasta o dever de observar a lei e o Direito. Base: Art. 2º, parágrafo único, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, I","origin":"elaboracao_propria_base_oficial"},{"q":"Uma súmula vinculante e uma decisão judicial isolada têm necessariamente os mesmos requisitos e o mesmo alcance.","a":false,"why":"O art. 103-A disciplina especificamente aprovação, revisão, cancelamento e efeito vinculante da súmula. Base: Art. 103-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-A","origin":"elaboracao_propria_base_oficial"},{"q":"A indisponibilidade impede renúncia de poderes ou competências, salvo autorização em lei.","a":true,"why":"Esse é o critério do art. 2º, parágrafo único, II; não se trata de proibir toda solução legalmente autorizada. Base: Art. 2º, parágrafo único, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, II","origin":"elaboracao_propria_base_oficial"},{"q":"Invocar interesse público dispensa a indicação dos fatos em decisão federal que limita um direito.","a":false,"why":"O art. 50 exige motivação, com indicação dos fatos e fundamentos jurídicos, nessas hipóteses. Base: Art. 50, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 50, I","origin":"elaboracao_propria_base_oficial"},{"q":"Razoabilidade e proporcionalidade integram os princípios expressos da Lei 9.784/1999.","a":true,"why":"São princípios expressamente enumerados no art. 2º, caput. Base: Art. 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º","origin":"elaboracao_propria_base_oficial"},{"q":"A promoção pessoal do agente é finalidade legítima da atuação administrativa federal.","a":false,"why":"O art. 2º, parágrafo único, III, exige objetividade no interesse público e veda promoção pessoal. Base: Art. 2º, parágrafo único, III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, III","origin":"elaboracao_propria_base_oficial"},{"q":"Estados e municípios são autônomos; isso não os torna individualmente soberanos.","a":true,"why":"A autonomia dos entes consta do art. 18; a soberania é fundamento da República Federativa do Brasil. Base: Arts. 1º, I, e 18.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 1º, I, e 18","origin":"elaboracao_propria_base_oficial"},{"q":"Federação e república respondem à mesma classificação e são expressões intercambiáveis.","a":false,"why":"A federação trata da organização territorial do poder; república, da forma de governo. O art. 1º adota ambas. Base: Art. 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º","origin":"elaboracao_propria_base_oficial"},{"q":"O poder popular somente pode ser exercido mediante representantes eleitos.","a":false,"why":"O art. 1º, parágrafo único, prevê também o exercício direto nos termos da Constituição. Base: Art. 1º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º, parágrafo único","origin":"elaboracao_propria_base_oficial"},{"q":"A soberania é um dos fundamentos constitucionais da República Federativa do Brasil.","a":true,"why":"Consta do art. 1º, I; não se deve atribuí-la separadamente aos entes autônomos. Base: Art. 1º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º, I","origin":"elaboracao_propria_base_oficial"},{"q":"A separação de Poderes elimina qualquer fiscalização recíproca prevista na Constituição.","a":false,"why":"A independência e harmonia do art. 2º convivem com controles constitucionais, como os dos arts. 70 e 71. Base: Arts. 2º, 70 e 71.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 2º, 70 e 71","origin":"elaboracao_propria_base_oficial"},{"q":"A publicidade administrativa admite apenas divulgações compatíveis com as proteções constitucionais de intimidade e sigilo.","a":true,"why":"O art. 37 deve ser interpretado com o art. 5º, X e XXXIII; publicidade não significa exposição irrestrita. Base: Arts. 5º, X e XXXIII, e 37.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 5º, X e XXXIII, e 37","origin":"elaboracao_propria_base_oficial"},{"q":"O critério de proporcionalidade permite impor obrigação superior à estritamente necessária à finalidade pública.","a":false,"why":"O art. 2º, parágrafo único, VI, veda essa imposição excessiva. Base: Art. 2º, parágrafo único, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, VI","origin":"elaboracao_propria_base_oficial"},{"q":"A Administração pode aplicar retroativamente nova interpretação administrativa em qualquer hipótese, por mera conveniência.","a":false,"why":"O art. 2º, parágrafo único, XIII, veda aplicação retroativa de nova interpretação. Base: Art. 2º, parágrafo único, XIII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, XIII","origin":"elaboracao_propria_base_oficial"},{"q":"O impulso de ofício do processo federal convive com o direito de atuação dos interessados.","a":true,"why":"O art. 2º, parágrafo único, XII, prevê impulsão de ofício sem prejuízo da atuação dos interessados. Base: Art. 2º, parágrafo único, XII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 2º, parágrafo único, XII","origin":"elaboracao_propria_base_oficial"},{"q":"A revisão judicial de lesão ou ameaça a direito depende de uma autorização genérica da Administração.","a":false,"why":"O art. 5º, XXXV, assegura o acesso à apreciação judicial; não depende dessa autorização. Base: Art. 5º, XXXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXV","origin":"elaboracao_propria_base_oficial"}]},"legal_review":{"checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Redação e vinte exercícios conferidos no recorte indicado nas fontes oficiais.","sources":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],"changes":[],"corrections":[]}},"expected_material":null,"expected_active_enrichments":[],"enrichment":{"id":"ce6cbaea-3260-5d17-9f6b-3279384dc5c3","material_slug":"administrativo-fundamentos-fontes-regime-juridico","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"be6c29d236f98161f6ccc02fe5893e1e304e98e68e6475e60244a44f3da27a13","content":{"cases":[{"id":"complemento-20261024","title":"Interesse público precisa de fundamento","scenario":"A autoridade pretende dispensar a defesa do interessado dizendo apenas que a decisão é eficiente.","question":"Qual limite precisa ser observado?","steps":["Identifique se a medida afeta direitos.","Leia o art. 2º da Lei 9.784 e as garantias do art. 5º da Constituição.","Exija os fundamentos e o procedimento aplicável."],"conclusion":"Eficiência não afasta legalidade nem defesa; o fundamento genérico não basta.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"O órgão usa providência cautelar diante de risco iminente.","answer":"Verifique a hipótese e as condições do art. 45; urgência não dispensa fundamentação."},"articles":["Lei 9.784/1999, arts. 2º, 45 e 50","CF, art. 5º, LIV e LV"]}],"illustrations":[{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"new","material":{"id":"41b4009c-b064-58d2-9639-17d332e58b43","slug":"administrativo-organizacao-direta-indireta-orgaos","discipline":"Direito Administrativo","topic_label":"Organização administrativa e entidades","sort_order":2,"title":"Organização administrativa: direta, indireta e órgãos públicos","summary":"Conceitos fundamentais com distinções de prova, fonte oficial atual, casos resolvidos e vinte exercícios comentados.","body_md":"## Pessoa jurídica, órgão e autoridade\n\nA Lei 9.784/1999, art. 1º, § 2º, oferece três referências para o processo federal: **órgão** é unidade de atuação da estrutura administrativa; **entidade** é unidade dotada de personalidade jurídica; **autoridade** é servidor ou agente com poder de decisão. Um ministério não se transforma em pessoa jurídica apenas por ter orçamento, chefia ou atribuições próprias.\n\nA doutrina da imputação explica por que o agente atua por meio de um órgão e os efeitos são atribuídos à pessoa jurídica correspondente. A falta de personalidade do órgão não autoriza concluir que toda discussão processual seja impossível: questões de legitimidade e defesa de prerrogativas institucionais exigem a regra processual e a jurisprudência do caso. Não confunda personalidade jurídica com capacidade processual excepcional.\n\n## Direta e indireta\n\nNa esfera federal, o Decreto-Lei 200/1967, arts. 4º e 5º, organiza a Administração direta e indireta. A Constituição, art. 37, XIX, distingue a criação de autarquia por lei específica e a autorização legal para instituir empresa pública, sociedade de economia mista e fundação. O texto constitucional é o ponto de partida atual, inclusive quando se lê a terminologia de diplomas mais antigos.\n\n| Estrutura | Personalidade e constituição | Cuidado de prova |\n| --- | --- | --- |\n| Órgão da direta | Integra a pessoa política; não ganha personalidade própria | Descentralizar não é apenas repartir setores |\n| Autarquia | Pessoa de direito público criada por lei específica | Autoadministração não é autonomia política |\n| Fundação estatal | Identificar a natureza pública ou privada e seu regime constitutivo | Não afirmar que toda fundação estatal é privada |\n| Empresa pública | Direito privado; autorização legal; capital público, observadas as condições legais | Não é sinônimo de sociedade de economia mista |\n| Sociedade de economia mista | Direito privado; sociedade anônima; maioria pública das ações com voto | Maioria do capital votante não significa necessariamente maioria de todo o capital |\n\nA Lei 13.303/2016, arts. 3º e 4º, define empresa pública e sociedade de economia mista e detalha a composição do capital. A constituição da pessoa privada não se completa apenas com a autorização: é preciso cumprir os atos constitutivos e o registro aplicável.\n\nFundações de direito público seguem regime autárquico; as de direito privado não podem ser tratadas como entidades privadas comuns sem sujeições públicas. Nos casos concretos, consulte a lei instituidora, o regime constitucional e a jurisprudência pertinente, em vez de decidir apenas pelo nome da entidade.\n\n## Onde está a competência?\n\n| Situação | Classificação didática |\n| --- | --- |\n| A própria pessoa política executa a atividade por seus órgãos | Centralização |\n| A atividade é distribuída a outra pessoa jurídica | Descentralização |\n| Uma pessoa jurídica reparte atribuições entre seus órgãos | Desconcentração |\n| Competências internas são reunidas em menos órgãos | Concentração |\n\nA desconcentração pode existir tanto na direta quanto dentro de uma autarquia ou empresa estatal. Descentralização e desconcentração não são alternativas que se excluem em toda organização: uma entidade descentralizada também pode distribuir internamente suas competências.\n\nNa descentralização por serviço, a lei institui uma entidade com suas atribuições. Na colaboração, como uma concessão de serviço público, não se transfere automaticamente a titularidade estatal: delega-se a prestação nas condições legais e contratuais. A Lei 8.987/1995, arts. 2º e 40, trata de concessão e permissão; a permissão de serviço é formalizada por contrato de adesão. Evite a generalização de que toda permissão seria ato unilateral.\n\n## Hierarquia, vinculação e supervisão\n\nEntre órgãos da mesma estrutura pode haver hierarquia, respeitadas competências e autonomias constitucionais. A entidade da indireta é **vinculada**, não um departamento hierarquicamente subordinado ao ministério. O controle finalístico ou tutela utiliza meios e limites legais; não autoriza substituir livremente toda decisão da entidade. Os arts. 19, 20 e 26 do Decreto-Lei 200 disciplinam a supervisão ministerial federal.\n\nAs classificações de órgãos em independentes, autônomos, superiores e subalternos são ferramentas doutrinárias. “Independente” nessa classificação não significa imunidade a controles nem soberania. Estrutura simples/composta, decisão singular/colegiada e atuação central/local respondem a perguntas diferentes.\n\n## Generalizações que não devem ser repetidas\n\n- Empresa estatal prestadora de serviço público não recebe automaticamente todos os privilégios da Fazenda Pública: precatórios, imunidades e bens vinculados exigem análise específica.\n- A Lei 13.303 rege contratações de estatais em seu âmbito; não se deve simplesmente incluí-las no regime geral da Lei 14.133, cujo art. 1º, § 1º, faz a distinção.\n- A autonomia dos entes permite organização própria, mas não dispensa exigências constitucionais de lei e de controle.\n\nPara ingresso e vínculos, veja [Agentes e provimento](/dashboard/library/servidores-lei-8112-posse-exercicio-vacancia-remocao). Para fiscalização, veja [Controle da Administração](/dashboard/library/administrativo-controle-da-administracao-publica). Para contratação, veja [Licitações atuais](/dashboard/library/administrativo-licitacoes-lei-14133-modalidades).\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":3,"source_note":"Redação própria a partir dos assuntos identificados nos arquivos enviados e das fontes oficiais indicadas. Sem reprodução de identidade visual, publicidade ou comentários autorais das apostilas. Questões extraídas são catalogadas separadamente com origem didática. Aplicação em outros concursos depende de edital e data de corte.","legal_basis":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"title":"Decreto-Lei 200/1967 — organização administrativa federal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm"},{"title":"Lei 13.303/2016 — estatais","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"},{"title":"Lei 8.987/1995 — concessões e permissões","url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm"},{"title":"Lei 14.133/2021 — licitações e contratos","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],"law_version_checked_at":"2026-10-24T22:30:24.912384+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00","quiz":[{"q":"No processo federal, entidade é unidade de atuação dotada de personalidade jurídica.","a":true,"why":"É a definição do art. 1º, § 2º, II, da Lei 9.784; não se confunde com órgão. Base: Art. 1º, § 2º, II."},{"q":"Um ministério adquire personalidade jurídica própria por possuir orçamento e autoridade decisória.","a":false,"why":"Órgão é unidade da estrutura administrativa; orçamento e chefia não o transformam em entidade. Base: Art. 1º, § 2º, I a III."},{"q":"As autarquias são criadas por lei específica, conforme a Constituição.","a":true,"why":"O art. 37, XIX, distingue criação de autarquia e autorização para instituir pessoas privadas. Base: Art. 37, XIX."},{"q":"A Constituição exige lei específica para autorizar a instituição de empresa pública.","a":true,"why":"A autorização legal é exigida pelo art. 37, XIX; os atos constitutivos ainda devem ser cumpridos. Base: Art. 37, XIX."},{"q":"Sociedade de economia mista pode adotar qualquer forma societária, como uma sociedade limitada.","a":false,"why":"A Lei 13.303, art. 4º, exige a forma de sociedade anônima. Base: Art. 4º."},{"q":"Na sociedade de economia mista, a definição legal considera a maioria das ações com direito a voto.","a":true,"why":"A referência é capital votante, não uma exigência genérica de maioria de todo o capital social. Base: Art. 4º."},{"q":"Empresa pública e sociedade de economia mista têm personalidade jurídica de direito público.","a":false,"why":"Os arts. 3º e 4º da Lei 13.303 definem ambas como pessoas de direito privado. Base: Arts. 3º e 4º."},{"q":"A autarquia federal possui personalidade jurídica, patrimônio e receita próprios.","a":true,"why":"Esses elementos constam da definição do Decreto-Lei 200, art. 5º, I. Base: Art. 5º, I."},{"q":"Autoadministração de uma autarquia equivale à autonomia política de um estado-membro.","a":false,"why":"A autarquia tem capacidade administrativa; a autonomia federativa do art. 18 é categoria distinta. Base: Arts. 18 e 37, XIX."},{"q":"Uma universidade autárquica pode repartir internamente atribuições entre seus órgãos sem criar outra pessoa jurídica.","a":true,"why":"A distinção entre órgão e entidade da Lei 9.784 permite identificar a distribuição interna de competências. Base: Art. 1º, § 2º."},{"q":"A criação de setores dentro de uma mesma pessoa jurídica caracteriza, em classificação didática, desconcentração.","a":true,"why":"A unidade de atuação pode integrar tanto a estrutura direta quanto a indireta, conforme art. 1º, § 2º, I. Base: Art. 1º, § 2º, I."},{"q":"Desconcentração administrativa exige necessariamente o surgimento de nova pessoa jurídica.","a":false,"why":"A repartição interna ocorre entre órgãos; nova personalidade caracteriza entidade distinta. Base: Art. 1º, § 2º."},{"q":"A supervisão ministerial permite ignorar os fins fixados em lei para uma entidade federal.","a":false,"why":"O art. 26, I, do Decreto-Lei 200 exige assegurar a realização dos objetivos previstos no ato de constituição. Base: Art. 26, I."},{"q":"A supervisão da indireta deve considerar a autonomia administrativa, operacional e financeira da entidade.","a":true,"why":"O art. 26, IV, inclui expressamente essa autonomia entre os objetivos da supervisão. Base: Art. 26, IV."},{"q":"A permissão de serviço público prevista na Lei 8.987 é formalizada por contrato de adesão.","a":true,"why":"O art. 40 o determina e exige observância da lei, das normas pertinentes e do edital. Base: Art. 40."},{"q":"A prestação de serviço por concessionária transforma essa empresa privada em órgão da Administração direta.","a":false,"why":"A concessão delega a prestação nas condições legais e contratuais; não apaga a personalidade da concessionária. Base: Art. 2º, II."},{"q":"O fato de integrar a Administração indireta coloca toda estatal no mesmo regime geral de contratação da Lei 14.133.","a":false,"why":"O art. 1º, § 1º, distingue empresas públicas, sociedades de economia mista e subsidiárias, regidas pela Lei 13.303, ressalvado art. 178. Base: Art. 1º, § 1º."},{"q":"Autoridade, para a Lei 9.784, é servidor ou agente público dotado de poder de decisão.","a":true,"why":"É a definição expressa do art. 1º, § 2º, III; não significa que a autoridade seja pessoa jurídica. Base: Art. 1º, § 2º, III."},{"q":"A Administração indireta é formada exclusivamente por unidades sem personalidade jurídica.","a":false,"why":"O Decreto-Lei 200, art. 4º, II, caracteriza entidades dotadas de personalidade jurídica própria. Base: Art. 4º, II."},{"q":"O contrato de desempenho previsto no art. 37, § 8º, por si só cria nova pessoa jurídica para o órgão contratante.","a":false,"why":"A norma trata de ampliação de autonomia e metas de desempenho, não de atribuição de personalidade jurídica ao órgão. Base: Art. 37, § 8º."}],"flashcards":[{"f":"No processo federal, entidade é unidade de atuação dotada de personalidade jurídica.","b":"Certo. É a definição do art. 1º, § 2º, II, da Lei 9.784; não se confunde com órgão."},{"f":"Um ministério adquire personalidade jurídica própria por possuir orçamento e autoridade decisória.","b":"Errado. Órgão é unidade da estrutura administrativa; orçamento e chefia não o transformam em entidade."},{"f":"As autarquias são criadas por lei específica, conforme a Constituição.","b":"Certo. O art. 37, XIX, distingue criação de autarquia e autorização para instituir pessoas privadas."},{"f":"A Constituição exige lei específica para autorizar a instituição de empresa pública.","b":"Certo. A autorização legal é exigida pelo art. 37, XIX; os atos constitutivos ainda devem ser cumpridos."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-organizacao-direta-indireta-orgaos","subject":"Direito Administrativo","topic_label":"Organização administrativa e entidades","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Revisão assistida dos vinte itens contra fontes oficiais; fixação local, sem atribuição a banca.","sources":[{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"dl200","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","bytes":317662,"sha256":"dec522116c8f9d89b81089e0de6029a261e889b60d091b66b777ae44ce09b31d","checked_at":"2026-10-24T22:17:19.906607+00:00","title":"Decreto-Lei 200/1967 — organização administrativa federal"},{"key":"l13303","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","bytes":248652,"sha256":"081e50a5e352f44fbf734df5da72be27d675c827d380126e990fb6b225b35f35","checked_at":"2026-10-24T22:17:17.994894+00:00","title":"Lei 13.303/2016 — estatais"},{"key":"l8987","url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm","bytes":104378,"sha256":"17c0d572f435d9c836079f67c4a0156a5d692d3c564f94541ae7d14fed2c45c8","checked_at":"2026-10-24T22:17:17.353896+00:00","title":"Lei 8.987/1995 — concessões e permissões"},{"key":"l14133","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","bytes":649705,"sha256":"6e747b82f9d1f660beeda5c2a9b75e6ff3881d21bd92d2618c032cba4dbab13f","checked_at":"2026-10-24T22:17:18.861233+00:00","title":"Lei 14.133/2021 — licitações e contratos"}],"items":[{"q":"No processo federal, entidade é unidade de atuação dotada de personalidade jurídica.","a":true,"why":"É a definição do art. 1º, § 2º, II, da Lei 9.784; não se confunde com órgão. Base: Art. 1º, § 2º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º, II","origin":"elaboracao_propria_base_oficial"},{"q":"Um ministério adquire personalidade jurídica própria por possuir orçamento e autoridade decisória.","a":false,"why":"Órgão é unidade da estrutura administrativa; orçamento e chefia não o transformam em entidade. Base: Art. 1º, § 2º, I a III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º, I a III","origin":"elaboracao_propria_base_oficial"},{"q":"As autarquias são criadas por lei específica, conforme a Constituição.","a":true,"why":"O art. 37, XIX, distingue criação de autarquia e autorização para instituir pessoas privadas. Base: Art. 37, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XIX","origin":"elaboracao_propria_base_oficial"},{"q":"A Constituição exige lei específica para autorizar a instituição de empresa pública.","a":true,"why":"A autorização legal é exigida pelo art. 37, XIX; os atos constitutivos ainda devem ser cumpridos. Base: Art. 37, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XIX","origin":"elaboracao_propria_base_oficial"},{"q":"Sociedade de economia mista pode adotar qualquer forma societária, como uma sociedade limitada.","a":false,"why":"A Lei 13.303, art. 4º, exige a forma de sociedade anônima. Base: Art. 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","article":"Art. 4º","origin":"elaboracao_propria_base_oficial"},{"q":"Na sociedade de economia mista, a definição legal considera a maioria das ações com direito a voto.","a":true,"why":"A referência é capital votante, não uma exigência genérica de maioria de todo o capital social. Base: Art. 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","article":"Art. 4º","origin":"elaboracao_propria_base_oficial"},{"q":"Empresa pública e sociedade de economia mista têm personalidade jurídica de direito público.","a":false,"why":"Os arts. 3º e 4º da Lei 13.303 definem ambas como pessoas de direito privado. Base: Arts. 3º e 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","article":"Arts. 3º e 4º","origin":"elaboracao_propria_base_oficial"},{"q":"A autarquia federal possui personalidade jurídica, patrimônio e receita próprios.","a":true,"why":"Esses elementos constam da definição do Decreto-Lei 200, art. 5º, I. Base: Art. 5º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","article":"Art. 5º, I","origin":"elaboracao_propria_base_oficial"},{"q":"Autoadministração de uma autarquia equivale à autonomia política de um estado-membro.","a":false,"why":"A autarquia tem capacidade administrativa; a autonomia federativa do art. 18 é categoria distinta. Base: Arts. 18 e 37, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 18 e 37, XIX","origin":"elaboracao_propria_base_oficial"},{"q":"Uma universidade autárquica pode repartir internamente atribuições entre seus órgãos sem criar outra pessoa jurídica.","a":true,"why":"A distinção entre órgão e entidade da Lei 9.784 permite identificar a distribuição interna de competências. Base: Art. 1º, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º","origin":"elaboracao_propria_base_oficial"},{"q":"A criação de setores dentro de uma mesma pessoa jurídica caracteriza, em classificação didática, desconcentração.","a":true,"why":"A unidade de atuação pode integrar tanto a estrutura direta quanto a indireta, conforme art. 1º, § 2º, I. Base: Art. 1º, § 2º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º, I","origin":"elaboracao_propria_base_oficial"},{"q":"Desconcentração administrativa exige necessariamente o surgimento de nova pessoa jurídica.","a":false,"why":"A repartição interna ocorre entre órgãos; nova personalidade caracteriza entidade distinta. Base: Art. 1º, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º","origin":"elaboracao_propria_base_oficial"},{"q":"A supervisão ministerial permite ignorar os fins fixados em lei para uma entidade federal.","a":false,"why":"O art. 26, I, do Decreto-Lei 200 exige assegurar a realização dos objetivos previstos no ato de constituição. Base: Art. 26, I.","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","article":"Art. 26, I","origin":"elaboracao_propria_base_oficial"},{"q":"A supervisão da indireta deve considerar a autonomia administrativa, operacional e financeira da entidade.","a":true,"why":"O art. 26, IV, inclui expressamente essa autonomia entre os objetivos da supervisão. Base: Art. 26, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","article":"Art. 26, IV","origin":"elaboracao_propria_base_oficial"},{"q":"A permissão de serviço público prevista na Lei 8.987 é formalizada por contrato de adesão.","a":true,"why":"O art. 40 o determina e exige observância da lei, das normas pertinentes e do edital. Base: Art. 40.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm","article":"Art. 40","origin":"elaboracao_propria_base_oficial"},{"q":"A prestação de serviço por concessionária transforma essa empresa privada em órgão da Administração direta.","a":false,"why":"A concessão delega a prestação nas condições legais e contratuais; não apaga a personalidade da concessionária. Base: Art. 2º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm","article":"Art. 2º, II","origin":"elaboracao_propria_base_oficial"},{"q":"O fato de integrar a Administração indireta coloca toda estatal no mesmo regime geral de contratação da Lei 14.133.","a":false,"why":"O art. 1º, § 1º, distingue empresas públicas, sociedades de economia mista e subsidiárias, regidas pela Lei 13.303, ressalvado art. 178. Base: Art. 1º, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 1º, § 1º","origin":"elaboracao_propria_base_oficial"},{"q":"Autoridade, para a Lei 9.784, é servidor ou agente público dotado de poder de decisão.","a":true,"why":"É a definição expressa do art. 1º, § 2º, III; não significa que a autoridade seja pessoa jurídica. Base: Art. 1º, § 2º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 1º, § 2º, III","origin":"elaboracao_propria_base_oficial"},{"q":"A Administração indireta é formada exclusivamente por unidades sem personalidade jurídica.","a":false,"why":"O Decreto-Lei 200, art. 4º, II, caracteriza entidades dotadas de personalidade jurídica própria. Base: Art. 4º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","article":"Art. 4º, II","origin":"elaboracao_propria_base_oficial"},{"q":"O contrato de desempenho previsto no art. 37, § 8º, por si só cria nova pessoa jurídica para o órgão contratante.","a":false,"why":"A norma trata de ampliação de autonomia e metas de desempenho, não de atribuição de personalidade jurídica ao órgão. Base: Art. 37, § 8º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, § 8º","origin":"elaboracao_propria_base_oficial"}]},"legal_review":{"checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Redação e vinte exercícios conferidos no recorte indicado nas fontes oficiais.","sources":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"title":"Decreto-Lei 200/1967 — organização administrativa federal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm"},{"title":"Lei 13.303/2016 — estatais","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"},{"title":"Lei 8.987/1995 — concessões e permissões","url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm"},{"title":"Lei 14.133/2021 — licitações e contratos","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],"changes":[],"corrections":[]}},"expected_material":null,"expected_active_enrichments":[],"enrichment":{"id":"2f0512d5-f4e0-52fc-a173-58521ce37ed5","material_slug":"administrativo-organizacao-direta-indireta-orgaos","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"05ae90b559f048300d222ccfa9aff1476e0550cabc3b6be3b883ddbe2ed942db","content":{"cases":[{"id":"complemento-20261024","title":"Criar setores ou criar uma entidade?","scenario":"Uma autarquia distribui atendimento entre três unidades, sem constituir outra pessoa jurídica.","question":"Houve descentralização por criação de outra entidade?","steps":["Identifique a personalidade já existente.","Verifique se as unidades são apenas órgãos.","Distinga distribuição interna de instituição de outra pessoa."],"conclusion":"A situação é de desconcentração interna na entidade existente.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"Uma lei cria autarquia com personalidade e atribuições próprias.","answer":"A análise muda para descentralização, observada a criação por lei específica."},"articles":["Lei 9.784/1999, art. 1º, § 2º","CF, art. 37, XIX"]}],"illustrations":[{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"title":"Decreto-Lei 200/1967 — organização administrativa federal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm"},{"title":"Lei 13.303/2016 — estatais","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"},{"title":"Lei 8.987/1995 — concessões e permissões","url":"https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm"},{"title":"Lei 14.133/2021 — licitações e contratos","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"951b740a-19fc-4262-8c74-db177f0b8a63","quiz":[{"a":false,"q":"O servidor deve cumprir ordem manifestamente ilegal apenas porque ela foi transmitida por superior hierárquico.","why":"A Lei 8.112, art. 116, IV, ressalva ordens manifestamente ilegais. Hierarquia não elimina legalidade."},{"a":true,"q":"Revogação e anulação são formas de desfazer o ato: a primeira por inconveniência, a segunda por vício.","why":"Revoga-se o ato inconveniente ou inoportuno; anula-se o ato com vício."},{"q":"Um regulamento de execução permite criar livremente obrigações sem fundamento legal.","a":false,"why":"CF, art. 84, IV: regulamentos destinam-se à fiel execução da lei, sem poder irrestrito de criar obrigações."},{"a":true,"q":"O servidor deve cumprir as ordens superiores, exceto quando manifestamente ilegais.","why":"Lei 8.112/1990, art. 116, IV."},{"a":true,"q":"O dever de representar contra ilegalidade, omissão ou abuso de poder integra os deveres do servidor.","why":"Lei 8.112/1990, art. 116, XII."},{"a":true,"q":"É dever do servidor observar as normas legais e regulamentares.","why":"Lei 8.112/1990, art. 116, III."},{"a":false,"q":"O servidor pode retirar documento da repartição sem prévia anuência da autoridade competente.","why":"Lei 8.112/1990, art. 117, II."},{"a":false,"q":"A lei permite ao servidor valer-se do cargo para lograr proveito pessoal em detrimento da dignidade da função pública.","why":"Lei 8.112/1990, art. 117, IX."},{"a":true,"q":"O servidor deve levar irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou competente.","why":"Lei 8.112/1990, art. 116, VI."},{"a":true,"q":"O dever de guardar sigilo sobre assunto da repartição está previsto na Lei 8.112.","why":"Lei 8.112/1990, art. 116, VIII."},{"a":true,"q":"A responsabilidade administrativa do servidor resulta de ato omissivo ou comissivo praticado no desempenho do cargo ou função.","why":"Lei 8.112/1990, art. 124."},{"a":true,"q":"As sanções civis, penais e administrativas podem cumular-se, sendo independentes entre si.","why":"Lei 8.112/1990, art. 125."},{"a":false,"q":"A responsabilidade administrativa do servidor é sempre afastada por absolvição criminal, qualquer que seja seu fundamento.","why":"Lei 8.112/1990, art. 126: exige absolvição criminal que negue existência do fato ou autoria."},{"a":true,"q":"A advertência é uma das penalidades disciplinares previstas na Lei 8.112.","why":"Lei 8.112/1990, art. 127, I."},{"a":false,"q":"A suspensão não integra o rol de penalidades disciplinares da Lei 8.112.","why":"Lei 8.112/1990, art. 127, II."},{"a":true,"q":"A demissão é penalidade disciplinar expressamente prevista na Lei 8.112.","why":"Lei 8.112/1990, art. 127, III."},{"a":true,"q":"A cassação de aposentadoria ou disponibilidade integra o rol legal de penalidades disciplinares.","why":"Lei 8.112/1990, art. 127, IV."},{"a":true,"q":"Na aplicação de penalidades, devem ser consideradas a natureza e a gravidade da infração e os danos dela provenientes.","why":"Lei 8.112/1990, art. 128."},{"a":false,"q":"A autoridade administrativa pode dispensar a motivação do ato que imponha penalidade disciplinar.","why":"Lei 8.112/1990, art. 128, parágrafo único: o ato de imposição mencionará fundamento legal e causa da sanção."},{"a":true,"q":"O servidor deve tratar as pessoas com urbanidade.","why":"Lei 8.112/1990, art. 116, XI."}],"slug":"administrativo-poderes-vinculado-discricionario-hierarquico","title":"Poderes vinculado, discricionário, hierárquico, disciplinar e regulamentar","body_md":"## Ideia geral\n\nA finalidade da Administração é garantir o **interesse público**. Os **poderes** são meios instrumentais e **prerrogativas** de direito público. Não são absolutos: sofrem os limites dos direitos e garantias dos cidadãos. São **irrenunciáveis** e, para o agente, funcionam como **poder-dever de agir**.\n\n## Vinculado × discricionário\n\n| | Poder vinculado | Poder discricionário |\n|---|---|---|\n| **Margem de valoração** | Mínima ou inexistente | Juízo de **conveniência e oportunidade** |\n| **Mérito administrativo** | Inexistente | Existe |\n\nO **mérito** é formado por **motivo** e **objeto**. Mesmo no ato discricionário, competência e finalidade são legalmente delimitadas; a forma obedece à lei, que pode admitir alternativas.\n\n## Poder hierárquico\n\nOrganiza as funções dos agentes e define superiores que **emitem ordens e fiscalizam**. Está presente em todos os poderes e esferas.\n\n- **Avocar:** o superior traz para si atribuições do subordinado, que **não sejam privativas** por previsão legal.\n- **Delegar:** atribuir exercício de parte da competência nos limites dos arts. 12 a 14 da Lei 9.784. Não se delegam edição de atos normativos, decisão de recursos administrativos e competência exclusiva (art. 13). Ordens manifestamente ilegais não se tornam obrigatórias por decorrerem de delegação; observe o art. 116, IV, da Lei 8.112.\n\n### Revisão do ato do subordinado\n\nManter, **convalidar** (sanear o defeito por um segundo ato) ou **desfazer**: **revogação** (ato inconveniente ou inoportuno) ou **anulação** (ato com vício).\n\n| Reconsideração | Revisão |\n|---|---|\n| Pela **própria** autoridade que emitiu o ato | Pela autoridade **superior** |\n\n## Poder disciplinar\n\nCapacidade de **verificar infrações e aplicar penalidades** a quem tenha **vínculo** com a Administração, seja funcional (servidores, decorre do poder hierárquico) ou contratual (particulares contratados). Não constitui liberdade para deixar de apurar infração conhecida: a Lei 8.112, art. 143, impõe apuração com garantias. A tipificação, os requisitos e os limites da penalidade devem ser observados.\n\n## Poder regulamentar × poder normativo\n\nO **poder normativo** é mais amplo e inclui a edição de regulamentos pelo chefe do Executivo e outros atos normativos administrativos. O **poder regulamentar**, em sentido estrito, refere-se aos regulamentos do chefe do Executivo, nos limites constitucionais.\n\n| Regulamento | Características |\n|---|---|\n| **Executivo** | Geral e abstrato, viabiliza o **fiel cumprimento da lei**, é ato **secundário** e **não inova**. Competência **indelegável** |\n| **Autônomo** | CF, art. 84, VI: organização e funcionamento sem aumento de despesa nem criação/extinção de órgãos; extinção de funções ou cargos vagos. Delegação apenas nos termos do parágrafo único, a ministros, PGR ou AGU |\n| **Regulamentação administrativa autorizada** | Competências técnicas delimitadas por lei não autorizam criação livre de obrigações ou crimes; identificar fundamento legal e limites da norma específica |\n\n> **Limite jurídico:** regulamentos de execução devem observar a lei. Decretos autônomos só cabem nas hipóteses constitucionais; autorização técnica não permite criar obrigações sem fundamento legal.\n\n> **Atualização legislativa (conferida no Planalto, Lei nº 9.784/1999, processo administrativo federal):** a **competência é irrenunciável** e só se transfere nos casos de **delegação e avocação** admitidos em lei (art. 11). A delegação é possível ainda que o delegado **não seja subordinado** ao delegante (art. 12) e é **revogável a qualquer tempo** (art. 14, § 2º). **Não podem ser delegados:** a **edição de atos normativos**, a **decisão de recursos administrativos** e as matérias de **competência exclusiva** (art. 13). A **avocação** é **excepcional e temporária**, por **motivos relevantes devidamente justificados**, de competência de órgão **hierarquicamente inferior** (art. 15). Atenção: a regra de que o subordinado \"não pode negar\" a delegação vem da doutrina, não da lei.\n\n## Casos guiados: delegação, avocação e ordem ilegal\n\n**Caso 1 — delegação a órgão não subordinado.** Uma autoridade federal delega parte de sua competência a outra autoridade, sem relação hierárquica direta. A Lei nº 9.784/1999 admite delegação nos limites legais mesmo sem subordinação, desde que a matéria não seja exclusiva e não se trate de edição de ato normativo ou decisão de recurso administrativo.\n\n**Caso 2 — avocação permanente.** Um superior decide assumir indefinidamente toda competência de um subordinado, sem justificativa específica. Isso não corresponde à avocação legal: ela é excepcional, temporária e deve ser motivada por razões relevantes.\n\n**Caso 3 — ordem manifestamente ilegal.** Um servidor recebe ordem claramente contrária à lei. A hierarquia não transforma uma ordem manifestamente ilegal em obrigação legítima; a Lei nº 8.112/1990 prevê o dever de cumprir ordens superiores, exceto quando manifestamente ilegais.\n\n### Lista de verificação\n\n- A competência pode ser delegada?\n- A decisão está entre as matérias indelegáveis?\n- Há justificativa e caráter temporário para avocar?\n- A ordem recebida é legal?\n- O ato discricionário continua respeitando competência, finalidade e forma previstas em lei?\n\n**Fontes oficiais:** [Lei nº 9.784/1999, arts. 11 a 15](https://www.planalto.gov.br/ccivil_03/leis/l9784.htm) e [Lei nº 8.112/1990, art. 116](https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm).\n\n## Caso de revisão: a ordem é legal e a competência pode ser delegada?\n\nNão misture hierarquia, disciplina e tutela. A hierarquia organiza órgãos e agentes de uma estrutura; a supervisão da indireta depende de seus limites legais. O poder disciplinar não é um poder de punir indistintamente qualquer cidadão: identifique o vínculo funcional ou contratual e o regime da infração. Para restrições gerais à atividade privada, consulte o módulo próprio de poder de polícia.\n\nNos atos federais de delegação, o art. 14 da Lei 9.784 exige publicação oficial e especificação das matérias e poderes transferidos, dos limites, da duração, dos objetivos e do recurso cabível. A decisão deve mencionar a delegação e é considerada editada **pelo delegado**. A possibilidade de delegar sem subordinação não autoriza avocar de quem não seja hierarquicamente inferior.\n\nExcesso de poder é atuação além da competência; desvio de finalidade é uso da competência para fim diferente do legal. Não basta trocar as palavras “excesso” e “desvio”: descreva o defeito. Um ato discricionário continua sujeito a finalidade, motivação, proporcionalidade e controle jurídico. Base: Lei 9.784, arts. 2º, 11 a 15 e 50.\n","summary":"Como cada poder funciona, o que o superior pode fazer com o ato do subordinado e os tipos de regulamento.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Competência, finalidade, forma, motivo e objeto. A margem de escolha deve estar autorizada pelo ordenamento; competência e finalidade são legalmente delimitadas, e a forma segue as exigências legais.","f":"Elementos sempre vinculados do ato"},{"b":"Formado por motivo e objeto; existe só no ato discricionário.","f":"Mérito administrativo"},{"b":"Avocar: o superior traz atribuição do subordinado, se não for privativa. Delegar: transferência precária de atribuição.","f":"Avocar × delegar"},{"b":"Reconsideração: pela própria autoridade que editou o ato. Revisão: pela autoridade superior.","f":"Reconsideração × revisão"},{"b":"O executivo (decreto regulamentar), ato secundário que viabiliza o fiel cumprimento da lei.","f":"Regulamento que não inova"}],"sort_order":10,"updated_at":"2026-10-24T20:32:23.821013+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"title":"Lei 8.112/1990 — servidores federais","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco de conferência e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Poderes administrativos","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Corrigidos conceito de poder normativo, limites da delegação, decreto autônomo e dever de apuração disciplinar.","Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-poderes-vinculado-discricionario-hierarquico","subject":"Direito Administrativo","topic_label":"Poderes administrativos","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"items":[{"a":false,"q":"O servidor deve cumprir ordem manifestamente ilegal apenas porque ela foi transmitida por superior hierárquico.","why":"A Lei 8.112, art. 116, IV, ressalva ordens manifestamente ilegais. Hierarquia não elimina legalidade.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"A Lei 8.112, art. 116, IV, ressalva ordens manifestamente ilegais. Hierarquia não elimina legalidade.","origin":"retained_and_rechecked"},{"a":true,"q":"Revogação e anulação são formas de desfazer o ato: a primeira por inconveniência, a segunda por vício.","why":"Revoga-se o ato inconveniente ou inoportuno; anula-se o ato com vício.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Revoga-se o ato inconveniente ou inoportuno; anula-se o ato com vício.","origin":"retained_and_rechecked"},{"q":"Um regulamento de execução permite criar livremente obrigações sem fundamento legal.","a":false,"why":"CF, art. 84, IV: regulamentos destinam-se à fiel execução da lei, sem poder irrestrito de criar obrigações.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 84, IV: regulamentos destinam-se à fiel execução da lei, sem poder irrestrito de criar obrigações.","origin":"clarified_current_official_text"},{"a":true,"q":"O servidor deve cumprir as ordens superiores, exceto quando manifestamente ilegais.","why":"Lei 8.112/1990, art. 116, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, IV.","origin":"retained_and_rechecked"},{"a":true,"q":"O dever de representar contra ilegalidade, omissão ou abuso de poder integra os deveres do servidor.","why":"Lei 8.112/1990, art. 116, XII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, XII.","origin":"retained_and_rechecked"},{"a":true,"q":"É dever do servidor observar as normas legais e regulamentares.","why":"Lei 8.112/1990, art. 116, III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, III.","origin":"retained_and_rechecked"},{"a":false,"q":"O servidor pode retirar documento da repartição sem prévia anuência da autoridade competente.","why":"Lei 8.112/1990, art. 117, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 117, II.","origin":"retained_and_rechecked"},{"a":false,"q":"A lei permite ao servidor valer-se do cargo para lograr proveito pessoal em detrimento da dignidade da função pública.","why":"Lei 8.112/1990, art. 117, IX.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 117, IX.","origin":"retained_and_rechecked"},{"a":true,"q":"O servidor deve levar irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou competente.","why":"Lei 8.112/1990, art. 116, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, VI.","origin":"retained_and_rechecked"},{"a":true,"q":"O dever de guardar sigilo sobre assunto da repartição está previsto na Lei 8.112.","why":"Lei 8.112/1990, art. 116, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, VIII.","origin":"retained_and_rechecked"},{"a":true,"q":"A responsabilidade administrativa do servidor resulta de ato omissivo ou comissivo praticado no desempenho do cargo ou função.","why":"Lei 8.112/1990, art. 124.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 124.","origin":"retained_and_rechecked"},{"a":true,"q":"As sanções civis, penais e administrativas podem cumular-se, sendo independentes entre si.","why":"Lei 8.112/1990, art. 125.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 125.","origin":"retained_and_rechecked"},{"a":false,"q":"A responsabilidade administrativa do servidor é sempre afastada por absolvição criminal, qualquer que seja seu fundamento.","why":"Lei 8.112/1990, art. 126: exige absolvição criminal que negue existência do fato ou autoria.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 126: exige absolvição criminal que negue existência do fato ou autoria.","origin":"retained_and_rechecked"},{"a":true,"q":"A advertência é uma das penalidades disciplinares previstas na Lei 8.112.","why":"Lei 8.112/1990, art. 127, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 127, I.","origin":"retained_and_rechecked"},{"a":false,"q":"A suspensão não integra o rol de penalidades disciplinares da Lei 8.112.","why":"Lei 8.112/1990, art. 127, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 127, II.","origin":"retained_and_rechecked"},{"a":true,"q":"A demissão é penalidade disciplinar expressamente prevista na Lei 8.112.","why":"Lei 8.112/1990, art. 127, III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 127, III.","origin":"retained_and_rechecked"},{"a":true,"q":"A cassação de aposentadoria ou disponibilidade integra o rol legal de penalidades disciplinares.","why":"Lei 8.112/1990, art. 127, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 127, IV.","origin":"retained_and_rechecked"},{"a":true,"q":"Na aplicação de penalidades, devem ser consideradas a natureza e a gravidade da infração e os danos dela provenientes.","why":"Lei 8.112/1990, art. 128.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 128.","origin":"retained_and_rechecked"},{"a":false,"q":"A autoridade administrativa pode dispensar a motivação do ato que imponha penalidade disciplinar.","why":"Lei 8.112/1990, art. 128, parágrafo único: o ato de imposição mencionará fundamento legal e causa da sanção.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 128, parágrafo único: o ato de imposição mencionará fundamento legal e causa da sanção.","origin":"retained_and_rechecked"},{"a":true,"q":"O servidor deve tratar as pessoas com urbanidade.","why":"Lei 8.112/1990, art. 116, XI.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 116, XI.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"951b740a-19fc-4262-8c74-db177f0b8a63","quiz":[{"a":false,"q":"O servidor deve cumprir ordem manifestamente ilegal apenas porque ela foi transmitida por superior hierárquico.","why":"A Lei 8.112, art. 116, IV, ressalva ordens manifestamente ilegais. Hierarquia não elimina legalidade."},{"a":true,"q":"Revogação e anulação são formas de desfazer o ato: a primeira por inconveniência, a segunda por vício.","why":"Revoga-se o ato inconveniente ou inoportuno; anula-se o ato com vício."},{"a":false,"q":"O regulamento executivo pode inovar a ordem jurídica.","why":"É ato secundário e não inova; os autônomos e autorizados podem inovar."},{"a":true,"q":"O servidor deve cumprir as ordens superiores, exceto quando manifestamente ilegais.","why":"Lei 8.112/1990, art. 116, IV."},{"a":true,"q":"O dever de representar contra ilegalidade, omissão ou abuso de poder integra os deveres do servidor.","why":"Lei 8.112/1990, art. 116, XII."},{"a":true,"q":"É dever do servidor observar as normas legais e regulamentares.","why":"Lei 8.112/1990, art. 116, III."},{"a":false,"q":"O servidor pode retirar documento da repartição sem prévia anuência da autoridade competente.","why":"Lei 8.112/1990, art. 117, II."},{"a":false,"q":"A lei permite ao servidor valer-se do cargo para lograr proveito pessoal em detrimento da dignidade da função pública.","why":"Lei 8.112/1990, art. 117, IX."},{"a":true,"q":"O servidor deve levar irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou competente.","why":"Lei 8.112/1990, art. 116, VI."},{"a":true,"q":"O dever de guardar sigilo sobre assunto da repartição está previsto na Lei 8.112.","why":"Lei 8.112/1990, art. 116, VIII."},{"a":true,"q":"A responsabilidade administrativa do servidor resulta de ato omissivo ou comissivo praticado no desempenho do cargo ou função.","why":"Lei 8.112/1990, art. 124."},{"a":true,"q":"As sanções civis, penais e administrativas podem cumular-se, sendo independentes entre si.","why":"Lei 8.112/1990, art. 125."},{"a":false,"q":"A responsabilidade administrativa do servidor é sempre afastada por absolvição criminal, qualquer que seja seu fundamento.","why":"Lei 8.112/1990, art. 126: exige absolvição criminal que negue existência do fato ou autoria."},{"a":true,"q":"A advertência é uma das penalidades disciplinares previstas na Lei 8.112.","why":"Lei 8.112/1990, art. 127, I."},{"a":false,"q":"A suspensão não integra o rol de penalidades disciplinares da Lei 8.112.","why":"Lei 8.112/1990, art. 127, II."},{"a":true,"q":"A demissão é penalidade disciplinar expressamente prevista na Lei 8.112.","why":"Lei 8.112/1990, art. 127, III."},{"a":true,"q":"A cassação de aposentadoria ou disponibilidade integra o rol legal de penalidades disciplinares.","why":"Lei 8.112/1990, art. 127, IV."},{"a":true,"q":"Na aplicação de penalidades, devem ser consideradas a natureza e a gravidade da infração e os danos dela provenientes.","why":"Lei 8.112/1990, art. 128."},{"a":false,"q":"A autoridade administrativa pode dispensar a motivação do ato que imponha penalidade disciplinar.","why":"Lei 8.112/1990, art. 128, parágrafo único: o ato de imposição mencionará fundamento legal e causa da sanção."},{"a":true,"q":"O servidor deve tratar as pessoas com urbanidade.","why":"Lei 8.112/1990, art. 116, XI."}],"slug":"administrativo-poderes-vinculado-discricionario-hierarquico","title":"Poderes vinculado, discricionário, hierárquico, disciplinar e regulamentar","body_md":"## Ideia geral\n\nA finalidade da Administração é garantir o **interesse público**. Os **poderes** são meios instrumentais e **prerrogativas** de direito público. Não são absolutos: sofrem os limites dos direitos e garantias dos cidadãos. São **irrenunciáveis** e, para o agente, funcionam como **poder-dever de agir**.\n\n## Vinculado × discricionário\n\n| | Poder vinculado | Poder discricionário |\n|---|---|---|\n| **Margem de valoração** | Mínima ou inexistente | Juízo de **conveniência e oportunidade** |\n| **Mérito administrativo** | Inexistente | Existe |\n\nO **mérito** é formado por **motivo** e **objeto**. Mesmo no ato discricionário, competência e finalidade são legalmente delimitadas; a forma obedece à lei, que pode admitir alternativas.\n\n## Poder hierárquico\n\nOrganiza as funções dos agentes e define superiores que **emitem ordens e fiscalizam**. Está presente em todos os poderes e esferas.\n\n- **Avocar:** o superior traz para si atribuições do subordinado, que **não sejam privativas** por previsão legal.\n- **Delegar:** atribuir exercício de parte da competência nos limites dos arts. 12 a 14 da Lei 9.784. Não se delegam edição de atos normativos, decisão de recursos administrativos e competência exclusiva (art. 13). Ordens manifestamente ilegais não se tornam obrigatórias por decorrerem de delegação; observe o art. 116, IV, da Lei 8.112.\n\n### Revisão do ato do subordinado\n\nManter, **convalidar** (sanear o defeito por um segundo ato) ou **desfazer**: **revogação** (ato inconveniente ou inoportuno) ou **anulação** (ato com vício).\n\n| Reconsideração | Revisão |\n|---|---|\n| Pela **própria** autoridade que emitiu o ato | Pela autoridade **superior** |\n\n## Poder disciplinar\n\nCapacidade de **verificar infrações e aplicar penalidades** a quem tenha **vínculo** com a Administração, seja funcional (servidores, decorre do poder hierárquico) ou contratual (particulares contratados). Não constitui liberdade para deixar de apurar infração conhecida: a Lei 8.112, art. 143, impõe apuração com garantias. A tipificação, os requisitos e os limites da penalidade devem ser observados.\n\n## Poder regulamentar × poder normativo\n\nO **poder normativo** é mais amplo e inclui a edição de regulamentos pelo chefe do Executivo e outros atos normativos administrativos. O **poder regulamentar**, em sentido estrito, refere-se aos regulamentos do chefe do Executivo, nos limites constitucionais.\n\n| Regulamento | Características |\n|---|---|\n| **Executivo** | Geral e abstrato, viabiliza o **fiel cumprimento da lei**, é ato **secundário** e **não inova**. Competência **indelegável** |\n| **Autônomo** | CF, art. 84, VI: organização e funcionamento sem aumento de despesa nem criação/extinção de órgãos; extinção de funções ou cargos vagos. Delegação apenas nos termos do parágrafo único, a ministros, PGR ou AGU |\n| **Regulamentação administrativa autorizada** | Competências técnicas delimitadas por lei não autorizam criação livre de obrigações ou crimes; identificar fundamento legal e limites da norma específica |\n\n> **Cai em prova:** o regulamento **executivo** não inova; só os **autônomos** e os **autorizados** podem inovar.\n\n> **Atualização legislativa (conferida no Planalto, Lei nº 9.784/1999, processo administrativo federal):** a **competência é irrenunciável** e só se transfere nos casos de **delegação e avocação** admitidos em lei (art. 11). A delegação é possível ainda que o delegado **não seja subordinado** ao delegante (art. 12) e é **revogável a qualquer tempo** (art. 14, § 2º). **Não podem ser delegados:** a **edição de atos normativos**, a **decisão de recursos administrativos** e as matérias de **competência exclusiva** (art. 13). A **avocação** é **excepcional e temporária**, por **motivos relevantes devidamente justificados**, de competência de órgão **hierarquicamente inferior** (art. 15). Atenção: a regra de que o subordinado \"não pode negar\" a delegação vem da doutrina, não da lei.\n\n## Casos guiados: delegação, avocação e ordem ilegal\n\n**Caso 1 — delegação a órgão não subordinado.** Uma autoridade federal delega parte de sua competência a outra autoridade, sem relação hierárquica direta. A Lei nº 9.784/1999 admite delegação nos limites legais mesmo sem subordinação, desde que a matéria não seja exclusiva e não se trate de edição de ato normativo ou decisão de recurso administrativo.\n\n**Caso 2 — avocação permanente.** Um superior decide assumir indefinidamente toda competência de um subordinado, sem justificativa específica. Isso não corresponde à avocação legal: ela é excepcional, temporária e deve ser motivada por razões relevantes.\n\n**Caso 3 — ordem manifestamente ilegal.** Um servidor recebe ordem claramente contrária à lei. A hierarquia não transforma uma ordem manifestamente ilegal em obrigação legítima; a Lei nº 8.112/1990 prevê o dever de cumprir ordens superiores, exceto quando manifestamente ilegais.\n\n### Lista de verificação\n\n- A competência pode ser delegada?\n- A decisão está entre as matérias indelegáveis?\n- Há justificativa e caráter temporário para avocar?\n- A ordem recebida é legal?\n- O ato discricionário continua respeitando competência, finalidade e forma previstas em lei?\n\n**Fontes oficiais:** [Lei nº 9.784/1999, arts. 11 a 15](https://www.planalto.gov.br/ccivil_03/leis/l9784.htm) e [Lei nº 8.112/1990, art. 116](https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm).","summary":"Como cada poder funciona, o que o superior pode fazer com o ato do subordinado e os tipos de regulamento.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Competência, finalidade, forma, motivo e objeto. A margem de escolha deve estar autorizada pelo ordenamento; competência e finalidade são legalmente delimitadas, e a forma segue as exigências legais.","f":"Elementos sempre vinculados do ato"},{"b":"Formado por motivo e objeto; existe só no ato discricionário.","f":"Mérito administrativo"},{"b":"Avocar: o superior traz atribuição do subordinado, se não for privativa. Delegar: transferência precária de atribuição.","f":"Avocar × delegar"},{"b":"Reconsideração: pela própria autoridade que editou o ato. Revisão: pela autoridade superior.","f":"Reconsideração × revisão"},{"b":"O executivo (decreto regulamentar), ato secundário que viabiliza o fiel cumprimento da lei.","f":"Regulamento que não inova"}],"sort_order":10,"updated_at":"2026-10-24T20:32:23.821013+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco de conferência e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Poderes administrativos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigidos conceito de poder normativo, limites da delegação, decreto autônomo e dever de apuração disciplinar."],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":false,"q":"O servidor deve cumprir ordem manifestamente ilegal apenas porque ela foi transmitida por superior hierárquico.","why":"A Lei 8.112, art. 116, IV, ressalva ordens manifestamente ilegais. Hierarquia não elimina legalidade.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"Revogação e anulação são formas de desfazer o ato: a primeira por inconveniência, a segunda por vício.","why":"Revoga-se o ato inconveniente ou inoportuno; anula-se o ato com vício.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"O regulamento executivo pode inovar a ordem jurídica.","why":"É ato secundário e não inova; os autônomos e autorizados podem inovar.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O servidor deve cumprir as ordens superiores, exceto quando manifestamente ilegais.","why":"Lei 8.112/1990, art. 116, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O dever de representar contra ilegalidade, omissão ou abuso de poder integra os deveres do servidor.","why":"Lei 8.112/1990, art. 116, XII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"É dever do servidor observar as normas legais e regulamentares.","why":"Lei 8.112/1990, art. 116, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"O servidor pode retirar documento da repartição sem prévia anuência da autoridade competente.","why":"Lei 8.112/1990, art. 117, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A lei permite ao servidor valer-se do cargo para lograr proveito pessoal em detrimento da dignidade da função pública.","why":"Lei 8.112/1990, art. 117, IX.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O servidor deve levar irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou competente.","why":"Lei 8.112/1990, art. 116, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O dever de guardar sigilo sobre assunto da repartição está previsto na Lei 8.112.","why":"Lei 8.112/1990, art. 116, VIII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A responsabilidade administrativa do servidor resulta de ato omissivo ou comissivo praticado no desempenho do cargo ou função.","why":"Lei 8.112/1990, art. 124.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"As sanções civis, penais e administrativas podem cumular-se, sendo independentes entre si.","why":"Lei 8.112/1990, art. 125.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A responsabilidade administrativa do servidor é sempre afastada por absolvição criminal, qualquer que seja seu fundamento.","why":"Lei 8.112/1990, art. 126: exige absolvição criminal que negue existência do fato ou autoria.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A advertência é uma das penalidades disciplinares previstas na Lei 8.112.","why":"Lei 8.112/1990, art. 127, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A suspensão não integra o rol de penalidades disciplinares da Lei 8.112.","why":"Lei 8.112/1990, art. 127, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A demissão é penalidade disciplinar expressamente prevista na Lei 8.112.","why":"Lei 8.112/1990, art. 127, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A cassação de aposentadoria ou disponibilidade integra o rol legal de penalidades disciplinares.","why":"Lei 8.112/1990, art. 127, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"Na aplicação de penalidades, devem ser consideradas a natureza e a gravidade da infração e os danos dela provenientes.","why":"Lei 8.112/1990, art. 128.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A autoridade administrativa pode dispensar a motivação do ato que imponha penalidade disciplinar.","why":"Lei 8.112/1990, art. 128, parágrafo único: o ato de imposição mencionará fundamento legal e causa da sanção.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O servidor deve tratar as pessoas com urbanidade.","why":"Lei 8.112/1990, art. 116, XI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"administrativo-poderes-vinculado-discricionario-hierarquico","syllabus_topic_id":"a4bda690-568e-4dfd-8706-250551f8ce00"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"174b3391-784c-5dcd-afb8-87330d8f9eee","status":"active","content":{"cases":[{"id":"case-1","steps":["A margem de escolha existe apenas nos aspectos autorizados pela norma.","Competência, finalidade e respeito aos direitos continuam controláveis; conveniência não autoriza qualquer resultado."],"title":"Escolha dentro da lei","pitfall":"Tratar mérito administrativo como imunidade a todo controle.","articles":["Lei 9.784/1999, art. 2º"],"question":"A escolha discricionária dispensa limites legais?","scenario":"Uma autoridade pode escolher, entre horários legalmente admitidos, o mais conveniente para atender ao público. O ato respeita competência e finalidade.","variation":{"answer":"Há possível desvio de finalidade; a conveniência alegada não afasta controle de legalidade.","scenario":"E se a autoridade usar a escolha para perseguir um servidor?"},"conclusion":"Discricionariedade é escolha juridicamente limitada, não arbitrariedade."}],"illustrations":[{"kind":"flow","nodes":["Escolha dentro da lei","A escolha discricionária dispensa limites legais?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Texto oficial complementar","sha256":"43ec9ab8fb3a4f02b797f4bc678a51fe9b76d8c6a011c5046cd868cccec60995","checked_at":"2026-10-05T04:33:26.355879+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:38.218+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"administrativo-poderes-vinculado-discricionario-hierarquico","source_body_sha256":"8408501a4dac764211f3cf312c960a8d83ad2ec878ecde04180bbe6c965bf38c"}],"enrichment":{"id":"0edb5611-dc89-5074-ae6f-02b76fe238df","material_slug":"administrativo-poderes-vinculado-discricionario-hierarquico","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"a1195a9ae468cf638412cdfb3439a3dfda73322b8d8ced6e098069ded7eddaf9","content":{"cases":[{"id":"case-1","steps":["A margem de escolha existe apenas nos aspectos autorizados pela norma.","Competência, finalidade e respeito aos direitos continuam controláveis; conveniência não autoriza qualquer resultado."],"title":"Escolha dentro da lei","pitfall":"Tratar mérito administrativo como imunidade a todo controle.","articles":["Lei 9.784/1999, art. 2º"],"question":"A escolha discricionária dispensa limites legais?","scenario":"Uma autoridade pode escolher, entre horários legalmente admitidos, o mais conveniente para atender ao público. O ato respeita competência e finalidade.","variation":{"answer":"Há possível desvio de finalidade; a conveniência alegada não afasta controle de legalidade.","scenario":"E se a autoridade usar a escolha para perseguir um servidor?"},"conclusion":"Discricionariedade é escolha juridicamente limitada, não arbitrariedade."},{"id":"complemento-20261024","title":"Quem assina a decisão delegada?","scenario":"Uma autoridade recebeu delegação válida e decide dentro de seu escopo, mas a minuta atribui o ato à autoridade delegante.","question":"A quem a lei atribui a decisão?","steps":["Confira publicação e limites da delegação.","Leia o art. 14, § 3º.","Mencione expressamente a qualidade de decisão por delegação."],"conclusion":"A decisão é considerada editada pelo delegado.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"A matéria é recurso administrativo.","answer":"A delegação é vedada pelo art. 13, II."},"articles":["Lei 9.784/1999, arts. 13 e 14"]}],"illustrations":[{"kind":"flow","nodes":["Escolha dentro da lei","A escolha discricionária dispensa limites legais?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"25e952e1-debf-4e58-99fc-4beca896e88d","quiz":[{"q":"Segundo a regra geral da Lei 8.112/1990, a posse ocorre em até trinta dias contados da publicação do ato de provimento.","a":true,"why":"Art. 13, § 1º. Considere as regras especiais do § 2º para os afastamentos nele indicados."},{"a":false,"q":"A exoneração é uma penalidade disciplinar aplicada ao servidor.","why":"A penalidade é a demissão; a exoneração não é sanção."},{"a":false,"q":"A redistribuição é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro.","why":"Isso é a remoção. A redistribuição desloca o cargo para outro órgão do mesmo Poder."},{"a":true,"q":"Tomando posse e não entrando em exercício no prazo legal, o servidor é exonerado.","why":"Art. 15, § 2º, e art. 34, parágrafo único, II."},{"a":true,"q":"A investidura em cargo público ocorre com a posse.","why":"Lei 8.112/1990, art. 7º."},{"a":true,"q":"A nomeação é uma forma de provimento de cargo público.","why":"Lei 8.112/1990, art. 8º, I."},{"a":true,"q":"A posse pode ocorrer mediante procuração específica.","why":"Lei 8.112/1990, art. 13, § 3º."},{"a":false,"q":"O prazo de posse é de quinze dias após a publicação do provimento.","why":"Lei 8.112/1990, art. 13, § 1º: trinta dias."},{"a":true,"q":"A posse depende de prévia inspeção médica oficial.","why":"Lei 8.112/1990, art. 14."},{"q":"É de quinze dias o prazo para o servidor empossado em cargo público efetivo entrar em exercício, contado da posse.","a":true,"why":"Lei 8.112/1990, art. 15, § 1º; identifique o cargo efetivo e o termo inicial."},{"a":true,"q":"O exercício é o efetivo desempenho das atribuições do cargo público.","why":"Lei 8.112/1990, art. 15, caput."},{"a":true,"q":"Cabe à autoridade competente do órgão ou entidade para onde for nomeado ou designado o servidor dar-lhe exercício.","why":"Lei 8.112/1990, art. 15, § 3º."},{"a":true,"q":"A promoção é hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, III."},{"a":true,"q":"A readaptação constitui hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, VI."},{"a":true,"q":"A posse em outro cargo inacumulável constitui hipótese de vacância.","why":"Lei 8.112/1990, art. 33, VIII."},{"a":false,"q":"A remoção é necessariamente solicitada pelo servidor, sendo vedada de ofício.","why":"Lei 8.112/1990, art. 36: a remoção pode ocorrer de ofício ou a pedido."},{"a":true,"q":"A remoção pode ocorrer no âmbito do mesmo quadro, com ou sem mudança de sede.","why":"Lei 8.112/1990, art. 36, caput."},{"a":true,"q":"A redistribuição desloca cargo de provimento efetivo, ocupado ou vago, para outro órgão ou entidade do mesmo Poder.","why":"Lei 8.112/1990, art. 37, caput."},{"a":false,"q":"A redistribuição independe do interesse da administração.","why":"Lei 8.112/1990, art. 37, I: interesse da administração é preceito da redistribuição."},{"a":true,"q":"O servidor pode ser exonerado de ofício se não satisfizer as condições do estágio probatório.","why":"Lei 8.112/1990, art. 34, parágrafo único, I."}],"slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","title":"Lei nº 8.112/1990: posse, exercício, vacância, remoção e redistribuição","body_md":"## Posse e exercício\n\n| Ato | Regra | Prazo |\n|---|---|---|\n| **Posse** (art. 13) | Dá-se pela **assinatura do termo**, com atribuições, deveres, responsabilidades e direitos do cargo, que não podem ser alterados unilateralmente, **ressalvados os atos de ofício previstos em lei** | **30 dias**, contados da **publicação do ato de provimento** |\n| **Exercício** (art. 15) | Efetivo desempenho das atribuições do cargo | **15 dias**, contados da **posse** |\n\nSe o servidor tomar posse e **não entrar em exercício no prazo**, é **exonerado** (art. 15, § 2º).\n\n## Vacância (art. 33)\n\nA vacância do cargo decorre de: **exoneração**, **demissão**, **promoção**, **readaptação**, **aposentadoria**, **posse em outro cargo inacumulável** e **falecimento**. A promoção permanece no art. 33, III; a Lei 9.527/1997 revogou outros incisos, não esse.\n\n### Exoneração\n\n- **Cargo efetivo (art. 34):** **a pedido** ou **de ofício**. De ofício, quando **não satisfeitas as condições do estágio probatório** ou quando, tendo tomado posse, o servidor **não entrar em exercício** no prazo.\n- **Cargo em comissão e função de confiança (art. 35):** **a juízo da autoridade competente**.\n- **Exoneração não é sanção.** A **demissão** (art. 132) é **penalidade disciplinar**.\n\n## Remoção e redistribuição (arts. 36 e 37)\n\n| | **Remoção** | **Redistribuição** |\n|---|---|---|\n| **O que se desloca** | O **servidor** | O **cargo** (de provimento efetivo, ocupado ou vago) |\n| **Onde** | No **mesmo quadro**, com ou sem mudança de sede | Para **outro órgão ou entidade do mesmo Poder** |\n| **Modalidades** | **De ofício**, no interesse da Administração; **a pedido, a critério da Administração**; **a pedido, independentemente do interesse da Administração** (casos do art. 36, parágrafo único, III) | Exige **interesse da administração**, **equivalência de vencimentos** e **prévia apreciação do órgão central do SIPEC** |\n\nNem a remoção nem a redistribuição são forma de **provimento** ou de **vacância**.\n\n## Reintegração (art. 28)\n\nÉ a **reinvestidura do servidor estável** no cargo anterior (ou no resultante de sua transformação), quando **invalidada a demissão** por decisão administrativa ou judicial, **com ressarcimento de todas as vantagens**. Se o cargo foi extinto, o servidor fica em **disponibilidade**; se estiver provido, o ocupante é **reconduzido** ao cargo de origem, **sem direito a indenização**, ou aproveitado em outro cargo.\n\n> **Conferência — 07/10/2026:** a promoção permanece como forma de vacância (art. 33, III). A Lei 8.112 mantém a redação de 24 meses no art. 20, mas o Decreto 12.374/2025 disciplina, em seu âmbito federal, o estágio probatório de 36 meses. A estabilidade constitucional exige três anos de efetivo exercício e avaliação especial (CF, art. 41). Não confunda os institutos nem ensine a redação isolada da lei como prazo operacional federal atual.\n\n## Antes da posse: identifique a espécie de vínculo\n\nAgente público é uma expressão abrangente de estudo. Não se deve excluir automaticamente um contratado temporário de toda categoria de agente estatal. O art. 37, II e IX, distingue concurso para cargo ou emprego e contratação por tempo determinado para necessidade temporária de excepcional interesse público, nos casos definidos em lei. Cargo em comissão declarado em lei de livre nomeação e exoneração integra a ressalva constitucional ao concurso, não uma liberdade para criar cargos sem lei.\n\nFunções de confiança são exercidas exclusivamente por servidores ocupantes de cargo efetivo; cargos em comissão observam os percentuais e condições legais e destinam-se apenas a direção, chefia e assessoramento (art. 37, V). A classificação doutrinária de agentes não substitui esses requisitos.\n\nNo mandato eletivo, separe **prefeito** de **vereador**. Para prefeito, há afastamento e faculdade de opção remuneratória. Para vereador com horários compatíveis, podem ser percebidas as vantagens do vínculo de origem sem prejuízo da remuneração do mandato; sem compatibilidade, aplica-se a regra do prefeito. A frase “mandato municipal só afasta se o horário for incompatível” é excessiva, pois apaga a hipótese de prefeito. Base: CF, art. 38, II e III.\n\nA Lei 8.112 rege o recorte federal nela definido. Não transplante automaticamente seus prazos ou formas de provimento para um servidor estadual, empregado celetista ou temporário.\n\n### Dois pontos que mudaram desde as apostilas\n\nA redação atual do art. 39, caput, deve ser lida com a ADI 2.135. O STF validou a alteração da EC 19 que retirou a exigência constitucional de regime jurídico único, com efeitos para contratações futuras e preservação do regime dos servidores já admitidos. Isso não autoriza converter automaticamente vínculos existentes nem dispensa concurso e lei aplicável. Consulte a notícia oficial e o processo antes de resolver hipóteses específicas.\n\nNa acumulação, o art. 37, XVI, “b”, hoje permite um cargo de professor com outro **de qualquer natureza**, conforme a EC 138/2025, mantidas compatibilidade de horários, teto e demais condições constitucionais. A restrição antiga a outro cargo “técnico ou científico” não deve ser ensinada como texto vigente.\n","summary":"Prazos de posse e exercício, as hipóteses de exoneração e vacância, e a diferença entre remoção e redistribuição.","created_at":"2026-10-01T03:57:19.854178+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Posse: 30 dias da publicação do ato de provimento. Exercício: 15 dias da posse.","f":"Prazos de posse e exercício (Lei 8.112)"},{"b":"Quando não satisfeitas as condições do estágio probatório, ou quando o servidor toma posse e não entra em exercício no prazo (art. 34).","f":"Exoneração de ofício do cargo efetivo"},{"b":"Remoção desloca o servidor no mesmo quadro. Redistribuição desloca o cargo para outro órgão do mesmo Poder, com prévia apreciação do SIPEC.","f":"Remoção × redistribuição"},{"b":"Não. A demissão é que é penalidade disciplinar (art. 132).","f":"A exoneração é sanção?"},{"b":"Reinvestidura do servidor estável no cargo anterior quando invalidada a demissão, com ressarcimento de todas as vantagens (art. 28).","f":"Reintegração"}],"sort_order":60,"updated_at":"2026-10-24T18:43:00.07321+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","title":"Lei nº 8.112/1990 (Regime Jurídico dos Servidores Públicos Civis da União), texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","title":"Fonte oficial complementar — d12374.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm","title":"Fonte oficial complementar — constituicaocompilado.htm"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"STF — ADI 2.135: regime de contratação de servidores","url":"https://noticias.stf.jus.br/postsnoticias/stf-valida-emenda-que-flexibilizou-regime-de-contratacao-de-servidores-publicos/"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido artigo por artigo com o texto da Lei nº 8.112/1990 no Planalto. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Servidores públicos","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","state":"effective","title":"DECRETO Nº 12.374/2025","summary":"Dispõe sobre os critérios e os procedimentos a serem observados pelos órgãos e pelas entidades integrantes do Sistema de Pessoal Civil da Administração Federal, para avaliação de desempenho de servidores ocupantes de cargo público efetivo durante o estágio probatório previsto no art. 20 da Lei nº 8.112, de 11 de dezembro de 1990.","vigency":"Art. 25. Este Decreto entra em vigor na data de sua publicação.","articles":["Art. 20"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/d12967.htm","state":"effective","title":"DECRETO Nº 12.967/2026","summary":"Altera o Decreto nº 12.374, de 6 de fevereiro de 2025, que dispõe sobre os critérios e os procedimentos a serem observados pelos órgãos e pelas entidades integrantes do Sistema de Pessoal Civil da Administração Federal, para avaliação de desempenho de servidores ocupantes de cargo público efetivo durante o estágio probatório previsto no art. 20 da Lei nº 8.112, de 11 de dezembro de 1990.","vigency":"Art. 2º Este Decreto entra em vigor na data de sua publicação.","articles":["Art. 9"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","title":"Fonte oficial complementar — d12374.htm","sha256":"f2ce1058b7127dcf83cd9651a1044353c949fe79bab374729352f6b84e644c99"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm","title":"Fonte oficial complementar — constituicaocompilado.htm","sha256":"9d6c6dca2e333ec1f111819458b31821b54631229153c6c57c6be3e3893854b7"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"stf_rju","url":"https://noticias.stf.jus.br/postsnoticias/stf-valida-emenda-que-flexibilizou-regime-de-contratacao-de-servidores-publicos/","bytes":68113,"sha256":"58bff730ef752dc9f63f9294d279a38011a79aaed3245797228d537d429ac1d3","checked_at":"2026-10-24T22:22:56.755614+00:00","title":"STF — ADI 2.135: regime de contratação de servidores"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Corrigida a falsa revogação da promoção e acrescentada a regulamentação federal do estágio probatório de 2025.","Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","subject":"Direito Administrativo","topic_label":"Servidores públicos","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"}],"items":[{"q":"Segundo a regra geral da Lei 8.112/1990, a posse ocorre em até trinta dias contados da publicação do ato de provimento.","a":true,"why":"Art. 13, § 1º. Considere as regras especiais do § 2º para os afastamentos nele indicados.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Art. 13, § 1º. Considere as regras especiais do § 2º para os afastamentos nele indicados.","origin":"clarified_current_official_text"},{"a":false,"q":"A exoneração é uma penalidade disciplinar aplicada ao servidor.","why":"A penalidade é a demissão; a exoneração não é sanção.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"A penalidade é a demissão; a exoneração não é sanção.","origin":"retained_and_rechecked"},{"a":false,"q":"A redistribuição é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro.","why":"Isso é a remoção. A redistribuição desloca o cargo para outro órgão do mesmo Poder.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Isso é a remoção. A redistribuição desloca o cargo para outro órgão do mesmo Poder.","origin":"retained_and_rechecked"},{"a":true,"q":"Tomando posse e não entrando em exercício no prazo legal, o servidor é exonerado.","why":"Art. 15, § 2º, e art. 34, parágrafo único, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Art. 15, § 2º, e art. 34, parágrafo único, II.","origin":"retained_and_rechecked"},{"a":true,"q":"A investidura em cargo público ocorre com a posse.","why":"Lei 8.112/1990, art. 7º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 7º.","origin":"retained_and_rechecked"},{"a":true,"q":"A nomeação é uma forma de provimento de cargo público.","why":"Lei 8.112/1990, art. 8º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 8º, I.","origin":"retained_and_rechecked"},{"a":true,"q":"A posse pode ocorrer mediante procuração específica.","why":"Lei 8.112/1990, art. 13, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 13, § 3º.","origin":"retained_and_rechecked"},{"a":false,"q":"O prazo de posse é de quinze dias após a publicação do provimento.","why":"Lei 8.112/1990, art. 13, § 1º: trinta dias.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 13, § 1º: trinta dias.","origin":"retained_and_rechecked"},{"a":true,"q":"A posse depende de prévia inspeção médica oficial.","why":"Lei 8.112/1990, art. 14.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 14.","origin":"retained_and_rechecked"},{"q":"É de quinze dias o prazo para o servidor empossado em cargo público efetivo entrar em exercício, contado da posse.","a":true,"why":"Lei 8.112/1990, art. 15, § 1º; identifique o cargo efetivo e o termo inicial.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 15, § 1º; identifique o cargo efetivo e o termo inicial.","origin":"clarified_current_official_text"},{"a":true,"q":"O exercício é o efetivo desempenho das atribuições do cargo público.","why":"Lei 8.112/1990, art. 15, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 15, caput.","origin":"retained_and_rechecked"},{"a":true,"q":"Cabe à autoridade competente do órgão ou entidade para onde for nomeado ou designado o servidor dar-lhe exercício.","why":"Lei 8.112/1990, art. 15, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 15, § 3º.","origin":"retained_and_rechecked"},{"a":true,"q":"A promoção é hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, III.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 33, III.","origin":"retained_and_rechecked"},{"a":true,"q":"A readaptação constitui hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 33, VI.","origin":"retained_and_rechecked"},{"a":true,"q":"A posse em outro cargo inacumulável constitui hipótese de vacância.","why":"Lei 8.112/1990, art. 33, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 33, VIII.","origin":"retained_and_rechecked"},{"a":false,"q":"A remoção é necessariamente solicitada pelo servidor, sendo vedada de ofício.","why":"Lei 8.112/1990, art. 36: a remoção pode ocorrer de ofício ou a pedido.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 36: a remoção pode ocorrer de ofício ou a pedido.","origin":"retained_and_rechecked"},{"a":true,"q":"A remoção pode ocorrer no âmbito do mesmo quadro, com ou sem mudança de sede.","why":"Lei 8.112/1990, art. 36, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 36, caput.","origin":"retained_and_rechecked"},{"a":true,"q":"A redistribuição desloca cargo de provimento efetivo, ocupado ou vago, para outro órgão ou entidade do mesmo Poder.","why":"Lei 8.112/1990, art. 37, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 37, caput.","origin":"retained_and_rechecked"},{"a":false,"q":"A redistribuição independe do interesse da administração.","why":"Lei 8.112/1990, art. 37, I: interesse da administração é preceito da redistribuição.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 37, I: interesse da administração é preceito da redistribuição.","origin":"retained_and_rechecked"},{"a":true,"q":"O servidor pode ser exonerado de ofício se não satisfizer as condições do estágio probatório.","why":"Lei 8.112/1990, art. 34, parágrafo único, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","article":"Lei 8.112/1990, art. 34, parágrafo único, I.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"25e952e1-debf-4e58-99fc-4beca896e88d","quiz":[{"a":true,"q":"Segundo a Lei 8.112/1990, a posse deve ocorrer em até 30 dias contados da publicação do ato de provimento.","why":"Art. 13, § 1º."},{"a":false,"q":"A exoneração é uma penalidade disciplinar aplicada ao servidor.","why":"A penalidade é a demissão; a exoneração não é sanção."},{"a":false,"q":"A redistribuição é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro.","why":"Isso é a remoção. A redistribuição desloca o cargo para outro órgão do mesmo Poder."},{"a":true,"q":"Tomando posse e não entrando em exercício no prazo legal, o servidor é exonerado.","why":"Art. 15, § 2º, e art. 34, parágrafo único, II."},{"a":true,"q":"A investidura em cargo público ocorre com a posse.","why":"Lei 8.112/1990, art. 7º."},{"a":true,"q":"A nomeação é uma forma de provimento de cargo público.","why":"Lei 8.112/1990, art. 8º, I."},{"a":true,"q":"A posse pode ocorrer mediante procuração específica.","why":"Lei 8.112/1990, art. 13, § 3º."},{"a":false,"q":"O prazo de posse é de quinze dias após a publicação do provimento.","why":"Lei 8.112/1990, art. 13, § 1º: trinta dias."},{"a":true,"q":"A posse depende de prévia inspeção médica oficial.","why":"Lei 8.112/1990, art. 14."},{"a":true,"q":"O servidor empossado tem quinze dias para entrar em exercício, contados da posse.","why":"Lei 8.112/1990, art. 15, § 1º."},{"a":true,"q":"O exercício é o efetivo desempenho das atribuições do cargo público.","why":"Lei 8.112/1990, art. 15, caput."},{"a":true,"q":"Cabe à autoridade competente do órgão ou entidade para onde for nomeado ou designado o servidor dar-lhe exercício.","why":"Lei 8.112/1990, art. 15, § 3º."},{"a":true,"q":"A promoção é hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, III."},{"a":true,"q":"A readaptação constitui hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, VI."},{"a":true,"q":"A posse em outro cargo inacumulável constitui hipótese de vacância.","why":"Lei 8.112/1990, art. 33, VIII."},{"a":false,"q":"A remoção é necessariamente solicitada pelo servidor, sendo vedada de ofício.","why":"Lei 8.112/1990, art. 36: a remoção pode ocorrer de ofício ou a pedido."},{"a":true,"q":"A remoção pode ocorrer no âmbito do mesmo quadro, com ou sem mudança de sede.","why":"Lei 8.112/1990, art. 36, caput."},{"a":true,"q":"A redistribuição desloca cargo de provimento efetivo, ocupado ou vago, para outro órgão ou entidade do mesmo Poder.","why":"Lei 8.112/1990, art. 37, caput."},{"a":false,"q":"A redistribuição independe do interesse da administração.","why":"Lei 8.112/1990, art. 37, I: interesse da administração é preceito da redistribuição."},{"a":true,"q":"O servidor pode ser exonerado de ofício se não satisfizer as condições do estágio probatório.","why":"Lei 8.112/1990, art. 34, parágrafo único, I."}],"slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","title":"Lei nº 8.112/1990: posse, exercício, vacância, remoção e redistribuição","body_md":"## Posse e exercício\n\n| Ato | Regra | Prazo |\n|---|---|---|\n| **Posse** (art. 13) | Dá-se pela **assinatura do termo**, com atribuições, deveres, responsabilidades e direitos do cargo, que não podem ser alterados unilateralmente, **ressalvados os atos de ofício previstos em lei** | **30 dias**, contados da **publicação do ato de provimento** |\n| **Exercício** (art. 15) | Efetivo desempenho das atribuições do cargo | **15 dias**, contados da **posse** |\n\nSe o servidor tomar posse e **não entrar em exercício no prazo**, é **exonerado** (art. 15, § 2º).\n\n## Vacância (art. 33)\n\nA vacância do cargo decorre de: **exoneração**, **demissão**, **promoção**, **readaptação**, **aposentadoria**, **posse em outro cargo inacumulável** e **falecimento**. A promoção permanece no art. 33, III; a Lei 9.527/1997 revogou outros incisos, não esse.\n\n### Exoneração\n\n- **Cargo efetivo (art. 34):** **a pedido** ou **de ofício**. De ofício, quando **não satisfeitas as condições do estágio probatório** ou quando, tendo tomado posse, o servidor **não entrar em exercício** no prazo.\n- **Cargo em comissão e função de confiança (art. 35):** **a juízo da autoridade competente**.\n- **Exoneração não é sanção.** A **demissão** (art. 132) é **penalidade disciplinar**.\n\n## Remoção e redistribuição (arts. 36 e 37)\n\n| | **Remoção** | **Redistribuição** |\n|---|---|---|\n| **O que se desloca** | O **servidor** | O **cargo** (de provimento efetivo, ocupado ou vago) |\n| **Onde** | No **mesmo quadro**, com ou sem mudança de sede | Para **outro órgão ou entidade do mesmo Poder** |\n| **Modalidades** | **De ofício**, no interesse da Administração; **a pedido, a critério da Administração**; **a pedido, independentemente do interesse da Administração** (casos do art. 36, parágrafo único, III) | Exige **interesse da administração**, **equivalência de vencimentos** e **prévia apreciação do órgão central do SIPEC** |\n\nNem a remoção nem a redistribuição são forma de **provimento** ou de **vacância**.\n\n## Reintegração (art. 28)\n\nÉ a **reinvestidura do servidor estável** no cargo anterior (ou no resultante de sua transformação), quando **invalidada a demissão** por decisão administrativa ou judicial, **com ressarcimento de todas as vantagens**. Se o cargo foi extinto, o servidor fica em **disponibilidade**; se estiver provido, o ocupante é **reconduzido** ao cargo de origem, **sem direito a indenização**, ou aproveitado em outro cargo.\n\n> **Conferência — 07/10/2026:** a promoção permanece como forma de vacância (art. 33, III). A Lei 8.112 mantém a redação de 24 meses no art. 20, mas o Decreto 12.374/2025 disciplina, em seu âmbito federal, o estágio probatório de 36 meses. A estabilidade constitucional exige três anos de efetivo exercício e avaliação especial (CF, art. 41). Não confunda os institutos nem ensine a redação isolada da lei como prazo operacional federal atual.\n\n","summary":"Prazos de posse e exercício, as hipóteses de exoneração e vacância, e a diferença entre remoção e redistribuição.","created_at":"2026-10-01T03:57:19.854178+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Posse: 30 dias da publicação do ato de provimento. Exercício: 15 dias da posse.","f":"Prazos de posse e exercício (Lei 8.112)"},{"b":"Quando não satisfeitas as condições do estágio probatório, ou quando o servidor toma posse e não entra em exercício no prazo (art. 34).","f":"Exoneração de ofício do cargo efetivo"},{"b":"Remoção desloca o servidor no mesmo quadro. Redistribuição desloca o cargo para outro órgão do mesmo Poder, com prévia apreciação do SIPEC.","f":"Remoção × redistribuição"},{"b":"Não. A demissão é que é penalidade disciplinar (art. 132).","f":"A exoneração é sanção?"},{"b":"Reinvestidura do servidor estável no cargo anterior quando invalidada a demissão, com ressarcimento de todas as vantagens (art. 28).","f":"Reintegração"}],"sort_order":60,"updated_at":"2026-10-24T18:43:00.07321+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","title":"Lei nº 8.112/1990 (Regime Jurídico dos Servidores Públicos Civis da União), texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","title":"Fonte oficial complementar — d12374.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm","title":"Fonte oficial complementar — constituicaocompilado.htm"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido artigo por artigo com o texto da Lei nº 8.112/1990 no Planalto. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Servidores públicos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","state":"effective","title":"DECRETO Nº 12.374/2025","summary":"Dispõe sobre os critérios e os procedimentos a serem observados pelos órgãos e pelas entidades integrantes do Sistema de Pessoal Civil da Administração Federal, para avaliação de desempenho de servidores ocupantes de cargo público efetivo durante o estágio probatório previsto no art. 20 da Lei nº 8.112, de 11 de dezembro de 1990.","vigency":"Art. 25. Este Decreto entra em vigor na data de sua publicação.","articles":["Art. 20"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/d12967.htm","state":"effective","title":"DECRETO Nº 12.967/2026","summary":"Altera o Decreto nº 12.374, de 6 de fevereiro de 2025, que dispõe sobre os critérios e os procedimentos a serem observados pelos órgãos e pelas entidades integrantes do Sistema de Pessoal Civil da Administração Federal, para avaliação de desempenho de servidores ocupantes de cargo público efetivo durante o estágio probatório previsto no art. 20 da Lei nº 8.112, de 11 de dezembro de 1990.","vigency":"Art. 2º Este Decreto entra em vigor na data de sua publicação.","articles":["Art. 9"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","title":"Lei nº 8.112/1990 (Regime Jurídico dos Servidores Públicos Civis da União), texto compilado","sha256":"8a601e739ee9f4998f62ce0432db463e86e299ad2a6c9c4bfe562fecae8a0ec6"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","title":"Fonte oficial complementar — d12374.htm","sha256":"f2ce1058b7127dcf83cd9651a1044353c949fe79bab374729352f6b84e644c99"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm","title":"Fonte oficial complementar — constituicaocompilado.htm","sha256":"9d6c6dca2e333ec1f111819458b31821b54631229153c6c57c6be3e3893854b7"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigida a falsa revogação da promoção e acrescentada a regulamentação federal do estágio probatório de 2025."],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":true,"q":"Segundo a Lei 8.112/1990, a posse deve ocorrer em até 30 dias contados da publicação do ato de provimento.","why":"Art. 13, § 1º.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A exoneração é uma penalidade disciplinar aplicada ao servidor.","why":"A penalidade é a demissão; a exoneração não é sanção.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A redistribuição é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro.","why":"Isso é a remoção. A redistribuição desloca o cargo para outro órgão do mesmo Poder.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"Tomando posse e não entrando em exercício no prazo legal, o servidor é exonerado.","why":"Art. 15, § 2º, e art. 34, parágrafo único, II.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A investidura em cargo público ocorre com a posse.","why":"Lei 8.112/1990, art. 7º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A nomeação é uma forma de provimento de cargo público.","why":"Lei 8.112/1990, art. 8º, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A posse pode ocorrer mediante procuração específica.","why":"Lei 8.112/1990, art. 13, § 3º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"O prazo de posse é de quinze dias após a publicação do provimento.","why":"Lei 8.112/1990, art. 13, § 1º: trinta dias.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A posse depende de prévia inspeção médica oficial.","why":"Lei 8.112/1990, art. 14.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O servidor empossado tem quinze dias para entrar em exercício, contados da posse.","why":"Lei 8.112/1990, art. 15, § 1º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O exercício é o efetivo desempenho das atribuições do cargo público.","why":"Lei 8.112/1990, art. 15, caput.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"Cabe à autoridade competente do órgão ou entidade para onde for nomeado ou designado o servidor dar-lhe exercício.","why":"Lei 8.112/1990, art. 15, § 3º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A promoção é hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A readaptação constitui hipótese de vacância de cargo público.","why":"Lei 8.112/1990, art. 33, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A posse em outro cargo inacumulável constitui hipótese de vacância.","why":"Lei 8.112/1990, art. 33, VIII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A remoção é necessariamente solicitada pelo servidor, sendo vedada de ofício.","why":"Lei 8.112/1990, art. 36: a remoção pode ocorrer de ofício ou a pedido.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A remoção pode ocorrer no âmbito do mesmo quadro, com ou sem mudança de sede.","why":"Lei 8.112/1990, art. 36, caput.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"A redistribuição desloca cargo de provimento efetivo, ocupado ou vago, para outro órgão ou entidade do mesmo Poder.","why":"Lei 8.112/1990, art. 37, caput.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":false,"q":"A redistribuição independe do interesse da administração.","why":"Lei 8.112/1990, art. 37, I: interesse da administração é preceito da redistribuição.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"},{"a":true,"q":"O servidor pode ser exonerado de ofício se não satisfizer as condições do estágio probatório.","why":"Lei 8.112/1990, art. 34, parágrafo único, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","syllabus_topic_id":"732855f7-3423-44fa-b27f-70780806b3ce"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"f9c10d08-b039-500a-9e6c-16c315118c1d","status":"active","content":{"cases":[{"id":"case-1","steps":["A posse, em regra, tem prazo de 30 dias da publicação do ato de provimento.","Para servidor empossado, o exercício tem prazo de 15 dias da posse, nas condições gerais do art. 15."],"title":"Posse e exercício têm marcos diferentes","pitfall":"Somar todos os prazos a partir de uma única data.","articles":["Lei 8.112/1990, arts. 13 e 15"],"question":"O prazo de exercício começa na publicação da nomeação?","scenario":"Uma nomeação federal é publicada. O candidato toma posse dentro do prazo e ainda não iniciou o trabalho.","variation":{"answer":"A lei prevê exoneração; não use como resposta o ato de tornar sem efeito a nomeação por falta de posse.","scenario":"E se o servidor empossado não entrar em exercício no prazo legal aplicável?"},"conclusion":"Não misture os marcos: nomeação → posse; posse → exercício. Hipóteses legais especiais exigem leitura própria."}],"illustrations":[{"kind":"flow","nodes":["Posse e exercício têm marcos diferentes","O prazo de exercício começa na publicação da nomeação?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","title":"Lei nº 8.112/1990 (Regime Jurídico dos Servidores Públicos Civis da União), texto compilado","sha256":"d99984a124063b4cf57c97b0eed4375b2185fc5f155323be1d2fe8b8091d26c8","checked_at":"2026-10-05T04:33:25.567495+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:39.386+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","source_body_sha256":"535c2f28eed8f41d60fe93a8f987f1c18a030820cb0c9977f53ad86e197e47f2"}],"enrichment":{"id":"097bf767-8af5-5824-8472-6f7c417e95f8","material_slug":"servidores-lei-8112-posse-exercicio-vacancia-remocao","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"e34de07d59575c9d4d33f6b8fc5c94bd2c7afa85549c95fd93578330b1d86fd2","content":{"cases":[{"id":"case-1","steps":["A posse, em regra, tem prazo de 30 dias da publicação do ato de provimento.","Para servidor empossado, o exercício tem prazo de 15 dias da posse, nas condições gerais do art. 15."],"title":"Posse e exercício têm marcos diferentes","pitfall":"Somar todos os prazos a partir de uma única data.","articles":["Lei 8.112/1990, arts. 13 e 15"],"question":"O prazo de exercício começa na publicação da nomeação?","scenario":"Uma nomeação federal é publicada. O candidato toma posse dentro do prazo e ainda não iniciou o trabalho.","variation":{"answer":"A lei prevê exoneração; não use como resposta o ato de tornar sem efeito a nomeação por falta de posse.","scenario":"E se o servidor empossado não entrar em exercício no prazo legal aplicável?"},"conclusion":"Não misture os marcos: nomeação → posse; posse → exercício. Hipóteses legais especiais exigem leitura própria."},{"id":"complemento-20261024","title":"Prefeito não é vereador","scenario":"Um servidor toma posse como prefeito e pretende manter o exercício do cargo de origem porque os horários seriam compatíveis.","question":"A compatibilidade resolve esse caso?","steps":["Identifique o mandato exercido.","Leia o art. 38, II.","Separe afastamento de opção remuneratória."],"conclusion":"Como prefeito, deve se afastar, com faculdade de opção remuneratória.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"O mandato é de vereador com horários compatíveis.","answer":"Aplica-se a hipótese própria do art. 38, III, com percepção das vantagens sem prejuízo da remuneração do mandato."},"articles":["CF, art. 38, II e III"]}],"illustrations":[{"kind":"flow","nodes":["Posse e exercício têm marcos diferentes","O prazo de exercício começa na publicação da nomeação?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"key":"l8112","url":"https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm","bytes":563961,"sha256":"5d599be9a93b8bf966231c8dce40584a362815991b636261e997a8374051608e","checked_at":"2026-10-24T22:17:18.830704+00:00","title":"Lei 8.112/1990 — servidores federais"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12374.htm","title":"Fonte oficial complementar — d12374.htm","sha256":"f2ce1058b7127dcf83cd9651a1044353c949fe79bab374729352f6b84e644c99"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm","title":"Fonte oficial complementar — constituicaocompilado.htm","sha256":"9d6c6dca2e333ec1f111819458b31821b54631229153c6c57c6be3e3893854b7"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"stf_rju","url":"https://noticias.stf.jus.br/postsnoticias/stf-valida-emenda-que-flexibilizou-regime-de-contratacao-de-servidores-publicos/","bytes":68113,"sha256":"58bff730ef752dc9f63f9294d279a38011a79aaed3245797228d537d429ac1d3","checked_at":"2026-10-24T22:22:56.755614+00:00","title":"STF — ADI 2.135: regime de contratação de servidores"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"287e7307-ed41-4416-988d-0a81c90dcdcc","quiz":[{"a":true,"q":"O controle externo da Administração federal é exercido pelo Congresso Nacional com o auxílio do Tribunal de Contas da União.","why":"Art. 71 da Constituição."},{"q":"No controle jurisdicional de ato administrativo de outro Poder, o Judiciário pode revogá-lo por sua preferência de conveniência e oportunidade.","a":false,"why":"O controle da juridicidade não permite substituir uma escolha administrativa legítima; não confundir com o Judiciário administrando a própria estrutura."},{"a":true,"q":"O autor da ação popular, salvo comprovada má-fé, é isento de custas judiciais e do ônus da sucumbência.","why":"Art. 5º, LXXIII, da Constituição."},{"a":false,"q":"O controle finalístico dos entes da administração indireta independe de previsão legal.","why":"Depende de norma legal que estabeleça meios e ocasiões de controle."},{"a":true,"q":"O Congresso Nacional exerce controle externo com auxílio do TCU?","why":"CF, arts. 70 e 71."},{"a":true,"q":"O controle interno deve ser mantido de forma integrada pelos Poderes?","why":"CF, art. 74."},{"a":true,"q":"A fiscalização contábil abrange legalidade, legitimidade e economicidade?","why":"CF, art. 70."},{"a":false,"q":"Somente órgãos da administração direta prestam contas de recursos públicos?","why":"CF, art. 70, parágrafo único, alcança qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre recursos públicos."},{"a":true,"q":"O TCU aprecia contas anuais do Presidente da República mediante parecer prévio?","why":"CF, art. 71, I."},{"a":false,"q":"O TCU julga diretamente as contas anuais do Presidente da República?","why":"CF, arts. 49, IX, e 71, I: julgamento compete ao Congresso Nacional; TCU emite parecer prévio."},{"a":true,"q":"O TCU julga contas de administradores e demais responsáveis por dinheiros, bens e valores públicos?","why":"CF, art. 71, II."},{"a":true,"q":"O TCU pode realizar auditorias por iniciativa própria?","why":"CF, art. 71, IV."},{"a":true,"q":"O controle judicial de atos administrativos pode examinar sua legalidade?","why":"A inafastabilidade da jurisdição está no art. 5º, XXXV, da CF."},{"a":false,"q":"O Judiciário pode substituir livremente a escolha administrativa legítima por preferência pessoal do juiz?","why":"O controle jurisdicional não autoriza substituição arbitrária do mérito administrativo válido."},{"a":true,"q":"A ação popular pode buscar anulação de ato lesivo ao patrimônio público?","why":"CF, art. 5º, LXXIII."},{"a":true,"q":"A legitimidade ativa da ação popular é atribuída constitucionalmente a qualquer cidadão?","why":"CF, art. 5º, LXXIII."},{"a":true,"q":"O Ministério Público possui função institucional de promover inquérito civil e ação civil pública?","why":"CF, art. 129, III."},{"a":true,"q":"O controle interno deve apoiar o controle externo no exercício de sua missão institucional?","why":"CF, art. 74, IV."},{"a":true,"q":"Responsáveis pelo controle interno devem comunicar irregularidade ao TCU ao tomar conhecimento, sob pena de responsabilidade solidária?","why":"CF, art. 74, § 1º."},{"a":false,"q":"A fiscalização do TCU é limitada à administração direta federal?","why":"CF, arts. 70 e 71, prevê alcance mais amplo da fiscalização."}],"slug":"administrativo-controle-da-administracao-publica","title":"Controle da Administração Pública","body_md":"## Conceito\n\nConjunto de instrumentos pelos quais a **própria Administração**, os Poderes **Judiciário** e **Legislativo** e o **povo** exercem **fiscalização, orientação e revisão** da atuação administrativa.\n\n## Classificações\n\n### Quanto à origem\n\n| Tipo | Ideia | Exemplo |\n|---|---|---|\n| **Interno** | Dentro do **mesmo Poder**, por órgãos de sua estrutura | Controle interno dos três Poderes (CF, art. 74) |\n| **Externo** | De **um Poder sobre outro**, ou da administração direta sobre a indireta | Fiscalização do **Congresso Nacional com auxílio do TCU** (CF, arts. 70 e 71) |\n| **Popular** | Pela coletividade | **Ação popular** (CF, art. 5º, LXXIII) |\n\n### Quanto ao momento\n\n**Prévio** (preventivo, antes da conclusão do ato), **concomitante** (durante a realização) e **posterior** (corretivo, depois do ato, para desfazer, corrigir ou confirmar).\n\n### Quanto ao aspecto controlado\n\n- **Legalidade e legitimidade:** confronta o ato com a ordem jurídica. Resulta em **validade, anulação ou convalidação**.\n- **Mérito:** conveniência e oportunidade. **Em regra, só o próprio Poder** que editou o ato (revogação). O Judiciário não substitui a escolha administrativa legítima por sua própria conveniência; pode controlar ilegalidade, finalidade, motivação, razoabilidade e proporcionalidade.\n\n### Quanto à amplitude\n\n- **Hierárquico:** dentro da mesma pessoa jurídica, **relação de subordinação**; é sempre interno.\n- **Finalístico (tutela, supervisão ministerial):** da administração direta sobre a indireta, **relação de vinculação**; depende de **lei** que fixe meios e ocasiões.\n\n### Quanto ao órgão\n\n- **Administrativo:** pela própria Administração, por **autotutela**, de ofício ou provocada, sobre legalidade e mérito.\n- **Legislativo:** político e financeiro. Meios: **CPI**, convocação de autoridades, pedidos de informação, fiscalização contábil, financeira e orçamentária e **sustação de atos normativos**.\n- **Judiciário:** só **legalidade e legitimidade**, sobre atos de qualquer dos Poderes.\n\n## O que a Constituição diz\n\n- **Art. 70:** a fiscalização **contábil, financeira, orçamentária, operacional e patrimonial** da União e das entidades da administração direta e indireta, quanto à **legalidade, legitimidade, economicidade**, aplicação de subvenções e renúncia de receitas, é exercida pelo **Congresso Nacional** (controle externo) e pelo **sistema de controle interno de cada Poder**.\n- **Art. 71:** o controle externo, a cargo do Congresso Nacional, é exercido **com o auxílio do Tribunal de Contas da União**.\n- **Art. 74:** os Poderes Legislativo, Executivo e Judiciário **manterão, de forma integrada, sistema de controle interno**, com finalidades como avaliar o cumprimento das metas do plano plurianual e comprovar a legalidade e avaliar os resultados da gestão.\n- **Art. 5º, LXXIII:** **qualquer cidadão** é parte legítima para propor **ação popular** contra ato lesivo ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, **salvo comprovada má-fé, isento de custas e de ônus da sucumbência**.\n\n> **Conferido na Constituição (Planalto e Constituição anotada do STF):** os arts. 5º, LXXIII, 70, 71 e 74 foram conferidos. As **classificações** acima vêm de **classificação doutrinária** e **não são texto constitucional**. Meios do controle legislativo além dos previstos na Constituição não foram conferidos aqui.\n\n## Casos guiados: identifique quem controla\n\n**Caso 1 — irregularidade detectada antes da contratação.** A unidade de controle interno examina o procedimento e aponta uma falha antes da assinatura. É controle preventivo e interno. A classificação depende de quem atua e de quando o exame ocorre, não apenas do assunto fiscalizado.\n\n**Caso 2 — ato administrativo ilegal.** Uma pessoa questiona judicialmente um ato por violação à lei. O Judiciário pode examinar legalidade, finalidade, motivação e limites jurídicos, mas não deve substituir uma escolha administrativa legítima apenas por preferir outra opção de conveniência.\n\n**Caso 3 — lesão ao patrimônio público.** Um cidadão pretende contestar ato lesivo ao patrimônio público ou à moralidade administrativa. A ação popular é instrumento constitucional próprio e exige a condição de cidadão; não é correto afirmar que qualquer pessoa, sem requisito de cidadania, pode ajuizá-la.\n\n### Quadro de decisão\n\n- **Quem fiscaliza?** Administração, Legislativo/TCU, Judiciário ou cidadão.\n- **Quando fiscaliza?** Antes, durante ou depois do ato.\n- **O que examina?** Legalidade/legitimidade ou, nos limites próprios, mérito administrativo.\n- **Qual instrumento?** Controle interno, externo, judicial, ação popular ou outro meio previsto em lei.\n\n**Fontes oficiais:** [Constituição Federal, arts. 5º, LXXIII, 70, 71 e 74](https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm).\n\n## Classificações: declare o critério antes de responder\n\nO rótulo “interno” pode considerar a pessoa jurídica ou o Poder fiscalizador. Por isso há classificações doutrinárias diferentes para a supervisão ministerial da indireta. Na questão, identifique o critério adotado e não trate uma convenção terminológica como dispositivo constitucional. O vínculo da entidade não se transforma em hierarquia por essa mudança de classificação.\n\nNo controle externo federal, **apreciar** contas do Presidente com parecer prévio é atribuição do TCU (art. 71, I); **julgá-las** é competência do Congresso (art. 49, IX). O TCU julga as contas dos administradores e demais responsáveis na hipótese do art. 71, II. São objetos e competências diferentes.\n\nPara sustação de contratos, leia o art. 71, §§ 1º e 2º: o ato de sustação é adotado diretamente pelo Congresso, que solicita medidas ao Executivo; se Congresso ou Executivo não efetivarem as medidas em noventa dias, o Tribunal decide a respeito. Não reduza esse procedimento à frase “o TCU susta sozinho todo contrato”. O art. 74, § 1º, fala em comunicação por responsáveis pelo **controle interno**, sob pena de responsabilidade **solidária**, não subsidiária.\n\nControle judicial inclui os limites jurídicos da discricionariedade. A análise de finalidade ou proporcionalidade não equivale a escolher livremente a política administrativa preferida pelo julgador. Acesso à Justiça e defesa devem ser considerados também no desfazimento de atos: CF, art. 5º, XXXV, LIV e LV.\n","summary":"Controle interno, externo e popular; controle prévio, concomitante e posterior; legalidade e mérito; e o que dizem os arts. 70, 71 e 74 da Constituição.","created_at":"2026-10-01T04:03:52.568808+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Interno: dentro do mesmo Poder. Externo: de um Poder sobre outro. O controle externo da União é do Congresso Nacional, com auxílio do TCU (CF, art. 71).","f":"Controle interno × externo"},{"b":"Em regra o próprio Poder que editou o ato (revogação). O Judiciário não controla mérito de ato de outro Poder.","f":"Quem faz o controle de mérito?"},{"b":"Qualquer cidadão pode propô-la contra ato lesivo ao patrimônio público, à moralidade, ao meio ambiente e ao patrimônio histórico-cultural; salvo má-fé, não paga custas nem sucumbência (CF, art. 5º, LXXIII).","f":"Ação popular"},{"b":"Hierárquico: subordinação dentro da mesma pessoa. Finalístico (tutela): vinculação entre administração direta e indireta, que depende de lei.","f":"Controle hierárquico × finalístico"},{"b":"Os três Poderes mantêm, de forma integrada, sistema de controle interno.","f":"Controle interno (CF, art. 74)"}],"sort_order":100,"updated_at":"2026-10-24T20:32:23.821013+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"title":"Decreto-Lei 200/1967 — organização administrativa federal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto da Lei nº 9.784/1999 e da Constituição no Planalto. Os pontos de doutrina estão indicados como tal. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Controle da Administração","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"dl200","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","bytes":317662,"sha256":"dec522116c8f9d89b81089e0de6029a261e889b60d091b66b777ae44ce09b31d","checked_at":"2026-10-24T22:17:19.906607+00:00","title":"Decreto-Lei 200/1967 — organização administrativa federal"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-controle-da-administracao-publica","subject":"Direito Administrativo","topic_label":"Controle da Administração","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"dl200","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","bytes":317662,"sha256":"dec522116c8f9d89b81089e0de6029a261e889b60d091b66b777ae44ce09b31d","checked_at":"2026-10-24T22:17:19.906607+00:00","title":"Decreto-Lei 200/1967 — organização administrativa federal"}],"items":[{"a":true,"q":"O controle externo da Administração federal é exercido pelo Congresso Nacional com o auxílio do Tribunal de Contas da União.","why":"Art. 71 da Constituição.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 71 da Constituição.","origin":"retained_and_rechecked"},{"q":"No controle jurisdicional de ato administrativo de outro Poder, o Judiciário pode revogá-lo por sua preferência de conveniência e oportunidade.","a":false,"why":"O controle da juridicidade não permite substituir uma escolha administrativa legítima; não confundir com o Judiciário administrando a própria estrutura.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"O controle da juridicidade não permite substituir uma escolha administrativa legítima; não confundir com o Judiciário administrando a própria estrutura.","origin":"clarified_current_official_text"},{"a":true,"q":"O autor da ação popular, salvo comprovada má-fé, é isento de custas judiciais e do ônus da sucumbência.","why":"Art. 5º, LXXIII, da Constituição.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXIII, da Constituição.","origin":"retained_and_rechecked"},{"a":false,"q":"O controle finalístico dos entes da administração indireta independe de previsão legal.","why":"Depende de norma legal que estabeleça meios e ocasiões de controle.","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","article":"Depende de norma legal que estabeleça meios e ocasiões de controle.","origin":"retained_and_rechecked"},{"a":true,"q":"O Congresso Nacional exerce controle externo com auxílio do TCU?","why":"CF, arts. 70 e 71.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, arts. 70 e 71.","origin":"retained_and_rechecked"},{"a":true,"q":"O controle interno deve ser mantido de forma integrada pelos Poderes?","why":"CF, art. 74.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 74.","origin":"retained_and_rechecked"},{"a":true,"q":"A fiscalização contábil abrange legalidade, legitimidade e economicidade?","why":"CF, art. 70.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 70.","origin":"retained_and_rechecked"},{"a":false,"q":"Somente órgãos da administração direta prestam contas de recursos públicos?","why":"CF, art. 70, parágrafo único, alcança qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre recursos públicos.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 70, parágrafo único, alcança qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre recursos públicos.","origin":"retained_and_rechecked"},{"a":true,"q":"O TCU aprecia contas anuais do Presidente da República mediante parecer prévio?","why":"CF, art. 71, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 71, I.","origin":"retained_and_rechecked"},{"a":false,"q":"O TCU julga diretamente as contas anuais do Presidente da República?","why":"CF, arts. 49, IX, e 71, I: julgamento compete ao Congresso Nacional; TCU emite parecer prévio.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, arts. 49, IX, e 71, I: julgamento compete ao Congresso Nacional; TCU emite parecer prévio.","origin":"retained_and_rechecked"},{"a":true,"q":"O TCU julga contas de administradores e demais responsáveis por dinheiros, bens e valores públicos?","why":"CF, art. 71, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 71, II.","origin":"retained_and_rechecked"},{"a":true,"q":"O TCU pode realizar auditorias por iniciativa própria?","why":"CF, art. 71, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 71, IV.","origin":"retained_and_rechecked"},{"a":true,"q":"O controle judicial de atos administrativos pode examinar sua legalidade?","why":"A inafastabilidade da jurisdição está no art. 5º, XXXV, da CF.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"A inafastabilidade da jurisdição está no art. 5º, XXXV, da CF.","origin":"retained_and_rechecked"},{"a":false,"q":"O Judiciário pode substituir livremente a escolha administrativa legítima por preferência pessoal do juiz?","why":"O controle jurisdicional não autoriza substituição arbitrária do mérito administrativo válido.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"O controle jurisdicional não autoriza substituição arbitrária do mérito administrativo válido.","origin":"retained_and_rechecked"},{"a":true,"q":"A ação popular pode buscar anulação de ato lesivo ao patrimônio público?","why":"CF, art. 5º, LXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 5º, LXXIII.","origin":"retained_and_rechecked"},{"a":true,"q":"A legitimidade ativa da ação popular é atribuída constitucionalmente a qualquer cidadão?","why":"CF, art. 5º, LXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 5º, LXXIII.","origin":"retained_and_rechecked"},{"a":true,"q":"O Ministério Público possui função institucional de promover inquérito civil e ação civil pública?","why":"CF, art. 129, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 129, III.","origin":"retained_and_rechecked"},{"a":true,"q":"O controle interno deve apoiar o controle externo no exercício de sua missão institucional?","why":"CF, art. 74, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 74, IV.","origin":"retained_and_rechecked"},{"a":true,"q":"Responsáveis pelo controle interno devem comunicar irregularidade ao TCU ao tomar conhecimento, sob pena de responsabilidade solidária?","why":"CF, art. 74, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 74, § 1º.","origin":"retained_and_rechecked"},{"a":false,"q":"A fiscalização do TCU é limitada à administração direta federal?","why":"CF, arts. 70 e 71, prevê alcance mais amplo da fiscalização.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, arts. 70 e 71, prevê alcance mais amplo da fiscalização.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"287e7307-ed41-4416-988d-0a81c90dcdcc","quiz":[{"a":true,"q":"O controle externo da Administração federal é exercido pelo Congresso Nacional com o auxílio do Tribunal de Contas da União.","why":"Art. 71 da Constituição."},{"a":false,"q":"O Poder Judiciário pode revogar atos administrativos por razões de conveniência e oportunidade.","why":"O Judiciário não revoga ato de outro Poder por mera conveniência e oportunidade. O controle de legalidade pode alcançar motivo, finalidade, proporcionalidade e outras exigências jurídicas."},{"a":true,"q":"O autor da ação popular, salvo comprovada má-fé, é isento de custas judiciais e do ônus da sucumbência.","why":"Art. 5º, LXXIII, da Constituição."},{"a":false,"q":"O controle finalístico dos entes da administração indireta independe de previsão legal.","why":"Depende de norma legal que estabeleça meios e ocasiões de controle."},{"a":true,"q":"O Congresso Nacional exerce controle externo com auxílio do TCU?","why":"CF, arts. 70 e 71."},{"a":true,"q":"O controle interno deve ser mantido de forma integrada pelos Poderes?","why":"CF, art. 74."},{"a":true,"q":"A fiscalização contábil abrange legalidade, legitimidade e economicidade?","why":"CF, art. 70."},{"a":false,"q":"Somente órgãos da administração direta prestam contas de recursos públicos?","why":"CF, art. 70, parágrafo único, alcança qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre recursos públicos."},{"a":true,"q":"O TCU aprecia contas anuais do Presidente da República mediante parecer prévio?","why":"CF, art. 71, I."},{"a":false,"q":"O TCU julga diretamente as contas anuais do Presidente da República?","why":"CF, arts. 49, IX, e 71, I: julgamento compete ao Congresso Nacional; TCU emite parecer prévio."},{"a":true,"q":"O TCU julga contas de administradores e demais responsáveis por dinheiros, bens e valores públicos?","why":"CF, art. 71, II."},{"a":true,"q":"O TCU pode realizar auditorias por iniciativa própria?","why":"CF, art. 71, IV."},{"a":true,"q":"O controle judicial de atos administrativos pode examinar sua legalidade?","why":"A inafastabilidade da jurisdição está no art. 5º, XXXV, da CF."},{"a":false,"q":"O Judiciário pode substituir livremente a escolha administrativa legítima por preferência pessoal do juiz?","why":"O controle jurisdicional não autoriza substituição arbitrária do mérito administrativo válido."},{"a":true,"q":"A ação popular pode buscar anulação de ato lesivo ao patrimônio público?","why":"CF, art. 5º, LXXIII."},{"a":true,"q":"A legitimidade ativa da ação popular é atribuída constitucionalmente a qualquer cidadão?","why":"CF, art. 5º, LXXIII."},{"a":true,"q":"O Ministério Público possui função institucional de promover inquérito civil e ação civil pública?","why":"CF, art. 129, III."},{"a":true,"q":"O controle interno deve apoiar o controle externo no exercício de sua missão institucional?","why":"CF, art. 74, IV."},{"a":true,"q":"Responsáveis pelo controle interno devem comunicar irregularidade ao TCU ao tomar conhecimento, sob pena de responsabilidade solidária?","why":"CF, art. 74, § 1º."},{"a":false,"q":"A fiscalização do TCU é limitada à administração direta federal?","why":"CF, arts. 70 e 71, prevê alcance mais amplo da fiscalização."}],"slug":"administrativo-controle-da-administracao-publica","title":"Controle da Administração Pública","body_md":"## Conceito\n\nConjunto de instrumentos pelos quais a **própria Administração**, os Poderes **Judiciário** e **Legislativo** e o **povo** exercem **fiscalização, orientação e revisão** da atuação administrativa.\n\n## Classificações\n\n### Quanto à origem\n\n| Tipo | Ideia | Exemplo |\n|---|---|---|\n| **Interno** | Dentro do **mesmo Poder**, por órgãos de sua estrutura | Controle interno dos três Poderes (CF, art. 74) |\n| **Externo** | De **um Poder sobre outro**, ou da administração direta sobre a indireta | Fiscalização do **Congresso Nacional com auxílio do TCU** (CF, arts. 70 e 71) |\n| **Popular** | Pela coletividade | **Ação popular** (CF, art. 5º, LXXIII) |\n\n### Quanto ao momento\n\n**Prévio** (preventivo, antes da conclusão do ato), **concomitante** (durante a realização) e **posterior** (corretivo, depois do ato, para desfazer, corrigir ou confirmar).\n\n### Quanto ao aspecto controlado\n\n- **Legalidade e legitimidade:** confronta o ato com a ordem jurídica. Resulta em **validade, anulação ou convalidação**.\n- **Mérito:** conveniência e oportunidade. **Em regra, só o próprio Poder** que editou o ato (revogação). O Judiciário não substitui a escolha administrativa legítima por sua própria conveniência; pode controlar ilegalidade, finalidade, motivação, razoabilidade e proporcionalidade.\n\n### Quanto à amplitude\n\n- **Hierárquico:** dentro da mesma pessoa jurídica, **relação de subordinação**; é sempre interno.\n- **Finalístico (tutela, supervisão ministerial):** da administração direta sobre a indireta, **relação de vinculação**; depende de **lei** que fixe meios e ocasiões.\n\n### Quanto ao órgão\n\n- **Administrativo:** pela própria Administração, por **autotutela**, de ofício ou provocada, sobre legalidade e mérito.\n- **Legislativo:** político e financeiro. Meios: **CPI**, convocação de autoridades, pedidos de informação, fiscalização contábil, financeira e orçamentária e **sustação de atos normativos**.\n- **Judiciário:** só **legalidade e legitimidade**, sobre atos de qualquer dos Poderes.\n\n## O que a Constituição diz\n\n- **Art. 70:** a fiscalização **contábil, financeira, orçamentária, operacional e patrimonial** da União e das entidades da administração direta e indireta, quanto à **legalidade, legitimidade, economicidade**, aplicação de subvenções e renúncia de receitas, é exercida pelo **Congresso Nacional** (controle externo) e pelo **sistema de controle interno de cada Poder**.\n- **Art. 71:** o controle externo, a cargo do Congresso Nacional, é exercido **com o auxílio do Tribunal de Contas da União**.\n- **Art. 74:** os Poderes Legislativo, Executivo e Judiciário **manterão, de forma integrada, sistema de controle interno**, com finalidades como avaliar o cumprimento das metas do plano plurianual e comprovar a legalidade e avaliar os resultados da gestão.\n- **Art. 5º, LXXIII:** **qualquer cidadão** é parte legítima para propor **ação popular** contra ato lesivo ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, **salvo comprovada má-fé, isento de custas e de ônus da sucumbência**.\n\n> **Conferido na Constituição (Planalto e Constituição anotada do STF):** os arts. 5º, LXXIII, 70, 71 e 74 foram conferidos. As **classificações** acima vêm de **doutrina** (resumo de Strauss e Leite) e **não são texto constitucional**. Meios do controle legislativo além dos previstos na Constituição não foram conferidos aqui.\n\n## Casos guiados: identifique quem controla\n\n**Caso 1 — irregularidade detectada antes da contratação.** A unidade de controle interno examina o procedimento e aponta uma falha antes da assinatura. É controle preventivo e interno. A classificação depende de quem atua e de quando o exame ocorre, não apenas do assunto fiscalizado.\n\n**Caso 2 — ato administrativo ilegal.** Uma pessoa questiona judicialmente um ato por violação à lei. O Judiciário pode examinar legalidade, finalidade, motivação e limites jurídicos, mas não deve substituir uma escolha administrativa legítima apenas por preferir outra opção de conveniência.\n\n**Caso 3 — lesão ao patrimônio público.** Um cidadão pretende contestar ato lesivo ao patrimônio público ou à moralidade administrativa. A ação popular é instrumento constitucional próprio e exige a condição de cidadão; não é correto afirmar que qualquer pessoa, sem requisito de cidadania, pode ajuizá-la.\n\n### Quadro de decisão\n\n- **Quem fiscaliza?** Administração, Legislativo/TCU, Judiciário ou cidadão.\n- **Quando fiscaliza?** Antes, durante ou depois do ato.\n- **O que examina?** Legalidade/legitimidade ou, nos limites próprios, mérito administrativo.\n- **Qual instrumento?** Controle interno, externo, judicial, ação popular ou outro meio previsto em lei.\n\n**Fontes oficiais:** [Constituição Federal, arts. 5º, LXXIII, 70, 71 e 74](https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm).","summary":"Controle interno, externo e popular; controle prévio, concomitante e posterior; legalidade e mérito; e o que dizem os arts. 70, 71 e 74 da Constituição.","created_at":"2026-10-01T04:03:52.568808+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Interno: dentro do mesmo Poder. Externo: de um Poder sobre outro. O controle externo da União é do Congresso Nacional, com auxílio do TCU (CF, art. 71).","f":"Controle interno × externo"},{"b":"Em regra o próprio Poder que editou o ato (revogação). O Judiciário não controla mérito de ato de outro Poder.","f":"Quem faz o controle de mérito?"},{"b":"Qualquer cidadão pode propô-la contra ato lesivo ao patrimônio público, à moralidade, ao meio ambiente e ao patrimônio histórico-cultural; salvo má-fé, não paga custas nem sucumbência (CF, art. 5º, LXXIII).","f":"Ação popular"},{"b":"Hierárquico: subordinação dentro da mesma pessoa. Finalístico (tutela): vinculação entre administração direta e indireta, que depende de lei.","f":"Controle hierárquico × finalístico"},{"b":"Os três Poderes mantêm, de forma integrada, sistema de controle interno.","f":"Controle interno (CF, art. 74)"}],"sort_order":100,"updated_at":"2026-10-24T20:32:23.821013+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto da Lei nº 9.784/1999 e da Constituição no Planalto. Os pontos de doutrina estão indicados como tal. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Controle da Administração","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":[],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":true,"q":"O controle externo da Administração federal é exercido pelo Congresso Nacional com o auxílio do Tribunal de Contas da União.","why":"Art. 71 da Constituição.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O Poder Judiciário pode revogar atos administrativos por razões de conveniência e oportunidade.","why":"O Judiciário não revoga ato de outro Poder por mera conveniência e oportunidade. O controle de legalidade pode alcançar motivo, finalidade, proporcionalidade e outras exigências jurídicas.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O autor da ação popular, salvo comprovada má-fé, é isento de custas judiciais e do ônus da sucumbência.","why":"Art. 5º, LXXIII, da Constituição.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O controle finalístico dos entes da administração indireta independe de previsão legal.","why":"Depende de norma legal que estabeleça meios e ocasiões de controle.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O Congresso Nacional exerce controle externo com auxílio do TCU?","why":"CF, arts. 70 e 71.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O controle interno deve ser mantido de forma integrada pelos Poderes?","why":"CF, art. 74.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A fiscalização contábil abrange legalidade, legitimidade e economicidade?","why":"CF, art. 70.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Somente órgãos da administração direta prestam contas de recursos públicos?","why":"CF, art. 70, parágrafo único, alcança qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre recursos públicos.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O TCU aprecia contas anuais do Presidente da República mediante parecer prévio?","why":"CF, art. 71, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O TCU julga diretamente as contas anuais do Presidente da República?","why":"CF, arts. 49, IX, e 71, I: julgamento compete ao Congresso Nacional; TCU emite parecer prévio.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O TCU julga contas de administradores e demais responsáveis por dinheiros, bens e valores públicos?","why":"CF, art. 71, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O TCU pode realizar auditorias por iniciativa própria?","why":"CF, art. 71, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O controle judicial de atos administrativos pode examinar sua legalidade?","why":"A inafastabilidade da jurisdição está no art. 5º, XXXV, da CF.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O Judiciário pode substituir livremente a escolha administrativa legítima por preferência pessoal do juiz?","why":"O controle jurisdicional não autoriza substituição arbitrária do mérito administrativo válido.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A ação popular pode buscar anulação de ato lesivo ao patrimônio público?","why":"CF, art. 5º, LXXIII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A legitimidade ativa da ação popular é atribuída constitucionalmente a qualquer cidadão?","why":"CF, art. 5º, LXXIII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O Ministério Público possui função institucional de promover inquérito civil e ação civil pública?","why":"CF, art. 129, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O controle interno deve apoiar o controle externo no exercício de sua missão institucional?","why":"CF, art. 74, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Responsáveis pelo controle interno devem comunicar irregularidade ao TCU ao tomar conhecimento, sob pena de responsabilidade solidária?","why":"CF, art. 74, § 1º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A fiscalização do TCU é limitada à administração direta federal?","why":"CF, arts. 70 e 71, prevê alcance mais amplo da fiscalização.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"administrativo-controle-da-administracao-publica","syllabus_topic_id":"732855f7-3423-44fa-b27f-70780806b3ce"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"4ae80650-25ff-5125-b4ca-602ed5442267","status":"active","content":{"cases":[{"id":"case-1","steps":["Separe margem legítima de escolha de violação da norma.","O Judiciário pode examinar legalidade; a existência de discricionariedade não autoriza critério ilegal."],"title":"O juiz verifica legalidade","pitfall":"Afirmar que ato discricionário nunca pode ser controlado.","articles":["Constituição, art. 5º, XXXV","Lei 9.784/1999, art. 2º"],"question":"Isso é vedado apenas porque a decisão envolve discricionariedade?","scenario":"Uma decisão administrativa usa critério contrário à lei. O interessado busca controle judicial desse vício.","variation":{"answer":"A mera preferência não demonstra ilegalidade; não confunda controle com administração do mérito.","scenario":"E se o pedido for apenas trocar uma opção legal por outra porque o autor gosta mais dela?"},"conclusion":"O controle do vício não se confunde com substituir uma escolha administrativa válida por preferência do julgador."}],"illustrations":[{"kind":"flow","nodes":["O juiz verifica legalidade","Isso é vedado apenas porque a decisão envolve discricionariedade?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Texto oficial complementar","sha256":"43ec9ab8fb3a4f02b797f4bc678a51fe9b76d8c6a011c5046cd868cccec60995","checked_at":"2026-10-05T04:33:26.355879+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:40.303+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"administrativo-controle-da-administracao-publica","source_body_sha256":"dd6bdc525ee6dcc51d8e84dc13552650f57b0fd49915c64af9732ae07ef051a2"}],"enrichment":{"id":"f48569f6-b255-5d11-96f9-a60f37e77291","material_slug":"administrativo-controle-da-administracao-publica","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"624c42077b545d4b7335349e1f0339b987c435db1669614fcb0c1f39433b43fd","content":{"cases":[{"id":"case-1","steps":["Separe margem legítima de escolha de violação da norma.","O Judiciário pode examinar legalidade; a existência de discricionariedade não autoriza critério ilegal."],"title":"O juiz verifica legalidade","pitfall":"Afirmar que ato discricionário nunca pode ser controlado.","articles":["Constituição, art. 5º, XXXV","Lei 9.784/1999, art. 2º"],"question":"Isso é vedado apenas porque a decisão envolve discricionariedade?","scenario":"Uma decisão administrativa usa critério contrário à lei. O interessado busca controle judicial desse vício.","variation":{"answer":"A mera preferência não demonstra ilegalidade; não confunda controle com administração do mérito.","scenario":"E se o pedido for apenas trocar uma opção legal por outra porque o autor gosta mais dela?"},"conclusion":"O controle do vício não se confunde com substituir uma escolha administrativa válida por preferência do julgador."},{"id":"complemento-20261024","title":"Parecer ou julgamento?","scenario":"Um resumo diz que o TCU julga definitivamente as contas anuais do Presidente.","question":"Qual atribuição foi confundida?","steps":["Identifique o titular das contas.","Compare os arts. 71, I e II.","Leia a competência do Congresso no art. 49, IX."],"conclusion":"Nas contas presidenciais, o TCU emite parecer prévio e o Congresso julga.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"As contas são de um administrador federal na hipótese do art. 71, II.","answer":"O TCU tem competência de julgamento nesse recorte."},"articles":["CF, arts. 49, IX, e 71, I e II"]}],"illustrations":[{"kind":"flow","nodes":["O juiz verifica legalidade","Isso é vedado apenas porque a decisão envolve discricionariedade?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"},{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"dl200","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm","bytes":317662,"sha256":"dec522116c8f9d89b81089e0de6029a261e889b60d091b66b777ae44ce09b31d","checked_at":"2026-10-24T22:17:19.906607+00:00","title":"Decreto-Lei 200/1967 — organização administrativa federal"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"9ccc0e28-dffc-434f-a586-4c115e7c5bc8","quiz":[{"a":false,"q":"A tomada de preços continua sendo modalidade de licitação na Lei 14.133/2021.","why":"O art. 28 lista cinco modalidades e não inclui convite nem tomada de preços."},{"a":true,"q":"O pregão é a modalidade para bens e serviços comuns, observadas as exclusões e a ressalva de serviços comuns de engenharia do art. 29.","why":"Leia conjuntamente os arts. 6º, XLI, e 29; não estenda o pregão a toda obra ou serviço técnico predominantemente intelectual."},{"a":false,"q":"É permitida a inexigibilidade de licitação para serviços de publicidade e divulgação com notória especialização.","why":"O art. 74, III, veda a inexigibilidade para serviços de publicidade e divulgação."},{"a":false,"q":"A Administração pode criar novas modalidades de licitação combinando as previstas em lei.","why":"O art. 28, § 2º, veda a criação de outras modalidades e a combinação das existentes."},{"a":true,"q":"Concorrência é modalidade de licitação.","why":"Art. 28, II."},{"a":true,"q":"Diálogo competitivo é modalidade de licitação.","why":"Art. 28, V."},{"a":true,"q":"Leilão é modalidade de licitação.","why":"Art. 28, IV."},{"a":true,"q":"Concurso é modalidade de licitação.","why":"Art. 28, III."},{"a":false,"q":"Convite consta do art. 28 como modalidade vigente.","why":"Art. 28."},{"a":true,"q":"A criação de outras modalidades de licitação é vedada.","why":"Art. 28, § 2º."},{"a":true,"q":"Menor preço é critério de julgamento.","why":"Art. 33, I."},{"a":true,"q":"Maior desconto é critério de julgamento.","why":"Art. 33, II."},{"a":true,"q":"Melhor técnica ou conteúdo artístico é critério de julgamento.","why":"Art. 33, III."},{"a":true,"q":"Maior lance é critério de julgamento.","why":"Art. 33, V."},{"a":true,"q":"Maior retorno econômico é critério de julgamento.","why":"Art. 33, VI."},{"a":false,"q":"A habilitação sempre precede o julgamento das propostas.","why":"Art. 17."},{"a":true,"q":"A fase preparatória integra a licitação.","why":"Art. 17, I."},{"a":true,"q":"A fase recursal integra a licitação.","why":"Art. 17, VI."},{"a":true,"q":"A homologação é fase da licitação.","why":"Art. 17, VII."},{"a":true,"q":"O pregão é destinado a bens e serviços comuns.","why":"Arts. 6º, XLI, e 29."}],"slug":"administrativo-licitacoes-lei-14133-modalidades","title":"Licitações: princípios, modalidades e inexigibilidade na Lei nº 14.133/2021","body_md":"## Qual lei vale\n\nA Lei 14.133/2021 é a lei geral atual de licitações e contratos. O art. 193, II, na redação da **Lei Complementar 198/2023**, fixou a revogação da Lei 8.666/1993, da Lei 10.520/2002 e dos arts. 1º a 47-A do RDC em **30/12/2023**. Contratos e escolhas válidas do período de transição conservam o regime próprio nas condições dos arts. 190 e 191; a revogação não converte automaticamente contratos antigos em novos. É vedada a combinação de regimes.\n\n> **Valores de 2026:** o **Decreto 12.807/2025**, vigente desde 01/01/2026, atualiza os limites. Nas hipóteses do art. 75, I e II, os valores são, respectivamente, R$ 130.984,20 e R$ 65.492,11. Confira o objeto, as condições legais e as regras de fracionamento antes de aplicar dispensa por valor; não use os valores nominais originais da lei.\n\n## Princípios (art. 5º)\n\nLegalidade, impessoalidade, moralidade, publicidade, eficiência, interesse público, probidade administrativa, igualdade, **planejamento**, **transparência**, **eficácia**, **segregação de funções**, motivação, vinculação ao edital, julgamento objetivo, segurança jurídica, razoabilidade, **competitividade**, proporcionalidade, **celeridade**, **economicidade** e **desenvolvimento nacional sustentável**, além das disposições da **LINDB** (Decreto-Lei nº 4.657/1942).\n\n## As cinco modalidades (art. 28)\n\n| Modalidade | Para quê |\n|---|---|\n| **Pregão** | Para bens e serviços comuns; observar os limites do art. 29, parágrafo único, inclusive obras e serviços de engenharia e a exceção dos serviços comuns de engenharia; julgamento por menor preço ou maior desconto |\n| **Concorrência** | Bens e serviços **especiais** e **obras e serviços comuns e especiais de engenharia** |\n| **Concurso** | Escolha de **trabalho técnico, científico ou artístico**, por **melhor técnica ou conteúdo artístico**, com prêmio ou remuneração ao vencedor |\n| **Leilão** | **Alienação** de bens **imóveis** ou de bens **móveis inservíveis ou legalmente apreendidos**, a quem der o **maior lance** |\n| **Diálogo competitivo** | Obras, serviços e compras em que a Administração **dialoga com licitantes previamente selecionados** para desenvolver alternativas, e depois recebe a **proposta final** |\n\n- É **vedado criar outras modalidades** ou **combinar** as existentes (art. 28, § 2º).\n- **Convite** e **tomada de preços**, da Lei nº 8.666/1993, **não constam** do rol da lei atual.\n- A **modalidade nova** é o **diálogo competitivo**.\n- A lei admite ainda **procedimentos auxiliares** (art. 28, § 1º).\n\n## Inexigibilidade (art. 74)\n\nÉ **inexigível** a licitação quando **inviável a competição**, **em especial** nos casos de:\n\n1. **Fornecedor exclusivo** (produtor, empresa ou representante comercial exclusivo). A Administração deve demonstrar a inviabilidade com atestado ou contrato de exclusividade, declaração do fabricante ou documento idôneo, **vedada a preferência por marca específica** (§ 1º).\n2. **Profissional do setor artístico**, diretamente ou por empresário exclusivo, **consagrado pela crítica especializada ou pela opinião pública**. O empresário exclusivo precisa ter exclusividade **permanente e contínua**, e não apenas para evento ou local específico (§ 2º).\n3. **Serviços técnicos especializados de natureza predominantemente intelectual**, com profissionais ou empresas de **notória especialização**, como estudos técnicos e projetos, consultorias e auditorias, fiscalização e supervisão de obras, patrocínio ou defesa de causas judiciais ou administrativas e restauração de obras de arte. **Vedada a inexigibilidade para serviços de publicidade e divulgação**.\n\nO rol do art. 74 é **exemplificativo** (\"em especial\"). Na hipótese do inciso III, é **vedada a subcontratação** de outras empresas e a atuação de profissionais diferentes dos que justificaram a inexigibilidade (§ 4º).\n\n> **Cai em prova:** inexigibilidade é **inviabilidade de competição**; dispensa é possibilidade de competir, mas com autorização legal para não licitar. E o **pregão** é **obrigatório** para bens e serviços comuns.\n\n## Atualização das apostilas: edital, desempate e procedimentos auxiliares\n\nMaterial que apresenta convite e tomada de preços como modalidades gerais atuais está descrevendo o regime anterior. A Lei 14.133, art. 28, contém cinco modalidades; o sistema de registro de preços integra os **procedimentos auxiliares**, nos arts. 78 e 82 a 86. A contratação por ata exige as condições aplicáveis; registro de preços não é autorização irrestrita para comprar de qualquer fornecedor.\n\nAlteração de edital exige nova divulgação na mesma forma e observância dos prazos originais, **exceto quando a alteração não comprometer a formulação das propostas** (art. 55, § 1º). Portanto, “toda alteração reabre prazo” e “nenhuma alteração reabre prazo” são generalizações igualmente inadequadas.\n\nNo empate, siga a ordem do art. 60: disputa final; desempenho contratual prévio; ações de equidade entre homens e mulheres no ambiente de trabalho; programa de integridade. As preferências sucessivas do § 1º e o tratamento da LC 123 referido no § 2º não devem ser confundidos com esses quatro critérios. A margem de preferência do art. 26 é outro instituto e depende das condições e da regulamentação aplicáveis.\n\nContratação direta exige processo instruído nos termos do art. 72. Inexigibilidade do art. 74 decorre de inviabilidade de competição e tem hipóteses exemplificativas; dispensa do art. 75 exige hipótese legal. Não use o antigo número de artigo como regra atual nem invente novas dispensas por conveniência. Fracionar artificialmente despesa para fugir da licitação não se confunde com parcelamento tecnicamente justificado do objeto; verifique art. 75, § 1º, e regras de planejamento.\n\nA licitação deserta não é sinônimo de inabilitação de todos os interessados. A hipótese atual do art. 75, III, exige condições próprias, como a referência temporal e a manutenção das condições do edital; a expressão doutrinária isolada não autoriza contratar diretamente.\n\nAs regras revogadas permanecem apenas como contexto histórico ou para contratos validamente submetidos à transição dos arts. 190 e 191. **Não se combinam regimes.** Confira também [Organização administrativa](/dashboard/library/administrativo-organizacao-direta-indireta-orgaos) para diferenciar estatais regidas pela Lei 13.303.\n","summary":"Os princípios do art. 5º, as cinco modalidades, o que desapareceu da Lei nº 8.666/1993 e os casos de inexigibilidade.","created_at":"2026-10-01T03:51:38.980016+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Pregão, concorrência, concurso, leilão e diálogo competitivo (art. 28). É vedado criar outras ou combiná-las.","f":"Quais são as modalidades de licitação da Lei 14.133/2021?"},{"b":"O diálogo competitivo. Convite e tomada de preços, da Lei 8.666/1993, não constam do rol atual.","f":"Modalidade nova da Lei 14.133/2021"},{"b":"Obrigatório para bens e serviços comuns; critério de menor preço ou maior desconto.","f":"Pregão"},{"b":"Quando inviável a competição, em especial: fornecedor exclusivo, artista consagrado e serviço técnico especializado de natureza intelectual com notória especialização.","f":"Inexigibilidade (art. 74)"},{"b":"Alienação de imóveis ou de móveis inservíveis ou legalmente apreendidos, a quem oferecer o maior lance.","f":"Leilão"}],"sort_order":50,"updated_at":"2026-10-24T19:59:47.556197+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","title":"Lei nº 14.133/2021 (Nova Lei de Licitações e Contratos Administrativos)"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","title":"Fonte oficial complementar — d12807.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp198.htm","title":"Fonte oficial complementar — lcp198.htm"},{"title":"Lei 13.303/2016 — estatais","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Elaborado diretamente a partir do texto da Lei nº 14.133/2021 no Planalto (arts. 5º, 6º, 28, 74 e 193), com organização e destaques próprios. Não usa o resumo de licitações da pasta Apostilas. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Licitações e contratos","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15471.htm","state":"effective","title":"LEI Nº 15.471/2026","summary":"Institui a Estratégia Nacional de Saúde do Complexo Econômico-Industrial da Saúde (Ensceis); e altera a Lei nº 6.360, de 23 de setembro de 1976, a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), e a Lei nº 8.080, de 19 de setembro de 1990 (Lei Orgânica da Saúde).","vigency":"Art. 39. Esta Lei entra em vigor na data de sua publicação.","articles":["Art. 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Lei/L15266.htm","state":"effective","title":"LEI Nº 15.266/2025","summary":"Altera a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), para prever o uso do Sistema de Compras Expressas (Sicx) na contratação de bens e serviços comuns padronizados.","vigency":"Art. 2º Esta Lei entra em vigor na data de sua publicação.","articles":["Art. 79","Art. 87","Art. 174","Art. 175"]},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Lei/L15210.htm","state":"effective","title":"LEI Nº 15.210/2025","summary":"Altera a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), para estabelecer requisitos para a compra de equipamentos destinados a procedimentos diagnósticos ou terapêuticos no âmbito do Sistema Único de Saúde (SUS).","vigency":"Art. 2º Esta Lei entra em vigor após decorridos 180 (cento e oitenta) dias de sua publicação oficial. Publicação: 17/09/2025. Entrada em vigor calculada pelo prazo legal: 16/03/2026.","articles":["Art. 44-A"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","state":"effective","title":"DECRETO Nº 12.807/2025","summary":"DECRETO Nº 12.807/2025","vigency":"Art. 5º Este Decreto entra em vigor em 1º de janeiro de 2026.","articles":["Art. 6","Art. 37","Art. 70","Art. 75","Art. 95","Art. 184-A"]}],"sources":[{"key":"l14133","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","bytes":649705,"sha256":"6e747b82f9d1f660beeda5c2a9b75e6ff3881d21bd92d2618c032cba4dbab13f","checked_at":"2026-10-24T22:17:18.861233+00:00","title":"Lei 14.133/2021 — licitações e contratos"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","title":"Fonte oficial complementar — d12807.htm","sha256":"a57c65cbeae48f68224545a9b3961c9530a4833ed07347ba9abeced96699beae"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp198.htm","title":"Fonte oficial complementar — lcp198.htm","sha256":"b755a8248b563efe76c339c5ab3b0933a7e5dcdf8b69aa80ef50f68c8a799b39"},{"key":"l13303","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","bytes":248652,"sha256":"081e50a5e352f44fbf734df5da72be27d675c827d380126e990fb6b225b35f35","checked_at":"2026-10-24T22:17:17.994894+00:00","title":"Lei 13.303/2016 — estatais"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Corrigida a data efetiva de revogação; incluídos os limites atualizados de dispensa para 2026 e as ressalvas do pregão.","Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-licitacoes-lei-14133-modalidades","subject":"Direito Administrativo","topic_label":"Licitações e contratos","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"l14133","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","bytes":649705,"sha256":"6e747b82f9d1f660beeda5c2a9b75e6ff3881d21bd92d2618c032cba4dbab13f","checked_at":"2026-10-24T22:17:18.861233+00:00","title":"Lei 14.133/2021 — licitações e contratos"}],"items":[{"a":false,"q":"A tomada de preços continua sendo modalidade de licitação na Lei 14.133/2021.","why":"O art. 28 lista cinco modalidades e não inclui convite nem tomada de preços.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"O art. 28 lista cinco modalidades e não inclui convite nem tomada de preços.","origin":"retained_and_rechecked"},{"a":true,"q":"O pregão é a modalidade para bens e serviços comuns, observadas as exclusões e a ressalva de serviços comuns de engenharia do art. 29.","why":"Leia conjuntamente os arts. 6º, XLI, e 29; não estenda o pregão a toda obra ou serviço técnico predominantemente intelectual.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Leia conjuntamente os arts. 6º, XLI, e 29; não estenda o pregão a toda obra ou serviço técnico predominantemente intelectual.","origin":"retained_and_rechecked"},{"a":false,"q":"É permitida a inexigibilidade de licitação para serviços de publicidade e divulgação com notória especialização.","why":"O art. 74, III, veda a inexigibilidade para serviços de publicidade e divulgação.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"O art. 74, III, veda a inexigibilidade para serviços de publicidade e divulgação.","origin":"retained_and_rechecked"},{"a":false,"q":"A Administração pode criar novas modalidades de licitação combinando as previstas em lei.","why":"O art. 28, § 2º, veda a criação de outras modalidades e a combinação das existentes.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"O art. 28, § 2º, veda a criação de outras modalidades e a combinação das existentes.","origin":"retained_and_rechecked"},{"a":true,"q":"Concorrência é modalidade de licitação.","why":"Art. 28, II.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28, II.","origin":"retained_and_rechecked"},{"a":true,"q":"Diálogo competitivo é modalidade de licitação.","why":"Art. 28, V.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28, V.","origin":"retained_and_rechecked"},{"a":true,"q":"Leilão é modalidade de licitação.","why":"Art. 28, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28, IV.","origin":"retained_and_rechecked"},{"a":true,"q":"Concurso é modalidade de licitação.","why":"Art. 28, III.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28, III.","origin":"retained_and_rechecked"},{"a":false,"q":"Convite consta do art. 28 como modalidade vigente.","why":"Art. 28.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28.","origin":"retained_and_rechecked"},{"a":true,"q":"A criação de outras modalidades de licitação é vedada.","why":"Art. 28, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 28, § 2º.","origin":"retained_and_rechecked"},{"a":true,"q":"Menor preço é critério de julgamento.","why":"Art. 33, I.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 33, I.","origin":"retained_and_rechecked"},{"a":true,"q":"Maior desconto é critério de julgamento.","why":"Art. 33, II.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 33, II.","origin":"retained_and_rechecked"},{"a":true,"q":"Melhor técnica ou conteúdo artístico é critério de julgamento.","why":"Art. 33, III.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 33, III.","origin":"retained_and_rechecked"},{"a":true,"q":"Maior lance é critério de julgamento.","why":"Art. 33, V.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 33, V.","origin":"retained_and_rechecked"},{"a":true,"q":"Maior retorno econômico é critério de julgamento.","why":"Art. 33, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 33, VI.","origin":"retained_and_rechecked"},{"a":false,"q":"A habilitação sempre precede o julgamento das propostas.","why":"Art. 17.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 17.","origin":"retained_and_rechecked"},{"a":true,"q":"A fase preparatória integra a licitação.","why":"Art. 17, I.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 17, I.","origin":"retained_and_rechecked"},{"a":true,"q":"A fase recursal integra a licitação.","why":"Art. 17, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 17, VI.","origin":"retained_and_rechecked"},{"a":true,"q":"A homologação é fase da licitação.","why":"Art. 17, VII.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Art. 17, VII.","origin":"retained_and_rechecked"},{"a":true,"q":"O pregão é destinado a bens e serviços comuns.","why":"Arts. 6º, XLI, e 29.","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","article":"Arts. 6º, XLI, e 29.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"9ccc0e28-dffc-434f-a586-4c115e7c5bc8","quiz":[{"a":false,"q":"A tomada de preços continua sendo modalidade de licitação na Lei 14.133/2021.","why":"O art. 28 lista cinco modalidades e não inclui convite nem tomada de preços."},{"a":true,"q":"O pregão é a modalidade para bens e serviços comuns, observadas as exclusões e a ressalva de serviços comuns de engenharia do art. 29.","why":"Leia conjuntamente os arts. 6º, XLI, e 29; não estenda o pregão a toda obra ou serviço técnico predominantemente intelectual."},{"a":false,"q":"É permitida a inexigibilidade de licitação para serviços de publicidade e divulgação com notória especialização.","why":"O art. 74, III, veda a inexigibilidade para serviços de publicidade e divulgação."},{"a":false,"q":"A Administração pode criar novas modalidades de licitação combinando as previstas em lei.","why":"O art. 28, § 2º, veda a criação de outras modalidades e a combinação das existentes."},{"a":true,"q":"Concorrência é modalidade de licitação.","why":"Art. 28, II."},{"a":true,"q":"Diálogo competitivo é modalidade de licitação.","why":"Art. 28, V."},{"a":true,"q":"Leilão é modalidade de licitação.","why":"Art. 28, IV."},{"a":true,"q":"Concurso é modalidade de licitação.","why":"Art. 28, III."},{"a":false,"q":"Convite consta do art. 28 como modalidade vigente.","why":"Art. 28."},{"a":true,"q":"A criação de outras modalidades de licitação é vedada.","why":"Art. 28, § 2º."},{"a":true,"q":"Menor preço é critério de julgamento.","why":"Art. 33, I."},{"a":true,"q":"Maior desconto é critério de julgamento.","why":"Art. 33, II."},{"a":true,"q":"Melhor técnica ou conteúdo artístico é critério de julgamento.","why":"Art. 33, III."},{"a":true,"q":"Maior lance é critério de julgamento.","why":"Art. 33, V."},{"a":true,"q":"Maior retorno econômico é critério de julgamento.","why":"Art. 33, VI."},{"a":false,"q":"A habilitação sempre precede o julgamento das propostas.","why":"Art. 17."},{"a":true,"q":"A fase preparatória integra a licitação.","why":"Art. 17, I."},{"a":true,"q":"A fase recursal integra a licitação.","why":"Art. 17, VI."},{"a":true,"q":"A homologação é fase da licitação.","why":"Art. 17, VII."},{"a":true,"q":"O pregão é destinado a bens e serviços comuns.","why":"Arts. 6º, XLI, e 29."}],"slug":"administrativo-licitacoes-lei-14133-modalidades","title":"Licitações: princípios, modalidades e inexigibilidade na Lei nº 14.133/2021","body_md":"## Qual lei vale\n\nA Lei 14.133/2021 é a lei geral atual de licitações e contratos. O art. 193, II, na redação da **Lei Complementar 198/2023**, fixou a revogação da Lei 8.666/1993, da Lei 10.520/2002 e dos arts. 1º a 47-A do RDC em **30/12/2023**. Contratos e escolhas válidas do período de transição conservam o regime próprio nas condições dos arts. 190 e 191; a revogação não converte automaticamente contratos antigos em novos. É vedada a combinação de regimes.\n\n> **Valores de 2026:** o **Decreto 12.807/2025**, vigente desde 01/01/2026, atualiza os limites. Nas hipóteses do art. 75, I e II, os valores são, respectivamente, R$ 130.984,20 e R$ 65.492,11. Confira o objeto, as condições legais e as regras de fracionamento antes de aplicar dispensa por valor; não use os valores nominais originais da lei.\n\n## Princípios (art. 5º)\n\nLegalidade, impessoalidade, moralidade, publicidade, eficiência, interesse público, probidade administrativa, igualdade, **planejamento**, **transparência**, **eficácia**, **segregação de funções**, motivação, vinculação ao edital, julgamento objetivo, segurança jurídica, razoabilidade, **competitividade**, proporcionalidade, **celeridade**, **economicidade** e **desenvolvimento nacional sustentável**, além das disposições da **LINDB** (Decreto-Lei nº 4.657/1942).\n\n## As cinco modalidades (art. 28)\n\n| Modalidade | Para quê |\n|---|---|\n| **Pregão** | Para bens e serviços comuns; observar os limites do art. 29, parágrafo único, inclusive obras e serviços de engenharia e a exceção dos serviços comuns de engenharia; julgamento por menor preço ou maior desconto |\n| **Concorrência** | Bens e serviços **especiais** e **obras e serviços comuns e especiais de engenharia** |\n| **Concurso** | Escolha de **trabalho técnico, científico ou artístico**, por **melhor técnica ou conteúdo artístico**, com prêmio ou remuneração ao vencedor |\n| **Leilão** | **Alienação** de bens **imóveis** ou de bens **móveis inservíveis ou legalmente apreendidos**, a quem der o **maior lance** |\n| **Diálogo competitivo** | Obras, serviços e compras em que a Administração **dialoga com licitantes previamente selecionados** para desenvolver alternativas, e depois recebe a **proposta final** |\n\n- É **vedado criar outras modalidades** ou **combinar** as existentes (art. 28, § 2º).\n- **Convite** e **tomada de preços**, da Lei nº 8.666/1993, **não constam** do rol da lei atual.\n- A **modalidade nova** é o **diálogo competitivo**.\n- A lei admite ainda **procedimentos auxiliares** (art. 28, § 1º).\n\n## Inexigibilidade (art. 74)\n\nÉ **inexigível** a licitação quando **inviável a competição**, **em especial** nos casos de:\n\n1. **Fornecedor exclusivo** (produtor, empresa ou representante comercial exclusivo). A Administração deve demonstrar a inviabilidade com atestado ou contrato de exclusividade, declaração do fabricante ou documento idôneo, **vedada a preferência por marca específica** (§ 1º).\n2. **Profissional do setor artístico**, diretamente ou por empresário exclusivo, **consagrado pela crítica especializada ou pela opinião pública**. O empresário exclusivo precisa ter exclusividade **permanente e contínua**, e não apenas para evento ou local específico (§ 2º).\n3. **Serviços técnicos especializados de natureza predominantemente intelectual**, com profissionais ou empresas de **notória especialização**, como estudos técnicos e projetos, consultorias e auditorias, fiscalização e supervisão de obras, patrocínio ou defesa de causas judiciais ou administrativas e restauração de obras de arte. **Vedada a inexigibilidade para serviços de publicidade e divulgação**.\n\nO rol do art. 74 é **exemplificativo** (\"em especial\"). Na hipótese do inciso III, é **vedada a subcontratação** de outras empresas e a atuação de profissionais diferentes dos que justificaram a inexigibilidade (§ 4º).\n\n> **Cai em prova:** inexigibilidade é **inviabilidade de competição**; dispensa é possibilidade de competir, mas com autorização legal para não licitar. E o **pregão** é **obrigatório** para bens e serviços comuns.","summary":"Os princípios do art. 5º, as cinco modalidades, o que desapareceu da Lei nº 8.666/1993 e os casos de inexigibilidade.","created_at":"2026-10-01T03:51:38.980016+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Pregão, concorrência, concurso, leilão e diálogo competitivo (art. 28). É vedado criar outras ou combiná-las.","f":"Quais são as modalidades de licitação da Lei 14.133/2021?"},{"b":"O diálogo competitivo. Convite e tomada de preços, da Lei 8.666/1993, não constam do rol atual.","f":"Modalidade nova da Lei 14.133/2021"},{"b":"Obrigatório para bens e serviços comuns; critério de menor preço ou maior desconto.","f":"Pregão"},{"b":"Quando inviável a competição, em especial: fornecedor exclusivo, artista consagrado e serviço técnico especializado de natureza intelectual com notória especialização.","f":"Inexigibilidade (art. 74)"},{"b":"Alienação de imóveis ou de móveis inservíveis ou legalmente apreendidos, a quem oferecer o maior lance.","f":"Leilão"}],"sort_order":50,"updated_at":"2026-10-24T19:59:47.556197+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","title":"Lei nº 14.133/2021 (Nova Lei de Licitações e Contratos Administrativos)"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","title":"Fonte oficial complementar — d12807.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp198.htm","title":"Fonte oficial complementar — lcp198.htm"}],"reviewed_at":"2026-10-07T21:37:20.649815+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Elaborado diretamente a partir do texto da Lei nº 14.133/2021 no Planalto (arts. 5º, 6º, 28, 74 e 193), com organização e destaques próprios. Não usa o resumo de licitações da pasta Apostilas. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Licitações e contratos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15471.htm","state":"effective","title":"LEI Nº 15.471/2026","summary":"Institui a Estratégia Nacional de Saúde do Complexo Econômico-Industrial da Saúde (Ensceis); e altera a Lei nº 6.360, de 23 de setembro de 1976, a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), e a Lei nº 8.080, de 19 de setembro de 1990 (Lei Orgânica da Saúde).","vigency":"Art. 39. Esta Lei entra em vigor na data de sua publicação.","articles":["Art. 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Lei/L15266.htm","state":"effective","title":"LEI Nº 15.266/2025","summary":"Altera a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), para prever o uso do Sistema de Compras Expressas (Sicx) na contratação de bens e serviços comuns padronizados.","vigency":"Art. 2º Esta Lei entra em vigor na data de sua publicação.","articles":["Art. 79","Art. 87","Art. 174","Art. 175"]},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Lei/L15210.htm","state":"effective","title":"LEI Nº 15.210/2025","summary":"Altera a Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos Administrativos), para estabelecer requisitos para a compra de equipamentos destinados a procedimentos diagnósticos ou terapêuticos no âmbito do Sistema Único de Saúde (SUS).","vigency":"Art. 2º Esta Lei entra em vigor após decorridos 180 (cento e oitenta) dias de sua publicação oficial. Publicação: 17/09/2025. Entrada em vigor calculada pelo prazo legal: 16/03/2026.","articles":["Art. 44-A"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","state":"effective","title":"DECRETO Nº 12.807/2025","summary":"DECRETO Nº 12.807/2025","vigency":"Art. 5º Este Decreto entra em vigor em 1º de janeiro de 2026.","articles":["Art. 6","Art. 37","Art. 70","Art. 75","Art. 95","Art. 184-A"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","title":"Lei nº 14.133/2021 (Nova Lei de Licitações e Contratos Administrativos)","sha256":"c846050b2949dfabff9a119dd84171161bd703a757394f03b0e5538ceedd3d09"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","title":"Fonte oficial complementar — d12807.htm","sha256":"a57c65cbeae48f68224545a9b3961c9530a4833ed07347ba9abeced96699beae"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp198.htm","title":"Fonte oficial complementar — lcp198.htm","sha256":"b755a8248b563efe76c339c5ab3b0933a7e5dcdf8b69aa80ef50f68c8a799b39"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigida a data efetiva de revogação; incluídos os limites atualizados de dispensa para 2026 e as ressalvas do pregão."],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":false,"q":"A tomada de preços continua sendo modalidade de licitação na Lei 14.133/2021.","why":"O art. 28 lista cinco modalidades e não inclui convite nem tomada de preços.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"O pregão é a modalidade para bens e serviços comuns, observadas as exclusões e a ressalva de serviços comuns de engenharia do art. 29.","why":"Leia conjuntamente os arts. 6º, XLI, e 29; não estenda o pregão a toda obra ou serviço técnico predominantemente intelectual.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":false,"q":"É permitida a inexigibilidade de licitação para serviços de publicidade e divulgação com notória especialização.","why":"O art. 74, III, veda a inexigibilidade para serviços de publicidade e divulgação.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":false,"q":"A Administração pode criar novas modalidades de licitação combinando as previstas em lei.","why":"O art. 28, § 2º, veda a criação de outras modalidades e a combinação das existentes.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Concorrência é modalidade de licitação.","why":"Art. 28, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Diálogo competitivo é modalidade de licitação.","why":"Art. 28, V.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Leilão é modalidade de licitação.","why":"Art. 28, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Concurso é modalidade de licitação.","why":"Art. 28, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":false,"q":"Convite consta do art. 28 como modalidade vigente.","why":"Art. 28.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"A criação de outras modalidades de licitação é vedada.","why":"Art. 28, § 2º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Menor preço é critério de julgamento.","why":"Art. 33, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Maior desconto é critério de julgamento.","why":"Art. 33, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Melhor técnica ou conteúdo artístico é critério de julgamento.","why":"Art. 33, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Maior lance é critério de julgamento.","why":"Art. 33, V.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"Maior retorno econômico é critério de julgamento.","why":"Art. 33, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":false,"q":"A habilitação sempre precede o julgamento das propostas.","why":"Art. 17.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"A fase preparatória integra a licitação.","why":"Art. 17, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"A fase recursal integra a licitação.","why":"Art. 17, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"A homologação é fase da licitação.","why":"Art. 17, VII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"},{"a":true,"q":"O pregão é destinado a bens e serviços comuns.","why":"Arts. 6º, XLI, e 29.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"administrativo-licitacoes-lei-14133-modalidades","syllabus_topic_id":"5554ba99-721b-49c0-a696-bf42e229034f"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"a0a24d96-eb6b-50e4-8b2f-cc49b6ef05ed","status":"active","content":{"cases":[{"id":"case-1","steps":["Inexigibilidade pressupõe inviabilidade de competição, nas hipóteses legalmente caracterizadas.","Preferência pessoal não comprova exclusividade nem substitui a instrução do processo de contratação direta."],"title":"Inexigibilidade não é mera preferência","pitfall":"Confundir inexigibilidade com dispensa ou liberdade sem motivação.","articles":["Lei 14.133/2021, arts. 72 e 74"],"question":"Essa preferência demonstra inexigibilidade?","scenario":"A Administração afirma que gosta mais de um fornecedor e pretende contratar diretamente, embora existam concorrentes aptos.","variation":{"answer":"Examine o art. 74 e a documentação exigida; a inviabilidade deve ser demonstrada, não apenas afirmada.","scenario":"E se houver fornecedor exclusivo, com comprovação adequada, para o objeto justificadamente necessário?"},"conclusion":"O motivo descrito é insuficiente. A contratação direta precisa de hipótese legal e instrução própria."}],"illustrations":[{"kind":"flow","nodes":["Inexigibilidade não é mera preferência","Essa preferência demonstra inexigibilidade?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","title":"Lei nº 14.133/2021 (Nova Lei de Licitações e Contratos Administrativos)","sha256":"02cbdfed31cd041252436ab25df718d963535a9e954ecc6445fa37ec9b7befc9","checked_at":"2026-10-05T04:33:19.237136+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:39.163+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"administrativo-licitacoes-lei-14133-modalidades","source_body_sha256":"6b6339e49463a4955146c819c9102b7d81ecd33fe7d9b59a96cf0e97563f1add"}],"enrichment":{"id":"74710ae1-9193-535b-b066-545cd47352b3","material_slug":"administrativo-licitacoes-lei-14133-modalidades","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"d4c1fed7ba9c3ceeeba1413a29e271236a48a9c84c264fbdf17fbdc6e3a67206","content":{"cases":[{"id":"case-1","steps":["Inexigibilidade pressupõe inviabilidade de competição, nas hipóteses legalmente caracterizadas.","Preferência pessoal não comprova exclusividade nem substitui a instrução do processo de contratação direta."],"title":"Inexigibilidade não é mera preferência","pitfall":"Confundir inexigibilidade com dispensa ou liberdade sem motivação.","articles":["Lei 14.133/2021, arts. 72 e 74"],"question":"Essa preferência demonstra inexigibilidade?","scenario":"A Administração afirma que gosta mais de um fornecedor e pretende contratar diretamente, embora existam concorrentes aptos.","variation":{"answer":"Examine o art. 74 e a documentação exigida; a inviabilidade deve ser demonstrada, não apenas afirmada.","scenario":"E se houver fornecedor exclusivo, com comprovação adequada, para o objeto justificadamente necessário?"},"conclusion":"O motivo descrito é insuficiente. A contratação direta precisa de hipótese legal e instrução própria."},{"id":"complemento-20261024","title":"Alteração que afeta a proposta","scenario":"A Administração muda especificação essencial do objeto depois de divulgar o edital e pretende manter o prazo original.","question":"Qual regra precisa ser aplicada?","steps":["Identifique o regime legal atual.","Verifique o efeito da alteração na formulação das propostas.","Aplique a nova divulgação e os prazos do art. 55, § 1º."],"conclusion":"Mudança que compromete a formulação exige divulgação e observância dos mesmos prazos originais.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"A correção é meramente formal e não compromete a formulação.","answer":"A ressalva legal pode afastar a repetição do prazo; a conclusão depende desse efeito."},"articles":["Lei 14.133/2021, art. 55, § 1º"]}],"illustrations":[{"kind":"flow","nodes":["Inexigibilidade não é mera preferência","Essa preferência demonstra inexigibilidade?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"key":"l14133","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","bytes":649705,"sha256":"6e747b82f9d1f660beeda5c2a9b75e6ff3881d21bd92d2618c032cba4dbab13f","checked_at":"2026-10-24T22:17:18.861233+00:00","title":"Lei 14.133/2021 — licitações e contratos"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","title":"Fonte oficial complementar — d12807.htm","sha256":"a57c65cbeae48f68224545a9b3961c9530a4833ed07347ba9abeced96699beae"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp198.htm","title":"Fonte oficial complementar — lcp198.htm","sha256":"b755a8248b563efe76c339c5ab3b0933a7e5dcdf8b69aa80ef50f68c8a799b39"},{"key":"l13303","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm","bytes":248652,"sha256":"081e50a5e352f44fbf734df5da72be27d675c827d380126e990fb6b225b35f35","checked_at":"2026-10-24T22:17:17.994894+00:00","title":"Lei 13.303/2016 — estatais"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"ac83e2cb-8a42-4c89-a258-01a2dcb7d876","quiz":[{"a":false,"q":"O art. 37, § 6º da CF afirma expressamente que a responsabilidade do Estado é objetiva.","why":"O texto não usa a palavra objetiva; essa leitura é de doutrina e jurisprudência."},{"a":true,"q":"A ação regressiva exige dolo ou culpa do agente público.","why":"É o que diz a parte final do art. 37, § 6º."},{"q":"Toda empresa pública exploradora de atividade econômica se submete automaticamente ao art. 37, § 6º, apenas por ser estatal, independentemente da atividade exercida.","a":false,"why":"O art. 37, § 6º, refere-se a pessoas públicas e a pessoas privadas prestadoras de serviços públicos; o simples controle estatal não basta para essa extensão."},{"a":true,"q":"O Estado indeniza quem ficar preso além do tempo fixado na sentença.","why":"Art. 5º, LXXV, da Constituição."},{"a":true,"q":"A Constituição prevê que pessoas jurídicas de direito público respondam por danos causados a terceiros por seus agentes, nessa qualidade.","why":"CF, art. 37, § 6º."},{"a":true,"q":"A regra constitucional do art. 37, § 6º também alcança pessoas jurídicas de direito privado prestadoras de serviços públicos.","why":"CF, art. 37, § 6º."},{"a":true,"q":"O direito de regresso contra o agente responsável é assegurado nos casos de dolo ou culpa.","why":"CF, art. 37, § 6º."},{"a":false,"q":"O art. 37, § 6º exige expressamente condenação criminal do agente para que a vítima seja indenizada.","why":"CF, art. 37, § 6º: não condiciona a responsabilidade à condenação criminal."},{"a":true,"q":"A responsabilidade prevista no art. 37, § 6º exige que o dano seja causado por agente atuando nessa qualidade.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A regra constitucional sobre responsabilidade por danos causados por agentes exclui as pessoas jurídicas de direito privado prestadoras de serviço público.","why":"CF, art. 37, § 6º: inclui expressamente essas prestadoras."},{"a":true,"q":"O Estado indenizará o condenado por erro judiciário, nos termos da Constituição.","why":"CF, art. 5º, LXXV."},{"a":true,"q":"A indenização por prisão além do tempo fixado na sentença está prevista no art. 5º, LXXV.","why":"CF, art. 5º, LXXV."},{"a":false,"q":"A Constituição exige que a ação regressiva seja proposta somente quando houver dolo, afastando a culpa.","why":"CF, art. 37, § 6º: admite dolo ou culpa."},{"a":true,"q":"O dever constitucional de indenizar do art. 37, § 6º refere-se a danos causados a terceiros.","why":"CF, art. 37, § 6º."},{"a":true,"q":"A Constituição prevê responsabilidade pelos danos causados por agentes públicos nessa qualidade, mesmo sem utilizar literalmente a expressão 'responsabilidade objetiva'.","why":"CF, art. 37, § 6º; texto constitucional não usa essa expressão."},{"a":false,"q":"O art. 37, § 6º restringe a responsabilidade nele prevista aos órgãos da administração direta federal.","why":"CF, art. 37, § 6º: refere-se às pessoas jurídicas de direito público e prestadoras privadas de serviços públicos."},{"a":true,"q":"A garantia de regresso prevista na Constituição dirige-se ao agente responsável pelo dano.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A Constituição afirma que toda pessoa jurídica de direito privado, independentemente da atividade exercida, se submete ao art. 37, § 6º.","why":"CF, art. 37, § 6º: limita a referência às pessoas jurídicas privadas prestadoras de serviços públicos."},{"a":true,"q":"A responsabilidade constitucional por danos causados por agentes em serviço público não elimina a possibilidade de regresso contra o responsável.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A regra do art. 5º, LXXV, limita a indenização por erro judiciário às hipóteses de prisão além do tempo fixado na sentença.","why":"CF, art. 5º, LXXV: contempla tanto erro judiciário quanto prisão além do tempo fixado."}],"slug":"administrativo-responsabilidade-civil-do-estado","title":"Responsabilidade civil do Estado","body_md":"## Base constitucional (art. 37, § 6º)\n\n> *As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.*\n\nO texto constitucional **não usa a palavra \"objetiva\"**; a responsabilidade **sem necessidade de provar culpa** do Estado é a leitura da **doutrina e da jurisprudência** (teoria do **risco administrativo**).\n\n## Quem responde\n\n| Responde na forma do art. 37, § 6º | Observação |\n|---|---|\n| Administração **direta**, autarquias e fundações públicas | Pessoas jurídicas de **direito público** |\n| Empresas públicas, sociedades de economia mista e fundações **prestadoras de serviço público** | Direito privado, mas **prestadoras de serviço público** |\n| **Concessionárias, permissionárias e autorizadas** de serviço público | Delegatárias |\n\nEstatais **exploradoras de atividade econômica** ficam **fora** dessa regra: seguem o regime do direito privado (civil ou comercial).\n\nA responsabilidade das prestadoras de serviço público abrange os danos aos **usuários** e também a **terceiros não usuários** (entendimento consolidado pelo STF). O agente deve estar **exercendo a função** ou agir **nessa qualidade**.\n\n## Conduta comissiva × omissiva\n\n| | Conduta **comissiva** (ação) | Conduta **omissiva** |\n|---|---|---|\n| **Teoria** | **Risco administrativo** | **Culpa administrativa** (culpa anônima, falta do serviço) |\n| **Natureza** | Objetiva | Em regra **subjetiva**: é preciso demonstrar a **falta do serviço** |\n| **Prova** | Dano, conduta e nexo causal | Também a omissão culposa |\n\n**Excludentes** de responsabilidade (ou atenuantes, conforme o caso): **culpa exclusiva da vítima**, **fato exclusivo de terceiro** e **força maior**.\n\n## Atos legislativos e judiciais\n\n- **Legislativos:** em regra **não geram** responsabilidade; as exceções clássicas são **lei inconstitucional** e **lei de efeitos concretos**.\n- **Judiciais:** regra geral de **irresponsabilidade**, mas o Estado **indeniza o condenado por erro judiciário** e quem **ficar preso além do tempo fixado na sentença** (CF, art. 5º, LXXV).\n\n## Ação de reparação e ação regressiva\n\n- A vítima pode obter **acordo administrativo** ou ajuizar ação **contra a pessoa jurídica** (e não direto contra o agente, entendimento do STF no mapa de origem).\n- O regresso deve observar o dano e a responsabilidade do agente por dolo ou culpa, após a reparação pela pessoa jurídica. Não trate condenação judicial prévia como requisito universal: o pagamento pode decorrer de solução administrativa válida. O **Tema 940/STF** orienta a ação indenizatória contra a pessoa jurídica, assegurando o regresso.\n- Para o **prazo prescricional** da ação de reparação contra a Fazenda, o resumo de origem cita **5 anos** (Decreto nº 20.910/1932 e Lei nº 9.494/1997, art. 1º-C). O art. 1º do Decreto 20.910/1932 e o art. 1º-C da Lei 9.494/1997 foram conferidos nesta revisão; examine o termo inicial e as regras específicas do caso.\n\n> **Conferido na Constituição (Planalto e Constituição anotada do STF):** o art. 37, § 6º e o art. 5º, LXXV foram conferidos com o texto atual. O reconhecimento da responsabilidade **objetiva**, a distinção entre ação e omissão e as teses sobre **terceiros não usuários** vêm de **doutrina e de jurisprudência** do STF, não do texto constitucional: ao responder, cite-as como entendimento, e não como dispositivo.\n\n### Omissão: examine o dever específico\n\nNão transforme a regra geral sobre omissão em imunidade ou responsabilidade subjetiva em todo caso. No **Tema 592/STF**, a inobservância do dever específico de proteção do art. 5º, XLIX, da Constituição pode gerar responsabilidade pela morte de detento. Identifique o dever, a possibilidade concreta de agir, o dano e o nexo causal; o evento sozinho não dispensa essa análise.\n\n## Leitura crítica de questões antigas\n\nO art. 37, § 6º, protege o terceiro diante dos danos causados por agentes nessa qualidade e assegura regresso contra o responsável por **dolo ou culpa**. Um gabarito que admite regresso apenas por dolo não acompanha a regra constitucional. Também não se deve transformar toda sociedade de economia mista em prestadora de serviço público: a atividade exercida é dado relevante.\n\nEm um caso de veículo apreendido que sofre furto no depósito, a simples informação de que o servidor estava descansando não resolve o problema. Identifique o dever de guarda, as condições de proteção, o dano, o nexo e as circunstâncias capazes de afastá-lo. Eventual responsabilidade pessoal do servidor exige análise própria; não nasce automaticamente da indenização estatal.\n\nItens que pedem solução categórica de omissão, custódia ou evento de terceiro sem fornecer elementos suficientes não foram incorporados como regras gerais. A distinção já apresentada neste material sobre dever específico de proteção deve ser mantida, e o precedente pertinente precisa ser consultado antes da aplicação a outro contexto. Base constitucional deste complemento: arts. 5º, XLIX e LXXV, e 37, § 6º.\n","summary":"Quem responde, por quê, a conduta comissiva e a omissiva, a ação regressiva e os atos legislativos e judiciais.","created_at":"2026-10-01T03:49:21.570929+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Pessoas jurídicas de direito público e privadas prestadoras de serviço público respondem pelos danos que seus agentes, nessa qualidade, causarem a terceiros, com direito de regresso contra o responsável nos casos de dolo ou culpa.","f":"Texto do art. 37, § 6º da CF"},{"b":"Comissiva: risco administrativo (responsabilidade objetiva). Omissiva: em regra culpa administrativa, com prova da falta do serviço.","f":"Conduta comissiva × omissiva"},{"b":"As exploradoras de atividade econômica, regidas pelo direito privado.","f":"Estatais que ficam fora do art. 37, § 6º"},{"b":"Reparação do dano pela pessoa jurídica e responsabilidade do agente por dolo ou culpa; condenação judicial prévia não é uma exigência universal do texto constitucional.","f":"Requisitos da ação regressiva"},{"b":"Em regra irresponsabilidade, mas o Estado indeniza o erro judiciário e a prisão além do tempo fixado na sentença (CF, art. 5º, LXXV).","f":"Responsabilidade por atos judiciais"}],"sort_order":40,"updated_at":"2026-10-24T18:56:36.657877+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto/antigos/d20910.htm","title":"Fonte oficial complementar — d20910.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9494.htm","title":"Fonte oficial complementar — l9494.htm"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto atual da Constituição e da Lei nº 8.429/1992 no Planalto. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Responsabilidade civil","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto/antigos/d20910.htm","title":"Fonte oficial complementar — d20910.htm","sha256":"2d1e79de5096840bfd47b9d880b2cd4afbe49cb6636a5863b2ec19a1142f865f"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9494.htm","title":"Fonte oficial complementar — l9494.htm","sha256":"e43689a7efc0fec7da0bc9c936d867e4ba2dba263a7a741b039ba2ef84729bee"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=940","title":"STF — Tema 940"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=4645403&numeroProcesso=841526&numeroTema=592","title":"STF — Tema 592"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Retirada exigência universal de condenação judicial prévia para regresso e conferidas as referências de prescrição citadas.","Acrescentada a distinção de dever específico de proteção no Tema 592/STF.","Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-responsabilidade-civil-do-estado","subject":"Direito Administrativo","topic_label":"Responsabilidade civil","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"items":[{"a":false,"q":"O art. 37, § 6º da CF afirma expressamente que a responsabilidade do Estado é objetiva.","why":"O texto não usa a palavra objetiva; essa leitura é de doutrina e jurisprudência.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"O texto não usa a palavra objetiva; essa leitura é de doutrina e jurisprudência.","origin":"retained_and_rechecked"},{"a":true,"q":"A ação regressiva exige dolo ou culpa do agente público.","why":"É o que diz a parte final do art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"É o que diz a parte final do art. 37, § 6º.","origin":"retained_and_rechecked"},{"q":"Toda empresa pública exploradora de atividade econômica se submete automaticamente ao art. 37, § 6º, apenas por ser estatal, independentemente da atividade exercida.","a":false,"why":"O art. 37, § 6º, refere-se a pessoas públicas e a pessoas privadas prestadoras de serviços públicos; o simples controle estatal não basta para essa extensão.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"O art. 37, § 6º, refere-se a pessoas públicas e a pessoas privadas prestadoras de serviços públicos; o simples controle estatal não basta para essa extensão.","origin":"clarified_current_official_text"},{"a":true,"q":"O Estado indeniza quem ficar preso além do tempo fixado na sentença.","why":"Art. 5º, LXXV, da Constituição.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXV, da Constituição.","origin":"retained_and_rechecked"},{"a":true,"q":"A Constituição prevê que pessoas jurídicas de direito público respondam por danos causados a terceiros por seus agentes, nessa qualidade.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":true,"q":"A regra constitucional do art. 37, § 6º também alcança pessoas jurídicas de direito privado prestadoras de serviços públicos.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":true,"q":"O direito de regresso contra o agente responsável é assegurado nos casos de dolo ou culpa.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":false,"q":"O art. 37, § 6º exige expressamente condenação criminal do agente para que a vítima seja indenizada.","why":"CF, art. 37, § 6º: não condiciona a responsabilidade à condenação criminal.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º: não condiciona a responsabilidade à condenação criminal.","origin":"retained_and_rechecked"},{"a":true,"q":"A responsabilidade prevista no art. 37, § 6º exige que o dano seja causado por agente atuando nessa qualidade.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":false,"q":"A regra constitucional sobre responsabilidade por danos causados por agentes exclui as pessoas jurídicas de direito privado prestadoras de serviço público.","why":"CF, art. 37, § 6º: inclui expressamente essas prestadoras.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º: inclui expressamente essas prestadoras.","origin":"retained_and_rechecked"},{"a":true,"q":"O Estado indenizará o condenado por erro judiciário, nos termos da Constituição.","why":"CF, art. 5º, LXXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 5º, LXXV.","origin":"retained_and_rechecked"},{"a":true,"q":"A indenização por prisão além do tempo fixado na sentença está prevista no art. 5º, LXXV.","why":"CF, art. 5º, LXXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 5º, LXXV.","origin":"retained_and_rechecked"},{"a":false,"q":"A Constituição exige que a ação regressiva seja proposta somente quando houver dolo, afastando a culpa.","why":"CF, art. 37, § 6º: admite dolo ou culpa.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º: admite dolo ou culpa.","origin":"retained_and_rechecked"},{"a":true,"q":"O dever constitucional de indenizar do art. 37, § 6º refere-se a danos causados a terceiros.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":true,"q":"A Constituição prevê responsabilidade pelos danos causados por agentes públicos nessa qualidade, mesmo sem utilizar literalmente a expressão 'responsabilidade objetiva'.","why":"CF, art. 37, § 6º; texto constitucional não usa essa expressão.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º; texto constitucional não usa essa expressão.","origin":"retained_and_rechecked"},{"a":false,"q":"O art. 37, § 6º restringe a responsabilidade nele prevista aos órgãos da administração direta federal.","why":"CF, art. 37, § 6º: refere-se às pessoas jurídicas de direito público e prestadoras privadas de serviços públicos.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º: refere-se às pessoas jurídicas de direito público e prestadoras privadas de serviços públicos.","origin":"retained_and_rechecked"},{"a":true,"q":"A garantia de regresso prevista na Constituição dirige-se ao agente responsável pelo dano.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":false,"q":"A Constituição afirma que toda pessoa jurídica de direito privado, independentemente da atividade exercida, se submete ao art. 37, § 6º.","why":"CF, art. 37, § 6º: limita a referência às pessoas jurídicas privadas prestadoras de serviços públicos.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º: limita a referência às pessoas jurídicas privadas prestadoras de serviços públicos.","origin":"retained_and_rechecked"},{"a":true,"q":"A responsabilidade constitucional por danos causados por agentes em serviço público não elimina a possibilidade de regresso contra o responsável.","why":"CF, art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 37, § 6º.","origin":"retained_and_rechecked"},{"a":false,"q":"A regra do art. 5º, LXXV, limita a indenização por erro judiciário às hipóteses de prisão além do tempo fixado na sentença.","why":"CF, art. 5º, LXXV: contempla tanto erro judiciário quanto prisão além do tempo fixado.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"CF, art. 5º, LXXV: contempla tanto erro judiciário quanto prisão além do tempo fixado.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"ac83e2cb-8a42-4c89-a258-01a2dcb7d876","quiz":[{"a":false,"q":"O art. 37, § 6º da CF afirma expressamente que a responsabilidade do Estado é objetiva.","why":"O texto não usa a palavra objetiva; essa leitura é de doutrina e jurisprudência."},{"a":true,"q":"A ação regressiva exige dolo ou culpa do agente público.","why":"É o que diz a parte final do art. 37, § 6º."},{"a":false,"q":"Empresa pública exploradora de atividade econômica responde na forma do art. 37, § 6º.","why":"Ficam fora da regra as exploradoras de atividade econômica."},{"a":true,"q":"O Estado indeniza quem ficar preso além do tempo fixado na sentença.","why":"Art. 5º, LXXV, da Constituição."},{"a":true,"q":"A Constituição prevê que pessoas jurídicas de direito público respondam por danos causados a terceiros por seus agentes, nessa qualidade.","why":"CF, art. 37, § 6º."},{"a":true,"q":"A regra constitucional do art. 37, § 6º também alcança pessoas jurídicas de direito privado prestadoras de serviços públicos.","why":"CF, art. 37, § 6º."},{"a":true,"q":"O direito de regresso contra o agente responsável é assegurado nos casos de dolo ou culpa.","why":"CF, art. 37, § 6º."},{"a":false,"q":"O art. 37, § 6º exige expressamente condenação criminal do agente para que a vítima seja indenizada.","why":"CF, art. 37, § 6º: não condiciona a responsabilidade à condenação criminal."},{"a":true,"q":"A responsabilidade prevista no art. 37, § 6º exige que o dano seja causado por agente atuando nessa qualidade.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A regra constitucional sobre responsabilidade por danos causados por agentes exclui as pessoas jurídicas de direito privado prestadoras de serviço público.","why":"CF, art. 37, § 6º: inclui expressamente essas prestadoras."},{"a":true,"q":"O Estado indenizará o condenado por erro judiciário, nos termos da Constituição.","why":"CF, art. 5º, LXXV."},{"a":true,"q":"A indenização por prisão além do tempo fixado na sentença está prevista no art. 5º, LXXV.","why":"CF, art. 5º, LXXV."},{"a":false,"q":"A Constituição exige que a ação regressiva seja proposta somente quando houver dolo, afastando a culpa.","why":"CF, art. 37, § 6º: admite dolo ou culpa."},{"a":true,"q":"O dever constitucional de indenizar do art. 37, § 6º refere-se a danos causados a terceiros.","why":"CF, art. 37, § 6º."},{"a":true,"q":"A Constituição prevê responsabilidade pelos danos causados por agentes públicos nessa qualidade, mesmo sem utilizar literalmente a expressão 'responsabilidade objetiva'.","why":"CF, art. 37, § 6º; texto constitucional não usa essa expressão."},{"a":false,"q":"O art. 37, § 6º restringe a responsabilidade nele prevista aos órgãos da administração direta federal.","why":"CF, art. 37, § 6º: refere-se às pessoas jurídicas de direito público e prestadoras privadas de serviços públicos."},{"a":true,"q":"A garantia de regresso prevista na Constituição dirige-se ao agente responsável pelo dano.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A Constituição afirma que toda pessoa jurídica de direito privado, independentemente da atividade exercida, se submete ao art. 37, § 6º.","why":"CF, art. 37, § 6º: limita a referência às pessoas jurídicas privadas prestadoras de serviços públicos."},{"a":true,"q":"A responsabilidade constitucional por danos causados por agentes em serviço público não elimina a possibilidade de regresso contra o responsável.","why":"CF, art. 37, § 6º."},{"a":false,"q":"A regra do art. 5º, LXXV, limita a indenização por erro judiciário às hipóteses de prisão além do tempo fixado na sentença.","why":"CF, art. 5º, LXXV: contempla tanto erro judiciário quanto prisão além do tempo fixado."}],"slug":"administrativo-responsabilidade-civil-do-estado","title":"Responsabilidade civil do Estado","body_md":"## Base constitucional (art. 37, § 6º)\n\n> *As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.*\n\nO texto constitucional **não usa a palavra \"objetiva\"**; a responsabilidade **sem necessidade de provar culpa** do Estado é a leitura da **doutrina e da jurisprudência** (teoria do **risco administrativo**).\n\n## Quem responde\n\n| Responde na forma do art. 37, § 6º | Observação |\n|---|---|\n| Administração **direta**, autarquias e fundações públicas | Pessoas jurídicas de **direito público** |\n| Empresas públicas, sociedades de economia mista e fundações **prestadoras de serviço público** | Direito privado, mas **prestadoras de serviço público** |\n| **Concessionárias, permissionárias e autorizadas** de serviço público | Delegatárias |\n\nEstatais **exploradoras de atividade econômica** ficam **fora** dessa regra: seguem o regime do direito privado (civil ou comercial).\n\nA responsabilidade das prestadoras de serviço público abrange os danos aos **usuários** e também a **terceiros não usuários** (entendimento consolidado pelo STF). O agente deve estar **exercendo a função** ou agir **nessa qualidade**.\n\n## Conduta comissiva × omissiva\n\n| | Conduta **comissiva** (ação) | Conduta **omissiva** |\n|---|---|---|\n| **Teoria** | **Risco administrativo** | **Culpa administrativa** (culpa anônima, falta do serviço) |\n| **Natureza** | Objetiva | Em regra **subjetiva**: é preciso demonstrar a **falta do serviço** |\n| **Prova** | Dano, conduta e nexo causal | Também a omissão culposa |\n\n**Excludentes** de responsabilidade (ou atenuantes, conforme o caso): **culpa exclusiva da vítima**, **fato exclusivo de terceiro** e **força maior**.\n\n## Atos legislativos e judiciais\n\n- **Legislativos:** em regra **não geram** responsabilidade; as exceções clássicas são **lei inconstitucional** e **lei de efeitos concretos**.\n- **Judiciais:** regra geral de **irresponsabilidade**, mas o Estado **indeniza o condenado por erro judiciário** e quem **ficar preso além do tempo fixado na sentença** (CF, art. 5º, LXXV).\n\n## Ação de reparação e ação regressiva\n\n- A vítima pode obter **acordo administrativo** ou ajuizar ação **contra a pessoa jurídica** (e não direto contra o agente, entendimento do STF no mapa de origem).\n- O regresso deve observar o dano e a responsabilidade do agente por dolo ou culpa, após a reparação pela pessoa jurídica. Não trate condenação judicial prévia como requisito universal: o pagamento pode decorrer de solução administrativa válida. O **Tema 940/STF** orienta a ação indenizatória contra a pessoa jurídica, assegurando o regresso.\n- Para o **prazo prescricional** da ação de reparação contra a Fazenda, o resumo de origem cita **5 anos** (Decreto nº 20.910/1932 e Lei nº 9.494/1997, art. 1º-C). O art. 1º do Decreto 20.910/1932 e o art. 1º-C da Lei 9.494/1997 foram conferidos nesta revisão; examine o termo inicial e as regras específicas do caso.\n\n> **Conferido na Constituição (Planalto e Constituição anotada do STF):** o art. 37, § 6º e o art. 5º, LXXV foram conferidos com o texto atual. O reconhecimento da responsabilidade **objetiva**, a distinção entre ação e omissão e as teses sobre **terceiros não usuários** vêm de **doutrina e de jurisprudência** do STF, não do texto constitucional: ao responder, cite-as como entendimento, e não como dispositivo.\n\n### Omissão: examine o dever específico\n\nNão transforme a regra geral sobre omissão em imunidade ou responsabilidade subjetiva em todo caso. No **Tema 592/STF**, a inobservância do dever específico de proteção do art. 5º, XLIX, da Constituição pode gerar responsabilidade pela morte de detento. Identifique o dever, a possibilidade concreta de agir, o dano e o nexo causal; o evento sozinho não dispensa essa análise.","summary":"Quem responde, por quê, a conduta comissiva e a omissiva, a ação regressiva e os atos legislativos e judiciais.","created_at":"2026-10-01T03:49:21.570929+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Pessoas jurídicas de direito público e privadas prestadoras de serviço público respondem pelos danos que seus agentes, nessa qualidade, causarem a terceiros, com direito de regresso contra o responsável nos casos de dolo ou culpa.","f":"Texto do art. 37, § 6º da CF"},{"b":"Comissiva: risco administrativo (responsabilidade objetiva). Omissiva: em regra culpa administrativa, com prova da falta do serviço.","f":"Conduta comissiva × omissiva"},{"b":"As exploradoras de atividade econômica, regidas pelo direito privado.","f":"Estatais que ficam fora do art. 37, § 6º"},{"b":"Reparação do dano pela pessoa jurídica e responsabilidade do agente por dolo ou culpa; condenação judicial prévia não é uma exigência universal do texto constitucional.","f":"Requisitos da ação regressiva"},{"b":"Em regra irresponsabilidade, mas o Estado indeniza o erro judiciário e a prisão além do tempo fixado na sentença (CF, art. 5º, LXXV).","f":"Responsabilidade por atos judiciais"}],"sort_order":40,"updated_at":"2026-10-24T18:56:36.657877+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto/antigos/d20910.htm","title":"Fonte oficial complementar — d20910.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9494.htm","title":"Fonte oficial complementar — l9494.htm"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto atual da Constituição e da Lei nº 8.429/1992 no Planalto. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Responsabilidade civil","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto/antigos/d20910.htm","title":"Fonte oficial complementar — d20910.htm","sha256":"2d1e79de5096840bfd47b9d880b2cd4afbe49cb6636a5863b2ec19a1142f865f"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9494.htm","title":"Fonte oficial complementar — l9494.htm","sha256":"e43689a7efc0fec7da0bc9c936d867e4ba2dba263a7a741b039ba2ef84729bee"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=940","title":"STF — Tema 940"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=4645403&numeroProcesso=841526&numeroTema=592","title":"STF — Tema 592"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Retirada exigência universal de condenação judicial prévia para regresso e conferidas as referências de prescrição citadas.","Acrescentada a distinção de dever específico de proteção no Tema 592/STF."],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":false,"q":"O art. 37, § 6º da CF afirma expressamente que a responsabilidade do Estado é objetiva.","why":"O texto não usa a palavra objetiva; essa leitura é de doutrina e jurisprudência.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A ação regressiva exige dolo ou culpa do agente público.","why":"É o que diz a parte final do art. 37, § 6º.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Empresa pública exploradora de atividade econômica responde na forma do art. 37, § 6º.","why":"Ficam fora da regra as exploradoras de atividade econômica.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O Estado indeniza quem ficar preso além do tempo fixado na sentença.","why":"Art. 5º, LXXV, da Constituição.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A Constituição prevê que pessoas jurídicas de direito público respondam por danos causados a terceiros por seus agentes, nessa qualidade.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A regra constitucional do art. 37, § 6º também alcança pessoas jurídicas de direito privado prestadoras de serviços públicos.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O direito de regresso contra o agente responsável é assegurado nos casos de dolo ou culpa.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O art. 37, § 6º exige expressamente condenação criminal do agente para que a vítima seja indenizada.","why":"CF, art. 37, § 6º: não condiciona a responsabilidade à condenação criminal.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A responsabilidade prevista no art. 37, § 6º exige que o dano seja causado por agente atuando nessa qualidade.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A regra constitucional sobre responsabilidade por danos causados por agentes exclui as pessoas jurídicas de direito privado prestadoras de serviço público.","why":"CF, art. 37, § 6º: inclui expressamente essas prestadoras.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O Estado indenizará o condenado por erro judiciário, nos termos da Constituição.","why":"CF, art. 5º, LXXV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A indenização por prisão além do tempo fixado na sentença está prevista no art. 5º, LXXV.","why":"CF, art. 5º, LXXV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A Constituição exige que a ação regressiva seja proposta somente quando houver dolo, afastando a culpa.","why":"CF, art. 37, § 6º: admite dolo ou culpa.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O dever constitucional de indenizar do art. 37, § 6º refere-se a danos causados a terceiros.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A Constituição prevê responsabilidade pelos danos causados por agentes públicos nessa qualidade, mesmo sem utilizar literalmente a expressão 'responsabilidade objetiva'.","why":"CF, art. 37, § 6º; texto constitucional não usa essa expressão.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O art. 37, § 6º restringe a responsabilidade nele prevista aos órgãos da administração direta federal.","why":"CF, art. 37, § 6º: refere-se às pessoas jurídicas de direito público e prestadoras privadas de serviços públicos.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A garantia de regresso prevista na Constituição dirige-se ao agente responsável pelo dano.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A Constituição afirma que toda pessoa jurídica de direito privado, independentemente da atividade exercida, se submete ao art. 37, § 6º.","why":"CF, art. 37, § 6º: limita a referência às pessoas jurídicas privadas prestadoras de serviços públicos.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A responsabilidade constitucional por danos causados por agentes em serviço público não elimina a possibilidade de regresso contra o responsável.","why":"CF, art. 37, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A regra do art. 5º, LXXV, limita a indenização por erro judiciário às hipóteses de prisão além do tempo fixado na sentença.","why":"CF, art. 5º, LXXV: contempla tanto erro judiciário quanto prisão além do tempo fixado.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"administrativo-responsabilidade-civil-do-estado","syllabus_topic_id":"732855f7-3423-44fa-b27f-70780806b3ce"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"3d3ba8ed-fa55-5e2d-99df-90b2c8d07ab6","status":"active","content":{"cases":[{"id":"case-1","steps":["A Constituição prevê responsabilidade das pessoas jurídicas indicadas pelos danos causados por seus agentes nessa qualidade.","A responsabilidade do Estado e a ação regressiva contra o agente são análises distintas."],"title":"Dano e nexo precisam aparecer","pitfall":"Aplicar essa conclusão indistintamente a toda omissão sem examinar o regime pertinente.","articles":["Constituição, art. 37, § 6º"],"question":"É preciso provar culpa do agente para a responsabilidade estatal da hipótese?","scenario":"Um agente público, nessa qualidade, causa dano a particular em atuação comissiva. O caso informa dano e nexo causal, sem excludente.","variation":{"answer":"Sem nexo não se conclui automaticamente responsabilidade; analise os fatos e eventuais excludentes.","scenario":"E se o dano não tiver relação causal com a atuação do agente?"},"conclusion":"Na hipótese constitucional comissiva descrita, a responsabilidade estatal é objetiva; o regresso depende de dolo ou culpa."}],"illustrations":[{"kind":"flow","nodes":["Dano e nexo precisam aparecer","É preciso provar culpa do agente para a responsabilidade estatal da hipótese?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:38.938+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"administrativo-responsabilidade-civil-do-estado","source_body_sha256":"88a574849678d9a2bfc0b3933fe4d9d16bb280fc3030292e9dc8290fced6715c"}],"enrichment":{"id":"36fc136b-c923-5e27-a65e-d282b400b93a","material_slug":"administrativo-responsabilidade-civil-do-estado","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"70baebf2c0c1decb37ebbd9ce253351ec6d3a4e2b3102572ec93a5c36f7a570d","content":{"cases":[{"id":"case-1","steps":["A Constituição prevê responsabilidade das pessoas jurídicas indicadas pelos danos causados por seus agentes nessa qualidade.","A responsabilidade do Estado e a ação regressiva contra o agente são análises distintas."],"title":"Dano e nexo precisam aparecer","pitfall":"Aplicar essa conclusão indistintamente a toda omissão sem examinar o regime pertinente.","articles":["Constituição, art. 37, § 6º"],"question":"É preciso provar culpa do agente para a responsabilidade estatal da hipótese?","scenario":"Um agente público, nessa qualidade, causa dano a particular em atuação comissiva. O caso informa dano e nexo causal, sem excludente.","variation":{"answer":"Sem nexo não se conclui automaticamente responsabilidade; analise os fatos e eventuais excludentes.","scenario":"E se o dano não tiver relação causal com a atuação do agente?"},"conclusion":"Na hipótese constitucional comissiva descrita, a responsabilidade estatal é objetiva; o regresso depende de dolo ou culpa."},{"id":"complemento-20261024","title":"Regresso não exige apenas dolo","scenario":"Após indenizar terceiro, a pessoa pública identifica culpa do agente e o resumo afirma que regresso só cabe por dolo.","question":"O que diz a Constituição?","steps":["Leia o art. 37, § 6º.","Distinga a responsabilidade perante o terceiro da responsabilidade do agente.","Examine os elementos da culpa, sem presumi-la do pagamento."],"conclusion":"O direito de regresso alcança dolo ou culpa demonstrados.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"Não se comprova dolo nem culpa do agente.","answer":"A indenização estatal, por si só, não cria responsabilidade regressiva automática."},"articles":["CF, art. 37, § 6º"]}],"illustrations":[{"kind":"flow","nodes":["Dano e nexo precisam aparecer","É preciso provar culpa do agente para a responsabilidade estatal da hipótese?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto/antigos/d20910.htm","title":"Fonte oficial complementar — d20910.htm","sha256":"2d1e79de5096840bfd47b9d880b2cd4afbe49cb6636a5863b2ec19a1142f865f"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9494.htm","title":"Fonte oficial complementar — l9494.htm","sha256":"e43689a7efc0fec7da0bc9c936d867e4ba2dba263a7a741b039ba2ef84729bee"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=940","title":"STF — Tema 940"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=4645403&numeroProcesso=841526&numeroTema=592","title":"STF — Tema 592"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"f83f90a7-8944-4641-a1d0-e0189a55cbb7","quiz":[{"q":"Em risco iminente, a Administração federal pode adotar providências acauteladoras sem prévia manifestação do interessado.","a":true,"why":"Lei 9.784/1999, art. 45: hipótese de tutela cautelar; não é autorização para dispensar motivação ou contraditório em todo ato."},{"q":"Os atos do processo administrativo federal exigem sempre forma determinada, mesmo quando a lei não a impõe.","a":false,"why":"Lei 9.784/1999, art. 22: os atos não dependem de forma determinada, salvo exigência legal."},{"a":true,"q":"O direito de a Administração anular atos de que decorram efeitos favoráveis decai em cinco anos, salvo comprovada má-fé.","why":"Art. 54 da Lei 9.784/1999."},{"q":"O controle judicial permite substituir uma escolha administrativa legítima de conveniência pela preferência pessoal do juiz.","a":false,"why":"Controle jurídico alcança finalidade, motivação e princípios; não é substituição livre da conveniência legítima. CF, art. 5º, XXXV; Lei 9.784, art. 2º."},{"a":true,"q":"A Administração deve anular seus próprios atos quando eivados de vício de legalidade.","why":"Lei 9.784/1999, art. 53."},{"a":true,"q":"A Administração pode revogar atos administrativos por conveniência ou oportunidade, respeitados os direitos adquiridos.","why":"Lei 9.784/1999, art. 53."},{"a":false,"q":"A revogação prevista no art. 53 da Lei 9.784/1999 decorre necessariamente de vício de legalidade.","why":"Lei 9.784/1999, art. 53: revogação decorre de conveniência ou oportunidade."},{"a":true,"q":"A anulação de atos ilegais pela Administração está prevista expressamente na Lei 9.784/1999.","why":"Lei 9.784/1999, art. 53."},{"a":true,"q":"A Administração deve indicar os pressupostos de fato e de direito que determinarem a decisão, conforme o princípio da motivação.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VII."},{"a":true,"q":"A motivação deve ser explícita, clara e congruente nos casos previstos no art. 50.","why":"Lei 9.784/1999, art. 50, § 1º."},{"a":true,"q":"Os atos administrativos que neguem, limitem ou afetem direitos ou interesses devem ser motivados.","why":"Lei 9.784/1999, art. 50, I."},{"a":false,"q":"A motivação é dispensável para atos que imponham ou agravem deveres, encargos ou sanções.","why":"Lei 9.784/1999, art. 50, II."},{"a":true,"q":"Os atos administrativos que decidam recursos administrativos devem ser motivados.","why":"Lei 9.784/1999, art. 50, V."},{"a":true,"q":"A Administração pode convalidar atos com defeitos sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros.","why":"Lei 9.784/1999, art. 55."},{"a":false,"q":"Todo defeito do ato administrativo é insanável e impede convalidação.","why":"Lei 9.784/1999, art. 55: admite convalidação de defeitos sanáveis."},{"a":true,"q":"O prazo decadencial de cinco anos para anular atos favoráveis admite exceção em caso de comprovada má-fé.","why":"Lei 9.784/1999, art. 54."},{"a":true,"q":"Nos casos de efeitos patrimoniais contínuos, o prazo de decadência conta-se da percepção do primeiro pagamento.","why":"Lei 9.784/1999, art. 54, § 1º."},{"a":true,"q":"O exercício do direito de anular pode ser caracterizado por medida de autoridade administrativa que importe impugnação à validade do ato.","why":"Lei 9.784/1999, art. 54, § 2º."},{"a":false,"q":"A Lei 9.784/1999 autoriza a revogação de atos por conveniência e oportunidade sem respeito a direitos adquiridos.","why":"Lei 9.784/1999, art. 53: exige respeito aos direitos adquiridos."},{"a":true,"q":"A Administração deve observar a adequação entre meios e fins, vedada imposição de restrições superiores às necessárias ao interesse público.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VI."}],"slug":"administrativo-atos-administrativos-requisitos-atributos","title":"Atos administrativos: requisitos, atributos, espécies e extinção","body_md":"## Requisitos (elementos) do ato\n\n| Requisito | Ideia central |\n|---|---|\n| **Competência** | Poder legal para praticar o ato. Decorre **sempre de lei**, é **intransferível**, **imodificável pela vontade do agente**, **imprescritível** e **irrenunciável**, salvo autorização legal |\n| **Finalidade** | **Sentido amplo**: interesse público. **Sentido estrito**: o fim legal específico. O defeito é o **desvio de finalidade** (exemplo clássico: remoção como forma de punição) |\n| **Forma** | **Revestimento exteriorizador** do ato. A forma essencial, quando descumprida, **torna o ato nulo** |\n| **Motivo** | **Pressuposto de fato e de direito** que autoriza ou exige a prática do ato |\n| **Objeto** | O **efeito jurídico imediato** que o ato produz |\n\n- **Teoria dos motivos determinantes:** os fatos que serviram de suporte à decisão **integram a validade do ato**; ele só é válido se os motivos enunciados **realmente existiram**.\n- **Motivação** (art. 50 da Lei nº 9.784/1999): é a exposição dos **fatos** e dos **fundamentos jurídicos**. Pode ser **contextual** (no próprio ato) ou **aliunde** (em outro documento, como parecer ao qual se remete).\n\n### Competência: delegação e avocação (Lei nº 9.784/1999)\n\n- **Delegação** (arts. 12 a 14): possível mesmo a órgão **não subordinado**, **revogável a qualquer tempo**. **Não se delegam** atos normativos, decisão de recursos administrativos e competência exclusiva.\n- **Avocação** (art. 15): **excepcional e temporária**, por motivos relevantes justificados, de competência de órgão **hierarquicamente inferior**.\n\n### Vinculado × discricionário (doutrina)\n\nEm todo ato, competência e finalidade são legalmente delimitadas; a forma deve observar as exigências legais. A **discricionariedade** está em **motivo** e **objeto**, e forma o **mérito administrativo** (conveniência e oportunidade). O Judiciário controla **legalidade e legitimidade**; não substitui a escolha legítima de conveniência e oportunidade; controla os limites jurídicos. A própria Administração controla também o mérito.\n\n## Atributos\n\n| Atributo | Significado |\n|---|---|\n| **Presunção de legitimidade e veracidade** | O ato se presume conforme a lei (legitimidade) e os fatos alegados se presumem verdadeiros (veracidade). A presunção é **relativa** (*juris tantum*): cabe prova em contrário |\n| **Imperatividade** | Impõe-se a terceiros **independentemente de sua vontade**. **Não há** nos atos que **outorgam direitos**, como permissão e autorização |\n| **Autoexecutoriedade** | Executa-se **sem ordem judicial**, por meios diretos. Exige **previsão em lei** ou **situação de urgência** |\n| **Exigibilidade** | Impele o destinatário à obediência por **meios indiretos** (multa, por exemplo) |\n| **Tipicidade** | O ato deve corresponder a **figuras previamente definidas em lei** |\n\n## Espécies mais cobradas\n\n| Ato | Natureza | Ideia |\n|---|---|---|\n| **Licença** | **Vinculado** e **definitivo** | Direito do requerente que preenche os requisitos. Ex.: licença para construir |\n| **Autorização** | **Discricionário** e **precário** | Interesse predominante do particular; sem direito subjetivo à obtenção. Ex.: porte de arma |\n| **Permissão de uso de bem público** | **Discricionário** e **precário** | Uso privativo de bem público |\n| **Permissão de serviço público** | **Contrato administrativo** (Lei nº 8.987/1995) | Não é ato administrativo unilateral |\n| **Parecer vinculante** | **É** ato administrativo | Um parecer obrigatório pode ser vinculante ou não vinculante; o art. 42 da Lei 9.784 distingue ambos. Obrigatoriedade de solicitar não é o mesmo que vinculação ao conteúdo |\n| **Atos punitivos** | Multa, interdição, destruição de coisa (externos) e sanções disciplinares (internos) | |\n\n## Anulação, revogação e convalidação (Lei nº 9.784/1999, arts. 53 a 55)\n\n- **Anulação** (art. 53): a Administração **deve** anular os atos com **vício de legalidade**.\n- **Revogação** (art. 53): a Administração **pode** revogar por **conveniência ou oportunidade**, **respeitados os direitos adquiridos**.\n- **Decadência** (art. 54): o direito de anular atos de que decorram **efeitos favoráveis** aos destinatários **decai em 5 anos**, contados da prática do ato, **salvo comprovada má-fé**. Nos efeitos patrimoniais contínuos, conta-se do **primeiro pagamento**.\n- **Convalidação** (art. 55): atos com **defeitos sanáveis** podem ser convalidados pela própria Administração, se **não houver lesão ao interesse público nem prejuízo a terceiros**.\n- **Motivação obrigatória** (art. 50) nos atos que, entre outros, neguem ou limitem direitos, imponham sanções, decidam recursos, dispensem licitação ou **importem anulação, revogação, suspensão ou convalidação** de ato.\n\n> **Conferido no Planalto (Lei nº 9.784/1999, texto compilado):** os arts. 12 a 15, 50 e 53 a 55 foram conferidos. A classificação dos atos, as espécies e os atributos acima vêm da **classificação doutrinária** e **não são texto de lei**: ao responder a uma questão, cite-os como entendimento doutrinário.\n\n## Separar quatro perguntas sobre o mesmo ato\n\n**Motivo:** qual fato e qual fundamento jurídico justificam agir? **Motivação:** como a decisão explica esses elementos? **Objeto:** qual efeito jurídico foi produzido? **Finalidade:** para qual fim a competência foi atribuída? Um parecer técnico pode integrar a motivação por remissão expressa, conforme o art. 50, § 1º, da Lei 9.784. Referência vazia a um parecer inexistente não supre o dever de explicar.\n\nA presunção de legitimidade não é certeza absoluta e não afasta defesa nem controle. Autoexecutoriedade não deve ser ensinada como atributo operacional de todo ato: a possibilidade de executar diretamente uma medida exige hipótese jurídica própria. Uma multa e uma medida urgente de interdição não se cobram nem se executam necessariamente pelo mesmo caminho.\n\nNa anulação, examine vício, defesa, segurança jurídica e decadência; na revogação, conveniência e oportunidade de ato válido, quando cabível, respeitados direitos adquiridos. O art. 55 permite convalidar defeito sanável sem lesão ao interesse público ou prejuízo a terceiros. Logo, não conclua “qualquer vício impõe anulação imediata sem ouvir ninguém”. A base é a Lei 9.784, arts. 2º, 50 e 53 a 55, em conjunto com a CF, art. 5º, LIV e LV.\n","summary":"Competência, finalidade, forma, motivo e objeto; presunção de legitimidade e os demais atributos; licença × autorização; anulação, revogação e convalidação.","created_at":"2026-10-01T04:03:52.568808+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Competência, finalidade, forma, motivo e objeto. A margem de escolha deve estar autorizada pelo ordenamento; competência e finalidade são legalmente delimitadas, e a forma segue as exigências legais.","f":"Requisitos do ato administrativo"},{"b":"O ato só é válido se os motivos enunciados efetivamente ocorreram.","f":"Teoria dos motivos determinantes"},{"b":"Licença é vinculada e definitiva (direito do requerente). Autorização é discricionária e precária (sem direito subjetivo).","f":"Licença × autorização"},{"b":"5 anos da prática do ato, nos atos de efeito favorável, salvo má-fé. Efeitos patrimoniais contínuos: do primeiro pagamento.","f":"Decadência do direito de anular (Lei 9.784, art. 54)"},{"b":"Possível para defeitos sanáveis, se não houver lesão ao interesse público nem prejuízo a terceiros.","f":"Convalidação (art. 55)"}],"sort_order":80,"updated_at":"2026-10-24T19:57:05.00342+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Lei nº 9.784/1999 (Processo Administrativo Federal), texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto da Lei nº 9.784/1999 e da Constituição no Planalto. Os pontos de doutrina estão indicados como tal. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Atos administrativos","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","corrections":["Corrigida a afirmação de que todo parecer obrigatório é não vinculante; diferenciadas as hipóteses do art. 42 da Lei 9.784.","Distinguidas classificações doutrinárias de texto legal e acrescentados limites relevantes no complemento."],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"administrativo-atos-administrativos-requisitos-atributos","subject":"Direito Administrativo","topic_label":"Atos administrativos","syllabus_topic_id":"9fc4243b-fe0f-461b-b705-57873fb33563","checked_at":"2026-10-24T22:30:24.912384+00:00","scope":"Vinte exercícios conferidos no recorte das fontes oficiais, com metadados completos e correção de generalizações.","sources":[{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"items":[{"q":"Em risco iminente, a Administração federal pode adotar providências acauteladoras sem prévia manifestação do interessado.","a":true,"why":"Lei 9.784/1999, art. 45: hipótese de tutela cautelar; não é autorização para dispensar motivação ou contraditório em todo ato.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 45: hipótese de tutela cautelar; não é autorização para dispensar motivação ou contraditório em todo ato.","origin":"clarified_current_official_text"},{"q":"Os atos do processo administrativo federal exigem sempre forma determinada, mesmo quando a lei não a impõe.","a":false,"why":"Lei 9.784/1999, art. 22: os atos não dependem de forma determinada, salvo exigência legal.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 22: os atos não dependem de forma determinada, salvo exigência legal.","origin":"clarified_current_official_text"},{"a":true,"q":"O direito de a Administração anular atos de que decorram efeitos favoráveis decai em cinco anos, salvo comprovada má-fé.","why":"Art. 54 da Lei 9.784/1999.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Art. 54 da Lei 9.784/1999.","origin":"retained_and_rechecked"},{"q":"O controle judicial permite substituir uma escolha administrativa legítima de conveniência pela preferência pessoal do juiz.","a":false,"why":"Controle jurídico alcança finalidade, motivação e princípios; não é substituição livre da conveniência legítima. CF, art. 5º, XXXV; Lei 9.784, art. 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Controle jurídico alcança finalidade, motivação e princípios; não é substituição livre da conveniência legítima. CF, art. 5º, XXXV; Lei 9.784, art. 2º.","origin":"clarified_current_official_text"},{"a":true,"q":"A Administração deve anular seus próprios atos quando eivados de vício de legalidade.","why":"Lei 9.784/1999, art. 53.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 53.","origin":"retained_and_rechecked"},{"a":true,"q":"A Administração pode revogar atos administrativos por conveniência ou oportunidade, respeitados os direitos adquiridos.","why":"Lei 9.784/1999, art. 53.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 53.","origin":"retained_and_rechecked"},{"a":false,"q":"A revogação prevista no art. 53 da Lei 9.784/1999 decorre necessariamente de vício de legalidade.","why":"Lei 9.784/1999, art. 53: revogação decorre de conveniência ou oportunidade.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 53: revogação decorre de conveniência ou oportunidade.","origin":"retained_and_rechecked"},{"a":true,"q":"A anulação de atos ilegais pela Administração está prevista expressamente na Lei 9.784/1999.","why":"Lei 9.784/1999, art. 53.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 53.","origin":"retained_and_rechecked"},{"a":true,"q":"A Administração deve indicar os pressupostos de fato e de direito que determinarem a decisão, conforme o princípio da motivação.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VII.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 2º, parágrafo único, VII.","origin":"retained_and_rechecked"},{"a":true,"q":"A motivação deve ser explícita, clara e congruente nos casos previstos no art. 50.","why":"Lei 9.784/1999, art. 50, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 50, § 1º.","origin":"retained_and_rechecked"},{"a":true,"q":"Os atos administrativos que neguem, limitem ou afetem direitos ou interesses devem ser motivados.","why":"Lei 9.784/1999, art. 50, I.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 50, I.","origin":"retained_and_rechecked"},{"a":false,"q":"A motivação é dispensável para atos que imponham ou agravem deveres, encargos ou sanções.","why":"Lei 9.784/1999, art. 50, II.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 50, II.","origin":"retained_and_rechecked"},{"a":true,"q":"Os atos administrativos que decidam recursos administrativos devem ser motivados.","why":"Lei 9.784/1999, art. 50, V.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 50, V.","origin":"retained_and_rechecked"},{"a":true,"q":"A Administração pode convalidar atos com defeitos sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros.","why":"Lei 9.784/1999, art. 55.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 55.","origin":"retained_and_rechecked"},{"a":false,"q":"Todo defeito do ato administrativo é insanável e impede convalidação.","why":"Lei 9.784/1999, art. 55: admite convalidação de defeitos sanáveis.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 55: admite convalidação de defeitos sanáveis.","origin":"retained_and_rechecked"},{"a":true,"q":"O prazo decadencial de cinco anos para anular atos favoráveis admite exceção em caso de comprovada má-fé.","why":"Lei 9.784/1999, art. 54.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 54.","origin":"retained_and_rechecked"},{"a":true,"q":"Nos casos de efeitos patrimoniais contínuos, o prazo de decadência conta-se da percepção do primeiro pagamento.","why":"Lei 9.784/1999, art. 54, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 54, § 1º.","origin":"retained_and_rechecked"},{"a":true,"q":"O exercício do direito de anular pode ser caracterizado por medida de autoridade administrativa que importe impugnação à validade do ato.","why":"Lei 9.784/1999, art. 54, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 54, § 2º.","origin":"retained_and_rechecked"},{"a":false,"q":"A Lei 9.784/1999 autoriza a revogação de atos por conveniência e oportunidade sem respeito a direitos adquiridos.","why":"Lei 9.784/1999, art. 53: exige respeito aos direitos adquiridos.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 53: exige respeito aos direitos adquiridos.","origin":"retained_and_rechecked"},{"a":true,"q":"A Administração deve observar a adequação entre meios e fins, vedada imposição de restrições superiores às necessárias ao interesse público.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","article":"Lei 9.784/1999, art. 2º, parágrafo único, VI.","origin":"retained_and_rechecked"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_material":{"id":"f83f90a7-8944-4641-a1d0-e0189a55cbb7","quiz":[{"a":false,"q":"A autoexecutoriedade do ato administrativo exige, em regra, ordem judicial prévia.","why":"Executa-se sem ordem judicial, mediante previsão em lei ou urgência."},{"a":false,"q":"A licença é ato discricionário e precário.","why":"A licença é vinculada e definitiva; discricionária e precária é a autorização."},{"a":true,"q":"O direito de a Administração anular atos de que decorram efeitos favoráveis decai em cinco anos, salvo comprovada má-fé.","why":"Art. 54 da Lei 9.784/1999."},{"a":false,"q":"O Poder Judiciário pode controlar o mérito do ato administrativo discricionário.","why":"O Judiciário não revoga ato de outro Poder por mera conveniência e oportunidade. O controle de legalidade pode alcançar motivo, finalidade, proporcionalidade e outras exigências jurídicas."},{"a":true,"q":"A Administração deve anular seus próprios atos quando eivados de vício de legalidade.","why":"Lei 9.784/1999, art. 53."},{"a":true,"q":"A Administração pode revogar atos administrativos por conveniência ou oportunidade, respeitados os direitos adquiridos.","why":"Lei 9.784/1999, art. 53."},{"a":false,"q":"A revogação prevista no art. 53 da Lei 9.784/1999 decorre necessariamente de vício de legalidade.","why":"Lei 9.784/1999, art. 53: revogação decorre de conveniência ou oportunidade."},{"a":true,"q":"A anulação de atos ilegais pela Administração está prevista expressamente na Lei 9.784/1999.","why":"Lei 9.784/1999, art. 53."},{"a":true,"q":"A Administração deve indicar os pressupostos de fato e de direito que determinarem a decisão, conforme o princípio da motivação.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VII."},{"a":true,"q":"A motivação deve ser explícita, clara e congruente nos casos previstos no art. 50.","why":"Lei 9.784/1999, art. 50, § 1º."},{"a":true,"q":"Os atos administrativos que neguem, limitem ou afetem direitos ou interesses devem ser motivados.","why":"Lei 9.784/1999, art. 50, I."},{"a":false,"q":"A motivação é dispensável para atos que imponham ou agravem deveres, encargos ou sanções.","why":"Lei 9.784/1999, art. 50, II."},{"a":true,"q":"Os atos administrativos que decidam recursos administrativos devem ser motivados.","why":"Lei 9.784/1999, art. 50, V."},{"a":true,"q":"A Administração pode convalidar atos com defeitos sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros.","why":"Lei 9.784/1999, art. 55."},{"a":false,"q":"Todo defeito do ato administrativo é insanável e impede convalidação.","why":"Lei 9.784/1999, art. 55: admite convalidação de defeitos sanáveis."},{"a":true,"q":"O prazo decadencial de cinco anos para anular atos favoráveis admite exceção em caso de comprovada má-fé.","why":"Lei 9.784/1999, art. 54."},{"a":true,"q":"Nos casos de efeitos patrimoniais contínuos, o prazo de decadência conta-se da percepção do primeiro pagamento.","why":"Lei 9.784/1999, art. 54, § 1º."},{"a":true,"q":"O exercício do direito de anular pode ser caracterizado por medida de autoridade administrativa que importe impugnação à validade do ato.","why":"Lei 9.784/1999, art. 54, § 2º."},{"a":false,"q":"A Lei 9.784/1999 autoriza a revogação de atos por conveniência e oportunidade sem respeito a direitos adquiridos.","why":"Lei 9.784/1999, art. 53: exige respeito aos direitos adquiridos."},{"a":true,"q":"A Administração deve observar a adequação entre meios e fins, vedada imposição de restrições superiores às necessárias ao interesse público.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VI."}],"slug":"administrativo-atos-administrativos-requisitos-atributos","title":"Atos administrativos: requisitos, atributos, espécies e extinção","body_md":"## Requisitos (elementos) do ato\n\n| Requisito | Ideia central |\n|---|---|\n| **Competência** | Poder legal para praticar o ato. Decorre **sempre de lei**, é **intransferível**, **imodificável pela vontade do agente**, **imprescritível** e **irrenunciável**, salvo autorização legal |\n| **Finalidade** | **Sentido amplo**: interesse público. **Sentido estrito**: o fim legal específico. O defeito é o **desvio de finalidade** (exemplo clássico: remoção como forma de punição) |\n| **Forma** | **Revestimento exteriorizador** do ato. A forma essencial, quando descumprida, **torna o ato nulo** |\n| **Motivo** | **Pressuposto de fato e de direito** que autoriza ou exige a prática do ato |\n| **Objeto** | O **efeito jurídico imediato** que o ato produz |\n\n- **Teoria dos motivos determinantes:** os fatos que serviram de suporte à decisão **integram a validade do ato**; ele só é válido se os motivos enunciados **realmente existiram**.\n- **Motivação** (art. 50 da Lei nº 9.784/1999): é a exposição dos **fatos** e dos **fundamentos jurídicos**. Pode ser **contextual** (no próprio ato) ou **aliunde** (em outro documento, como parecer ao qual se remete).\n\n### Competência: delegação e avocação (Lei nº 9.784/1999)\n\n- **Delegação** (arts. 12 a 14): possível mesmo a órgão **não subordinado**, **revogável a qualquer tempo**. **Não se delegam** atos normativos, decisão de recursos administrativos e competência exclusiva.\n- **Avocação** (art. 15): **excepcional e temporária**, por motivos relevantes justificados, de competência de órgão **hierarquicamente inferior**.\n\n### Vinculado × discricionário (doutrina)\n\nEm todo ato, competência e finalidade são legalmente delimitadas; a forma deve observar as exigências legais. A **discricionariedade** está em **motivo** e **objeto**, e forma o **mérito administrativo** (conveniência e oportunidade). O Judiciário controla **legalidade e legitimidade**; não substitui a escolha legítima de conveniência e oportunidade; controla os limites jurídicos. A própria Administração controla também o mérito.\n\n## Atributos\n\n| Atributo | Significado |\n|---|---|\n| **Presunção de legitimidade e veracidade** | O ato se presume conforme a lei (legitimidade) e os fatos alegados se presumem verdadeiros (veracidade). A presunção é **relativa** (*juris tantum*): cabe prova em contrário |\n| **Imperatividade** | Impõe-se a terceiros **independentemente de sua vontade**. **Não há** nos atos que **outorgam direitos**, como permissão e autorização |\n| **Autoexecutoriedade** | Executa-se **sem ordem judicial**, por meios diretos. Exige **previsão em lei** ou **situação de urgência** |\n| **Exigibilidade** | Impele o destinatário à obediência por **meios indiretos** (multa, por exemplo) |\n| **Tipicidade** | O ato deve corresponder a **figuras previamente definidas em lei** |\n\n## Espécies mais cobradas\n\n| Ato | Natureza | Ideia |\n|---|---|---|\n| **Licença** | **Vinculado** e **definitivo** | Direito do requerente que preenche os requisitos. Ex.: licença para construir |\n| **Autorização** | **Discricionário** e **precário** | Interesse predominante do particular; sem direito subjetivo à obtenção. Ex.: porte de arma |\n| **Permissão de uso de bem público** | **Discricionário** e **precário** | Uso privativo de bem público |\n| **Permissão de serviço público** | **Contrato administrativo** (Lei nº 8.987/1995) | Não é ato administrativo unilateral |\n| **Parecer vinculante** | **É** ato administrativo | Um parecer obrigatório pode ser vinculante ou não vinculante; o art. 42 da Lei 9.784 distingue ambos. Obrigatoriedade de solicitar não é o mesmo que vinculação ao conteúdo |\n| **Atos punitivos** | Multa, interdição, destruição de coisa (externos) e sanções disciplinares (internos) | |\n\n## Anulação, revogação e convalidação (Lei nº 9.784/1999, arts. 53 a 55)\n\n- **Anulação** (art. 53): a Administração **deve** anular os atos com **vício de legalidade**.\n- **Revogação** (art. 53): a Administração **pode** revogar por **conveniência ou oportunidade**, **respeitados os direitos adquiridos**.\n- **Decadência** (art. 54): o direito de anular atos de que decorram **efeitos favoráveis** aos destinatários **decai em 5 anos**, contados da prática do ato, **salvo comprovada má-fé**. Nos efeitos patrimoniais contínuos, conta-se do **primeiro pagamento**.\n- **Convalidação** (art. 55): atos com **defeitos sanáveis** podem ser convalidados pela própria Administração, se **não houver lesão ao interesse público nem prejuízo a terceiros**.\n- **Motivação obrigatória** (art. 50) nos atos que, entre outros, neguem ou limitem direitos, imponham sanções, decidam recursos, dispensem licitação ou **importem anulação, revogação, suspensão ou convalidação** de ato.\n\n> **Conferido no Planalto (Lei nº 9.784/1999, texto compilado):** os arts. 12 a 15, 50 e 53 a 55 foram conferidos. A classificação dos atos, as espécies e os atributos acima vêm do **resumo de doutrina** (Strauss e Leite) e **não são texto de lei**: ao responder a uma questão, cite-os como entendimento doutrinário.","summary":"Competência, finalidade, forma, motivo e objeto; presunção de legitimidade e os demais atributos; licença × autorização; anulação, revogação e convalidação.","created_at":"2026-10-01T04:03:52.568808+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Competência, finalidade, forma, motivo e objeto. A margem de escolha deve estar autorizada pelo ordenamento; competência e finalidade são legalmente delimitadas, e a forma segue as exigências legais.","f":"Requisitos do ato administrativo"},{"b":"O ato só é válido se os motivos enunciados efetivamente ocorreram.","f":"Teoria dos motivos determinantes"},{"b":"Licença é vinculada e definitiva (direito do requerente). Autorização é discricionária e precária (sem direito subjetivo).","f":"Licença × autorização"},{"b":"5 anos da prática do ato, nos atos de efeito favorável, salvo má-fé. Efeitos patrimoniais contínuos: do primeiro pagamento.","f":"Decadência do direito de anular (Lei 9.784, art. 54)"},{"b":"Possível para defeitos sanáveis, se não houver lesão ao interesse público nem prejuízo a terceiros.","f":"Convalidação (art. 55)"}],"sort_order":80,"updated_at":"2026-10-24T19:57:05.00342+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Lei nº 9.784/1999 (Processo Administrativo Federal), texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto da Lei nº 9.784/1999 e da Constituição no Planalto. Os pontos de doutrina estão indicados como tal. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Atos administrativos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Lei nº 9.784/1999 (Processo Administrativo Federal), texto compilado","sha256":"11615a237814ce8b668a863391240f56e3ab2f00fcd86f1b442aa8fd2d5b29c3"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigida a afirmação de que todo parecer obrigatório é não vinculante; diferenciadas as hipóteses do art. 42 da Lei 9.784."],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":false,"q":"A autoexecutoriedade do ato administrativo exige, em regra, ordem judicial prévia.","why":"Executa-se sem ordem judicial, mediante previsão em lei ou urgência.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"A licença é ato discricionário e precário.","why":"A licença é vinculada e definitiva; discricionária e precária é a autorização.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"O direito de a Administração anular atos de que decorram efeitos favoráveis decai em cinco anos, salvo comprovada má-fé.","why":"Art. 54 da Lei 9.784/1999.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"O Poder Judiciário pode controlar o mérito do ato administrativo discricionário.","why":"O Judiciário não revoga ato de outro Poder por mera conveniência e oportunidade. O controle de legalidade pode alcançar motivo, finalidade, proporcionalidade e outras exigências jurídicas.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A Administração deve anular seus próprios atos quando eivados de vício de legalidade.","why":"Lei 9.784/1999, art. 53.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A Administração pode revogar atos administrativos por conveniência ou oportunidade, respeitados os direitos adquiridos.","why":"Lei 9.784/1999, art. 53.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"A revogação prevista no art. 53 da Lei 9.784/1999 decorre necessariamente de vício de legalidade.","why":"Lei 9.784/1999, art. 53: revogação decorre de conveniência ou oportunidade.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A anulação de atos ilegais pela Administração está prevista expressamente na Lei 9.784/1999.","why":"Lei 9.784/1999, art. 53.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A Administração deve indicar os pressupostos de fato e de direito que determinarem a decisão, conforme o princípio da motivação.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VII.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A motivação deve ser explícita, clara e congruente nos casos previstos no art. 50.","why":"Lei 9.784/1999, art. 50, § 1º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"Os atos administrativos que neguem, limitem ou afetem direitos ou interesses devem ser motivados.","why":"Lei 9.784/1999, art. 50, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"A motivação é dispensável para atos que imponham ou agravem deveres, encargos ou sanções.","why":"Lei 9.784/1999, art. 50, II.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"Os atos administrativos que decidam recursos administrativos devem ser motivados.","why":"Lei 9.784/1999, art. 50, V.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A Administração pode convalidar atos com defeitos sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros.","why":"Lei 9.784/1999, art. 55.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"Todo defeito do ato administrativo é insanável e impede convalidação.","why":"Lei 9.784/1999, art. 55: admite convalidação de defeitos sanáveis.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"O prazo decadencial de cinco anos para anular atos favoráveis admite exceção em caso de comprovada má-fé.","why":"Lei 9.784/1999, art. 54.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"Nos casos de efeitos patrimoniais contínuos, o prazo de decadência conta-se da percepção do primeiro pagamento.","why":"Lei 9.784/1999, art. 54, § 1º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"O exercício do direito de anular pode ser caracterizado por medida de autoridade administrativa que importe impugnação à validade do ato.","why":"Lei 9.784/1999, art. 54, § 2º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":false,"q":"A Lei 9.784/1999 autoriza a revogação de atos por conveniência e oportunidade sem respeito a direitos adquiridos.","why":"Lei 9.784/1999, art. 53: exige respeito aos direitos adquiridos.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"},{"a":true,"q":"A Administração deve observar a adequação entre meios e fins, vedada imposição de restrições superiores às necessárias ao interesse público.","why":"Lei 9.784/1999, art. 2º, parágrafo único, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],"subject":"Direito Administrativo","version":1,"material_slug":"administrativo-atos-administrativos-requisitos-atributos","syllabus_topic_id":"9bdd0632-9ac7-4197-b18b-cf2e45191320"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"96423ac1-31de-5c90-b01b-a6095d97f980","status":"active","content":{"cases":[{"id":"case-1","steps":["Diferencie a explicação formal do fato que a sustenta.","Quando o ato se apoia nesse motivo, sua falsidade compromete a fundamentação; motivação não é apenas escrever uma frase."],"title":"Motivo declarado precisa existir","pitfall":"Achar que um requisito válido torna todo o ato válido.","articles":["Lei 9.784/1999, arts. 2º e 50"],"question":"A declaração do motivo impede controle do ato?","scenario":"Um ato informa que um servidor faltou dez dias sem justificativa. Os registros mostram presença em todos eles.","variation":{"answer":"Competência não corrige um motivo inexistente nem dispensa finalidade e os demais requisitos.","scenario":"E se a autoridade tinha competência para decidir?"},"conclusion":"O dado factual precisa ser verdadeiro e juridicamente pertinente para sustentar a decisão."}],"illustrations":[{"kind":"flow","nodes":["Motivo declarado precisa existir","A declaração do motivo impede controle do ato?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Lei nº 9.784/1999 (Processo Administrativo Federal), texto compilado","sha256":"43ec9ab8fb3a4f02b797f4bc678a51fe9b76d8c6a011c5046cd868cccec60995","checked_at":"2026-10-05T04:33:26.355879+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:39.843+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"administrativo-atos-administrativos-requisitos-atributos","source_body_sha256":"2b7b579ac4745463328f38c580ad16112f57f0573fd9462710af7fbe9ac27042"}],"enrichment":{"id":"11873841-1c97-5dac-ae6a-2cb41384703c","material_slug":"administrativo-atos-administrativos-requisitos-atributos","version":"2026-10-24-administrativo-complemento-v1","source_body_sha256":"9eaf5f0e1286ea56e7007def71e252482d83806eb9fce9be87be2fe7816ef263","content":{"cases":[{"id":"case-1","steps":["Diferencie a explicação formal do fato que a sustenta.","Quando o ato se apoia nesse motivo, sua falsidade compromete a fundamentação; motivação não é apenas escrever uma frase."],"title":"Motivo declarado precisa existir","pitfall":"Achar que um requisito válido torna todo o ato válido.","articles":["Lei 9.784/1999, arts. 2º e 50"],"question":"A declaração do motivo impede controle do ato?","scenario":"Um ato informa que um servidor faltou dez dias sem justificativa. Os registros mostram presença em todos eles.","variation":{"answer":"Competência não corrige um motivo inexistente nem dispensa finalidade e os demais requisitos.","scenario":"E se a autoridade tinha competência para decidir?"},"conclusion":"O dado factual precisa ser verdadeiro e juridicamente pertinente para sustentar a decisão."},{"id":"complemento-20261024","title":"Defeito sanável não é anulação automática","scenario":"A Administração identifica defeito sanável e pretende retirar o ato sem considerar qualquer alternativa.","question":"Qual exame legal falta?","steps":["Qualifique o defeito.","Examine lesão ao interesse público e prejuízo a terceiros.","Leia o art. 55 e as garantias procedimentais."],"conclusion":"A convalidação é possibilidade legal quando satisfeitos seus requisitos.","pitfall":"Aplicar rótulo ou regra de outra hipótese antes de identificar o regime e os fatos relevantes.","variation":{"scenario":"O defeito é insanável.","answer":"Não se aplica a solução do art. 55; examine a anulação e seus limites."},"articles":["Lei 9.784/1999, arts. 53 a 55"]}],"illustrations":[{"kind":"flow","nodes":["Motivo declarado precisa existir","A declaração do motivo impede controle do ato?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."},{"kind":"flow","title":"Sequência de análise","caption":"Identifique o instituto antes de aplicar a consequência.","nodes":["Qual é o regime?","Quem atua?","Qual regra e quais limites?","Conclusão fundamentada"]}]},"sources":[{"key":"l9784","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","bytes":74941,"sha256":"27f45c85b6b29171a563428cafd5271afe456eabfc334757342dd89c4ba5f6e8","checked_at":"2026-10-24T22:17:16.726165+00:00","title":"Lei 9.784/1999 — processo administrativo federal"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"},{"key":"cf","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","bytes":1507134,"sha256":"c2e86781dbdc3353a946039f68e25b68918c18199c186d426e3028f8a180290c","checked_at":"2026-10-24T22:17:27.783560+00:00","title":"Constituição Federal — texto compilado"}],"checked_at":"2026-10-24T22:30:24.912384+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T22:30:24.912384+00:00"}},{"kind":"update","material":{"id":"48407590-049a-465e-9d6d-5a4348dc2417","quiz":[{"a":true,"q":"O recurso administrativo tramita, em regra, por no máximo três instâncias.","why":"Art. 57 da Lei 9.784/1999."},{"a":false,"q":"A Lei 9.784/1999 se aplica a processos administrativos específicos, como o PAD, com prevalência sobre a lei própria.","why":"Aplica-se apenas subsidiariamente aos processos regidos por lei própria (art. 69)."},{"a":true,"q":"A Lei 14.210/2021 introduziu a decisão coordenada na Lei 9.784/1999.","why":"Arts. 49-A a 49-G."},{"a":true,"q":"A omissão do dever de comunicar o próprio impedimento é falta grave para efeitos disciplinares.","why":"Art. 19, parágrafo único."},{"a":true,"q":"A Lei 9.784/1999 rege o processo administrativo federal?","why":"Art. 1º: normas básicas da Administração Pública Federal."},{"a":false,"q":"A lei nunca se aplica ao Legislativo e Judiciário da União?","why":"Art. 1º, §1º: aplica-se quando exercem função administrativa."},{"a":true,"q":"Legalidade, finalidade, motivação e eficiência são princípios do processo?","why":"Art. 2º, caput, da Lei 9.784/1999."},{"a":false,"q":"O advogado é sempre obrigatório no processo administrativo?","why":"Art. 3º, IV: assistência facultativa, salvo exigência legal."},{"a":true,"q":"O processo pode começar de ofício?","why":"Art. 5º: de ofício ou a pedido de interessado."},{"a":false,"q":"É permitida recusa imotivada de documentos?","why":"Art. 6º, parágrafo único, veda recusa imotivada."},{"a":true,"q":"A capacidade processual administrativa começa, em regra, aos 18 anos?","why":"Art. 10, ressalvada previsão especial."},{"a":false,"q":"A competência administrativa é livremente renunciável?","why":"Art. 11: competência irrenunciável, ressalvadas delegação e avocação."},{"a":false,"q":"A edição de atos normativos pode ser delegada?","why":"Art. 13, I: matéria indelegável."},{"a":true,"q":"A decisão de recursos administrativos é indelegável?","why":"Art. 13, II."},{"a":true,"q":"A avocação excepcional exige motivos relevantes justificados?","why":"Art. 15: avocação temporária e excepcional."},{"a":true,"q":"Interesse direto do servidor na matéria gera impedimento?","why":"Art. 18, I."},{"a":true,"q":"Amizade íntima com interessado pode fundamentar suspeição?","why":"Art. 20."},{"a":false,"q":"Todo ato processual exige forma determinada mesmo sem lei?","why":"Art. 22: forma determinada apenas quando exigida em lei."},{"a":true,"q":"O prazo geral para recurso administrativo é de dez dias?","why":"Art. 59, salvo disposição legal específica."},{"a":true,"q":"A Administração deve anular atos ilegais?","why":"Art. 53: anulação por ilegalidade; revogação por conveniência ou oportunidade."}],"slug":"administrativo-processo-administrativo-lei-9784","title":"Processo administrativo federal (Lei nº 9.784/1999)","body_md":"## Âmbito (art. 1º e art. 69)\n\nRegula o **processo administrativo na Administração Federal**, direta e indireta, e os **órgãos dos Poderes Legislativo e Judiciário da União** quando no desempenho de **função administrativa**. Os processos **específicos** (como o PAD da Lei nº 8.112/1990) regem-se por **lei própria**, e a Lei nº 9.784/1999 se aplica a eles **apenas subsidiariamente**.\n\n## Princípios (art. 2º)\n\nLegalidade, finalidade, **motivação**, razoabilidade, proporcionalidade, moralidade, **ampla defesa**, **contraditório**, segurança jurídica, interesse público e eficiência. Entre os critérios do parágrafo único: **proibição de cobrança de despesas processuais**, **impulsão de ofício** e **vedação de aplicação retroativa de nova interpretação** da norma administrativa.\n\n## Início e interessados (arts. 5º a 10)\n\n- O processo pode iniciar-se **de ofício** ou **a pedido** do interessado (art. 5º).\n- O requerimento inicial é **por escrito**, salvo solicitação oral admitida (art. 6º). É **vedada a recusa imotivada** de recebimento de documentos (art. 6º, parágrafo único).\n- **Legitimados** (art. 9º): quem inicia o processo, quem tem direitos ou interesses **afetados pela decisão**, **organizações e associações** (interesses coletivos) e pessoas ou associações quanto a **interesses difusos**.\n- **Capacidade** (art. 10): **maiores de 18 anos**, salvo previsão especial.\n\n## Impedimento e suspeição (arts. 18 a 21)\n\n| | **Impedimento** (art. 18) | **Suspeição** (art. 20) |\n|---|---|---|\n| **Causas** | Interesse direto ou indireto; participação como **perito, testemunha ou representante**; **litígio** com o interessado ou cônjuge | **Amizade íntima** ou **inimizade notória** com interessado, cônjuge, companheiro ou parentes até o 3º grau |\n| **Consequência** | O impedido deve **comunicar** e se abster. A **omissão** do dever de comunicar é **falta grave** (art. 19) | A suspeição **pode ser arguida** |\n\nO indeferimento da alegação de suspeição cabe **recurso, sem efeito suspensivo** (art. 21).\n\n## Forma, prazos e intimação (arts. 22 a 28)\n\n- **Informalismo:** os atos não dependem de forma determinada, salvo quando a lei exigir (art. 22). Realizam-se em **dias úteis**, no horário de funcionamento (art. 23).\n- **Prazo geral** dos atos: **5 dias**, **prorrogáveis até o dobro**, mediante justificação (art. 24).\n- **Intimação** (art. 26): com antecedência mínima de **3 dias úteis**; por ciência no processo, **via postal com AR**, telegrama ou outro meio que assegure a ciência; para interessados indeterminados, **publicação oficial**. É **nula** a intimação irregular, mas o **comparecimento** do administrado **supre** a falta (§ 5º).\n- O **desatendimento** da intimação **não importa reconhecimento da verdade dos fatos** nem renúncia a direito (art. 27).\n\n## Instrução (arts. 29 a 47)\n\n- É **inadmissível** a prova **obtida por meio ilícito** (art. 30).\n- **Consulta pública** (art. 31) e **audiência pública** (art. 32) em matérias de interesse geral.\n- **Ônus da prova** do interessado quanto aos fatos que alegou (art. 36), mas a Administração obtém **de ofício** documentos que estejam em seus arquivos (art. 37).\n- **Provas recusáveis** (art. 38, § 2º), por decisão fundamentada: **ilícitas, impertinentes, desnecessárias ou protelatórias**.\n- **Parecer obrigatório**: prazo máximo de **15 dias** (art. 42). Se for **vinculante** e não emitido, o processo **não segue**; se **não vinculante**, pode ser decidido sem ele.\n- Encerrada a instrução, o interessado tem **10 dias** para se manifestar (art. 44). Em **risco iminente**, a Administração pode adotar **providências acauteladoras** sem ouvir o interessado (art. 45).\n\n## Decisão (arts. 48 e 49)\n\nA Administração tem o **dever de decidir** explicitamente. Concluída a instrução, o prazo é de **até 30 dias**, **prorrogável por igual período**, motivadamente.\n\n## Recursos (arts. 56 a 65)\n\n| Ponto | Regra |\n|---|---|\n| **Cabimento** | Cabe recurso **por razões de legalidade e de mérito** |\n| **Reconsideração** | O recurso vai à autoridade que decidiu, que pode **reconsiderar em 5 dias**; se não, o **encaminha à superior** |\n| **Caução** | **Independe de caução**, salvo exigência legal |\n| **Instâncias** | **No máximo 3** instâncias administrativas |\n| **Prazo para recorrer** | **10 dias** da ciência ou divulgação oficial |\n| **Prazo para decidir** | **30 dias**, prorrogáveis por igual período |\n| **Efeito** | **Em regra sem efeito suspensivo**; pode ser concedido em caso de justo receio de prejuízo de difícil reparação |\n| **Não conhecimento** | Fora do prazo, órgão incompetente, ilegitimidade ou esfera administrativa exaurida. **Não impede** a revisão de ofício do ato ilegal |\n| **Reformatio in pejus** | Se a decisão puder **agravar** a situação do recorrente, ele deve ser **cientificado** para se manifestar (art. 64, parágrafo único) |\n| **Revisão** | Processos com **sanção** podem ser revistos **a qualquer tempo**, com fatos novos, e **sem agravamento** da sanção (art. 65) |\n\n## Prazos (arts. 66 e 67)\n\nContam-se **excluindo o dia do começo e incluindo o do vencimento**. Prazos em dias são **contínuos**. Em regra os prazos processuais **não se suspendem**, salvo força maior comprovada.\n\n## Prioridade (art. 69-A)\n\nTêm prioridade os processos em que figure pessoa com **60 anos ou mais**, **pessoa com deficiência** e pessoa com **doença grave** listada na lei.\n\n> **Atualização legislativa (conferida no Planalto):** a **Lei nº 14.210/2021** incluiu na Lei nº 9.784/1999 a **decisão coordenada** (arts. 49-A a 49-G), para decisões que exijam a participação de **3 ou mais setores, órgãos ou entidades**, quando for justificável pela relevância da matéria e houver discordância que prejudique a celeridade. **Não se aplica** a processos de **licitação**, ao **poder sancionador** ou com autoridades de **Poderes distintos** (art. 49-A, § 6º). A decisão coordenada **não exclui a responsabilidade originária** de cada órgão. Resumos anteriores a 2021 **não trazem** esse instituto.\n\n## Leitura atual da lei: não confunda o resumo antigo com o texto vigente\n\nUma apostila anterior a 2021 pode ser útil para artigos que não mudaram, mas é insuficiente para decisão coordenada. O art. 49-A, incluído pela Lei 14.210/2021, exige participação de três ou mais setores, órgãos ou entidades, relevância justificadora e discordância que prejudique a celeridade. A decisão não dilui a responsabilidade originária de cada participante e não se aplica às exclusões do § 6º.\n\nUse um quadro de prazos sem misturar regimes: o prazo geral do art. 24 é de cinco dias, prorrogável até o dobro mediante justificação; o prazo para decidir após a instrução, art. 49, é de trinta dias, prorrogável por igual período de forma expressamente motivada; o prazo recursal do art. 59 é de dez dias, salvo disposição legal específica. O art. 66 estabelece contagem contínua dos prazos em dias e prorrogação quando o vencimento cair sem expediente. **Não importe automaticamente a contagem em dias úteis do CPC.**\n\nNo recurso comum, a decisão pode agravar a situação do recorrente, mas é necessário cientificá-lo para alegações antes da decisão (art. 64, parágrafo único). Na revisão de processo sancionador, fundada em fatos novos ou circunstâncias relevantes, é vedado agravar a sanção (art. 65). Essa diferença resolve itens aparentemente contraditórios.\n\nA prioridade do art. 69-A não depende apenas da idade: deficiência e doença grave legalmente enquadrada também devem ser verificadas. A pessoa interessada deve requerer o benefício e comprovar a condição. Não substitua a avaliação da hipótese por uma idade ou doença inventada no resumo.\n\nO texto integral atualizado deve ser lido no [Planalto](https://www.planalto.gov.br/ccivil_03/leis/l9784.htm). Para aplicação de Lei 8.112 ou outro rito específico, considere a subsidiariedade do art. 69. O caderno antigo de exercícios não certifica a origem oficial da prova nem a atualidade do gabarito: os itens catalogados recebem identificação didática própria.\n","summary":"Âmbito, princípios, início, interessados, impedimento e suspeição, intimação, instrução, decisão, recursos e a decisão coordenada.","created_at":"2026-10-01T04:03:52.568808+00:00","discipline":"Direito Administrativo","flashcards":[{"b":"Administração Federal direta e indireta, e órgãos do Legislativo e do Judiciário da União em função administrativa. Para processos específicos (como o PAD), aplica-se só subsidiariamente.","f":"Âmbito de aplicação da Lei 9.784/1999"},{"b":"10 dias da ciência ou divulgação oficial da decisão; decisão em até 30 dias, prorrogáveis por igual período.","f":"Prazo do recurso administrativo (Lei 9.784)"},{"b":"Em regra, sem efeito suspensivo; pode ser concedido se houver justo receio de prejuízo de difícil ou incerta reparação.","f":"Efeito do recurso administrativo"},{"b":"Para decisões que exijam participação de 3 ou mais setores, órgãos ou entidades, quando justificável e houver discordância que prejudique a celeridade; não vale para licitação nem poder sancionador.","f":"Decisão coordenada (Lei 14.210/2021)"},{"b":"É inadmissível no processo administrativo (art. 30).","f":"Prova obtida por meio ilícito"}],"sort_order":90,"updated_at":"2026-10-24T18:30:23.464042+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm","title":"Lei nº 9.784/1999 (Processo Administrativo Federal), texto compilado"}],"reviewed_at":"2026-10-24T22:30:24.912384+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir do material de mapas mentais de Direito Administrativo (Strauss e Leite) da pasta Apostilas, com organização e destaques próprios, e conferido com o texto da Lei nº 9.784/1999 e da Constituição no Planalto. Os pontos de doutrina estão indicados como tal. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: redação própria após confronto dos temas dos arquivos enviados com a cobertura existente; escopo e fontes em Atualizações da lei. Exercícios didáticos catalogados separadamente, sem certificação de banca.","topic_label":"Processo administrativo","contest_name":"Polícia Federal","legal_review":{"scope":"Complemento e vinte exercícios de fixação revistos em 24/10/2026. As demais partes anteriores foram preservadas; esta data não certifica revisão nova de toda jurisprudência preexistente.","changes":[],"sources":[{"key":"l9784","url