do $guard$
declare p jsonb;r jsonb;m public.study_materials;e public.study_material_enrichments;active_ids jsonb;expected_ids jsonb;
begin
 select payload into p from admin_payload;
 if not exists(select 1 from public.user_roles where user_id=(p->>'actor')::uuid and role::text='admin') then raise exception 'Responsável de publicação não é administrador.'; end if;
 if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions se on se.id=t.edition_id join public.content_sources s on s.id=se.source_id where t.id=(p#>>'{syllabus_topic,id}')::uuid and t.topic_text=p#>>'{syllabus_topic,topic_text}' and t.content_status='current' and se.status='active' and s.url='https://conhecimento.fgv.br/sites/default/files/concursos/edital_delegado.22.12_0.pdf' and s.is_official and s.status='vigente') then raise exception 'Edital ou tópico deixou de ser válido.'; end if;
 if exists(select 1 from jsonb_array_elements(p->'sources') x join public.content_sources s on s.url=x->>'url' where s.id<>(x->>'id')::uuid or not s.is_official or s.status<>'vigente') then raise exception 'Fonte existente precisa de conciliação.'; end if;
 for r in select value from jsonb_array_elements(p->'rows') order by value#>>'{material,slug}' loop
  if jsonb_array_length(r#>'{material,quiz}')<>20 or jsonb_array_length(r#>'{material,practice_review,items}')<>20 then raise exception 'Prática incompleta.'; end if;
  if r#>>'{material,discipline}'<>'Direito Administrativo' or r#>>'{material,content_status}'<>'active' then raise exception 'Classificação inválida.'; end if;
  select * into m from public.study_materials where slug=r#>>'{material,slug}' for update;
  if r->>'kind'='new' then
   if found and not(to_jsonb(m) @> (r->'material')) then raise exception 'Novo material já cadastrado de forma diferente.'; end if;
   if exists(select 1 from public.study_materials x where lower(x.title)=lower(r#>>'{material,title}') and x.slug<>r#>>'{material,slug}' and x.content_status='active') then raise exception 'Título equivalente em outra rota.'; end if;
  else
   if not found or not(to_jsonb(m)=r->'expected_material' or to_jsonb(m) @> ((r->'material')-'updated_at'-'created_at')) then raise exception 'Alteração concorrente no material: %',r#>>'{material,slug}'; end if;
  end if;
  perform 1 from public.study_material_enrichments where material_slug=r#>>'{material,slug}' for update;
  select coalesce(jsonb_agg(id::text order by id::text),'[]') into active_ids from public.study_material_enrichments where material_slug=r#>>'{material,slug}' and status='active';
  select coalesce(jsonb_agg(x->>'id' order by x->>'id'),'[]') into expected_ids from jsonb_array_elements(r->'expected_active_enrichments') x;
  if active_ids<>expected_ids and active_ids<>jsonb_build_array(r#>>'{enrichment,id}') then raise exception 'Casos ativos alterados em concorrência.'; end if;
  if active_ids=expected_ids and exists(select 1 from jsonb_array_elements(r->'expected_active_enrichments') x left join public.study_material_enrichments y on y.id=(x->>'id')::uuid where y.id is null or to_jsonb(y)<>x) then raise exception 'Versão anterior de casos foi alterada.'; end if;
  select * into e from public.study_material_enrichments where id=(r#>>'{enrichment,id}')::uuid;
  if found and not(to_jsonb(e) @> (r->'enrichment')) then raise exception 'Nova versão de casos divergente.'; end if;
 end loop;
end $guard$;
insert into public.content_sources(id,source_type,title,issuer,url,status,is_official,checked_at,notes)
select (s->>'id')::uuid,s->>'source_type',s->>'title',s->>'issuer',s->>'url','vigente',true,(s->>'checked_at')::timestamptz,'Conferência do recorte do lote administrativo. SHA-256: '||(s->>'sha256')
from admin_payload p cross join lateral jsonb_array_elements(p.payload->'sources') s on conflict(url) do nothing;
insert into public.study_materials(id,slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_by,reviewed_at,quiz,flashcards,practice_review,legal_review) select m.id,m.slug,m.discipline,m.topic_label,m.sort_order,m.title,m.summary,m.body_md,m.contest_name,m.syllabus_topic_order,m.source_note,m.legal_basis,m.law_version_checked_at,m.content_status,m.reviewed_by,m.reviewed_at,m.quiz,m.flashcards,m.practice_review,m.legal_review from admin_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.study_materials,r->'material') m where r->>'kind'='new' on conflict(slug) do nothing;
update public.study_materials m set body_md=r#>>'{material,body_md}',source_note=r#>>'{material,source_note}',legal_basis=r#>'{material,legal_basis}',legal_review=r#>'{material,legal_review}',quiz=r#>'{material,quiz}',practice_review=r#>'{material,practice_review}',reviewed_at=(r#>>'{material,reviewed_at}')::timestamptz,reviewed_by=(r#>>'{material,reviewed_by}')::uuid
from admin_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r where r->>'kind'='update' and m.slug=r#>>'{material,slug}' and (m.body_md is distinct from r#>>'{material,body_md}' or m.legal_review is distinct from r#>'{material,legal_review}');
update public.study_material_enrichments e set status='archived' from admin_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r where e.material_slug=r#>>'{material,slug}' and e.status='active' and e.id<>(r#>>'{enrichment,id}')::uuid;
insert into public.study_material_enrichments(id,material_slug,version,source_body_sha256,content,sources,checked_at,status,reviewed_by,reviewed_at) select e.id,e.material_slug,e.version,e.source_body_sha256,e.content,e.sources,e.checked_at,e.status,e.reviewed_by,e.reviewed_at from admin_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.study_material_enrichments,r->'enrichment') e on conflict(material_slug,version) do nothing;
do $verify$
declare p jsonb;r jsonb;
begin
 select payload into p from admin_payload;
 for r in select value from jsonb_array_elements(p->'rows') loop
  if not exists(select 1 from public.study_materials m where m.slug=r#>>'{material,slug}' and to_jsonb(m) @> ((r->'material')-'updated_at'-'created_at')) then raise exception 'Falha na leitura final de material.'; end if;
  if not exists(select 1 from public.study_material_enrichments e where e.id=(r#>>'{enrichment,id}')::uuid and to_jsonb(e) @> (r->'enrichment')) then raise exception 'Falha na leitura final dos casos.'; end if;
  if (select count(*) from public.study_material_enrichments e where e.material_slug=r#>>'{material,slug}' and e.status='active')<>1 then raise exception 'Contagem de versões ativas inválida.'; end if;
 end loop;
end $verify$;
select count(*) as confirmed_materials,count(*) filter(where r->>'kind'='new') as new_materials,count(*) filter(where r->>'kind'='update') as updated_materials from admin_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r join public.study_materials m on m.slug=r#>>'{material,slug}';
commit;
